    private function is_portal_request_path() {
        $path = isset($_SERVER['REQUEST_URI']) ? (string) wp_unslash($_SERVER['REQUEST_URI']) : '';
        $path = trim((string) parse_url($path, PHP_URL_PATH), '/');
        return in_array($path, array('client', 'customer', 'ugyfel', 'agent', 'sales', 'sales-admin', 'lawyer'), true);
    }

    private function is_agent_portal_request() {
        return get_query_var('harmat_agent_portal') || $this->is_path_portal_slug('agent');
    }

    private function is_sales_portal_request() {
        return get_query_var('harmat_sales_portal') || $this->is_path_portal_slug('sales');
    }

    private function is_customer_portal_request() {
        return get_query_var('harmat_customer_portal') || $this->is_path_portal_slug('client') || $this->is_path_portal_slug('customer') || $this->is_path_portal_slug('ugyfel');
    }

    private function is_path_portal_slug($slug) {
        $path = isset($_SERVER['REQUEST_URI']) ? (string) wp_unslash($_SERVER['REQUEST_URI']) : '';
        $path = trim((string) parse_url($path, PHP_URL_PATH), '/');
        return $path === $slug;
    }

    public function disable_portal_caching() {
        if (!$this->is_portal_request_path()) {
            return;
        }

        foreach (array('DONOTCACHEPAGE', 'DONOTCACHEOBJECT', 'DONOTCACHEDB') as $constant) {
            if (!defined($constant)) {
                define($constant, true);
            }
        }
    }

    public function send_portal_nocache_headers() {
        if ($this->is_portal_request_path()) {
            nocache_headers();
        }
    }

    public function register_visit_tracking_route() {
        register_rest_route(self::VISIT_REST_NAMESPACE, '/visit', array(
            'methods' => 'POST',
            'callback' => array($this, 'track_public_visit'),
            'permission_callback' => '__return_true',
            'args' => array(
                'path' => array(
                    'required' => true,
                    'type' => 'string',
                ),
                'title' => array(
                    'required' => false,
                    'type' => 'string',
                ),
            ),
        ));

        register_rest_route(self::VISIT_REST_NAMESPACE, '/offer', array(
            'methods' => 'POST',
            'callback' => array($this, 'submit_public_offer'),
            'permission_callback' => '__return_true',
        ));
    }

    public function render_public_visit_tracker() {
        if (is_admin() || wp_doing_ajax() || is_user_logged_in() || $this->is_portal_request_path()) {
            return;
        }

        $endpoint = esc_url_raw(rest_url(self::VISIT_REST_NAMESPACE . '/visit'));
        ?>
        <script id="harmat-sales-visit-tracker" type="application/javascript" data-cfasync="false" data-no-optimize="1" data-noptimize="1">
        (function(){
            var endpoint = <?php echo wp_json_encode($endpoint); ?>;
            if (!endpoint || navigator.doNotTrack === "1" || window.doNotTrack === "1") return;
            function readConsent(){
                var found = document.cookie.split("; ").find(function(row){ return row.indexOf("harmat_cookie_consent_v1=") === 0; });
                if (!found) return null;
                try { return JSON.parse(decodeURIComponent(found.split("=").slice(1).join("="))); } catch(e){ return null; }
            }
            var consent = readConsent();
            if (!consent || !consent.analytics) return;
            var payload = JSON.stringify({
                path: window.location.pathname || "/",
                title: document.title || ""
            });
            try {
                if (navigator.sendBeacon) {
                    navigator.sendBeacon(endpoint, new Blob([payload], { type: "application/json" }));
                    return;
                }
                fetch(endpoint, {
                    method: "POST",
                    headers: { "Content-Type": "application/json" },
                    body: payload,
                    keepalive: true,
                    credentials: "omit"
                });
            } catch(e) {}
        })();
        </script>
        <?php
    }

    public function track_public_visit(WP_REST_Request $request) {
        $path = $this->normalize_visit_path((string) $request->get_param('path'));
        if ($path === '' || !$this->is_trackable_public_path($path) || $this->is_probable_bot_request()) {
            return rest_ensure_response(array('ok' => true, 'tracked' => false));
        }

        $date = current_time('Y-m-d');
        $title = sanitize_text_field((string) $request->get_param('title'));
        $title = mb_substr($title, 0, 90, 'UTF-8');
        $visitor = $this->daily_visit_hash($date);

        $stats = get_option(self::VISIT_STATS_OPTION, array());
        if (!is_array($stats)) {
            $stats = array();
        }
        if (!isset($stats[$date]) || !is_array($stats[$date])) {
            $stats[$date] = array(
                'pageviews' => 0,
                'visitors' => array(),
                'pages' => array(),
            );
        }

        $stats[$date]['pageviews'] = (int) ($stats[$date]['pageviews'] ?? 0) + 1;
        if ($visitor !== '') {
            $stats[$date]['visitors'][$visitor] = 1;
        }
        if (!isset($stats[$date]['pages'][$path]) || !is_array($stats[$date]['pages'][$path])) {
            $stats[$date]['pages'][$path] = array('views' => 0, 'title' => '');
        }
        $stats[$date]['pages'][$path]['views'] = (int) ($stats[$date]['pages'][$path]['views'] ?? 0) + 1;
        if ($title !== '') {
            $stats[$date]['pages'][$path]['title'] = $title;
        }

        $stats = $this->trim_visit_stats($stats);
        update_option(self::VISIT_STATS_OPTION, $stats, false);

        return rest_ensure_response(array('ok' => true, 'tracked' => true));
    }

    public function submit_public_offer(WP_REST_Request $request) {
        if ($this->is_probable_bot_request()) {
            return rest_ensure_response(array('success' => true, 'ignored' => true));
        }

        $posted = array();
        foreach (array(
            'your-name', 'your-email', 'your-phone', 'your-date', 'your-time', 'your-message',
            'selected-building', 'selected-floor', 'selected-apartment', 'selected-area',
            'selected-rooms', 'selected-price', 'selected-url', 'privacy-acceptance',
            'marketing-consent', 'marketing-consent[]', '_wpcf7',
            '_harmat_offer_nonce', 'harmat_company_url',
            'utm_source', 'utm_medium', 'utm_campaign', 'utm_content', 'utm_term',
            'landing_page', 'referrer', 'lead_source', 'source_url',
        ) as $key) {
            $posted[$key] = $request->get_param($key);
        }

        if ($this->cf7_posted_text($posted, 'harmat_company_url') !== '') {
            return rest_ensure_response(array('success' => true, 'ignored' => true));
        }

        if (!$this->public_offer_request_origin_allowed($request)) {
            return new WP_Error('harmat_offer_bad_origin', 'A küldés biztonsági ellenőrzése nem sikerült.', array('status' => 403));
        }

        $nonce = $this->cf7_posted_text($posted, '_harmat_offer_nonce');
        if ($nonce !== '' && !wp_verify_nonce($nonce, 'harmat_public_offer')) {
            return new WP_Error('harmat_offer_bad_nonce', 'A munkamenet lejárt. Kérjük, frissítse az oldalt és próbálja újra.', array('status' => 403));
        }

        $name = $this->cf7_posted_text($posted, 'your-name');
        $email = sanitize_email($this->cf7_posted_text($posted, 'your-email'));
        $phone = $this->cf7_posted_text($posted, 'your-phone');
        $date = $this->cf7_posted_text($posted, 'your-date');
        $time = $this->cf7_posted_text($posted, 'your-time');
        $message = $this->limit_text($this->cf7_posted_textarea($posted, 'your-message'), 200);
        $apartment = $this->cf7_posted_text($posted, 'selected-apartment');
        $privacy = $this->cf7_posted_text($posted, 'privacy-acceptance');

        if ($name === '' || !is_email($email) || $phone === '' || $date === '' || $privacy === '') {
            return new WP_Error(
                'harmat_offer_required',
                'Kérjük, töltse ki a nevet, e-mail címet, dátumot, telefonszámot, és fogadja el az adatkezelési tájékoztatót.',
                array('status' => 400)
            );
        }

        if (!$this->public_offer_rate_allowed($email)) {
            return new WP_Error(
                'harmat_offer_rate_limited',
                'Köszönjük. Kérjük, várjon néhány percet az újabb küldés előtt.',
                array('status' => 429)
            );
        }

        if (!$this->public_offer_duplicate_allowed($email, $phone)) {
            return new WP_Error(
                'harmat_offer_duplicate_limited',
                'Köszönjük, az adataival nemrég már érkezett érdeklődés. Kérjük, várjon néhány percet az újabb küldés előtt.',
                array('status' => 429)
            );
        }

        $property_id = $apartment ? $this->property_id_by_title($apartment) : 0;
        $url = $this->cf7_posted_text($posted, 'selected-url');
        if (!$property_id && $url) {
            $property_id = url_to_postid($url);
        }
        if (!$apartment && $property_id && get_post_type($property_id) === 'property') {
            $apartment = get_the_title($property_id);
        }

        $stored = array(
            'your-name' => $name,
            'your-email' => $email,
            'your-phone' => $phone,
            'your-date' => $date,
            'your-time' => $time,
            'your-message' => $message,
            'selected-building' => $this->cf7_posted_text($posted, 'selected-building'),
            'selected-floor' => $this->cf7_posted_text($posted, 'selected-floor'),
            'selected-apartment' => $apartment,
            'selected-area' => $this->cf7_posted_text($posted, 'selected-area'),
            'selected-rooms' => $this->cf7_posted_text($posted, 'selected-rooms'),
            'selected-price' => $this->cf7_posted_text($posted, 'selected-price'),
            'selected-url' => $url,
            'privacy-acceptance' => '1',
            'marketing-consent' => $this->cf7_posted_text($posted, 'marketing-consent') ?: $this->cf7_posted_text($posted, 'marketing-consent[]'),
            'source' => esc_url_raw($request->get_param('source_url') ?: wp_get_referer()),
            'utm_source' => $this->cf7_posted_text($posted, 'utm_source'),
            'utm_medium' => $this->cf7_posted_text($posted, 'utm_medium'),
            'utm_campaign' => $this->cf7_posted_text($posted, 'utm_campaign'),
            'utm_content' => $this->cf7_posted_text($posted, 'utm_content'),
            'utm_term' => $this->cf7_posted_text($posted, 'utm_term'),
            'landing_page' => esc_url_raw($this->cf7_posted_text($posted, 'landing_page')),
            'referrer' => esc_url_raw($this->cf7_posted_text($posted, 'referrer')),
            'lead_source' => $this->cf7_posted_text($posted, 'lead_source') ?: 'website',
            'security' => array(
                'nonce' => $nonce !== '' ? 'verified' : 'not_present',
                'origin' => 'verified',
                'honeypot' => 'empty',
            ),
        );

        $stored = $this->complete_offer_property_data($stored, $property_id);
        if ($stored['your-message'] === '' && $stored['selected-apartment'] !== '') {
            $stored['your-message'] = 'A ' . $stored['selected-apartment'] . ' lakás iránt érdeklődöm.';
        }

        $hash = $this->cf7_offer_submission_hash($stored);
        $post_id = $this->existing_cf7_offer_inquiry_id($hash, $stored);

        if (!$post_id) {
            $post_id = wp_insert_post(array(
                'post_type' => 'harmat_offer_lead',
                'post_status' => 'private',
                'post_title' => 'Magán: ' . $name . ' - ' . current_time('ymd-His'),
                'post_content' => $stored['your-message'],
            ), true);

            if (is_wp_error($post_id) || !$post_id) {
                return new WP_Error('harmat_offer_save_failed', 'A küldés nem sikerült. Kérjük, próbálja újra.', array('status' => 500));
            }
        }

        $crm = get_post_meta($post_id, '_harmat_offer_crm_code', true);
        if (!$crm) {
            $crm = 'WEB-' . current_time('Ymd') . '-' . str_pad((string) $post_id, 5, '0', STR_PAD_LEFT);
        }

        update_post_meta($post_id, '_harmat_offer_posted', $stored);
        update_post_meta($post_id, '_harmat_offer_email', $email);
        update_post_meta($post_id, '_harmat_offer_phone', $phone);
        update_post_meta($post_id, '_harmat_offer_apartment', $stored['selected-apartment']);
        update_post_meta($post_id, '_harmat_offer_date', $date);
        update_post_meta($post_id, '_harmat_offer_time', $time);
        update_post_meta($post_id, '_harmat_offer_crm_code', $crm);
        update_post_meta($post_id, '_harmat_offer_mail_status', 'queued');
        update_post_meta($post_id, '_harmat_offer_mail_checked_at', current_time('mysql'));
        update_post_meta($post_id, '_harmat_cf7_submission_hash', $hash);
        update_post_meta($post_id, '_harmat_offer_cf7_form_id', absint($this->cf7_posted_text($posted, '_wpcf7')));
        update_post_meta($post_id, '_harmat_offer_tracking', array(
            'utm_source' => $stored['utm_source'],
            'utm_medium' => $stored['utm_medium'],
            'utm_campaign' => $stored['utm_campaign'],
            'utm_content' => $stored['utm_content'],
            'utm_term' => $stored['utm_term'],
            'landing_page' => $stored['landing_page'],
            'referrer' => $stored['referrer'],
            'lead_source' => $stored['lead_source'],
        ));
        update_post_meta($post_id, '_harmat_offer_security', $stored['security']);

        if (!wp_next_scheduled(self::SALES_OFFER_MAIL_HOOK, array((int) $post_id))) {
            wp_schedule_single_event(time() + 1, self::SALES_OFFER_MAIL_HOOK, array((int) $post_id));
            spawn_cron(time());
        }

        return rest_ensure_response(array(
            'success' => true,
            'id' => (int) $post_id,
            'crm' => $crm,
            'message' => 'Köszönjük, megkaptuk érdeklődését.',
        ));
    }

    private function normalize_visit_path($path) {
        $path = (string) parse_url($path, PHP_URL_PATH);
        $path = '/' . ltrim($path, '/');
        $path = preg_replace('~/+~', '/', $path);
        return $path ?: '/';
    }

    private function is_trackable_public_path($path) {
        $path = trim((string) $path, '/');
        if ($path === '') {
            return true;
        }
        foreach (array('sales', 'agent', 'client', 'customer', 'ugyfel', 'sales-admin', 'wp-admin', 'wp-login.php', 'wp-json') as $private_prefix) {
            if ($path === $private_prefix || strpos($path, $private_prefix . '/') === 0) {
                return false;
            }
        }
        return true;
    }

    private function is_probable_bot_request() {
        $ua = isset($_SERVER['HTTP_USER_AGENT']) ? strtolower((string) wp_unslash($_SERVER['HTTP_USER_AGENT'])) : '';
        if ($ua === '') {
            return true;
        }
        foreach (array('bot', 'crawl', 'spider', 'slurp', 'facebookexternalhit', 'whatsapp', 'telegrambot', 'preview', 'pingdom', 'uptimerobot') as $needle) {
            if (strpos($ua, $needle) !== false) {
                return true;
            }
        }
        return false;
    }

    private function daily_visit_hash($date) {
        $ip = isset($_SERVER['REMOTE_ADDR']) ? (string) wp_unslash($_SERVER['REMOTE_ADDR']) : '';
        $ua = isset($_SERVER['HTTP_USER_AGENT']) ? substr((string) wp_unslash($_SERVER['HTTP_USER_AGENT']), 0, 180) : '';
        if ($ip === '' && $ua === '') {
            return '';
        }
        return hash_hmac('sha256', $date . '|' . $ip . '|' . $ua, wp_salt('auth'));
    }

    private function trim_visit_stats($stats) {
        krsort($stats);
        $stats = array_slice($stats, 0, 30, true);
        foreach ($stats as $date => $day) {
            if (!is_array($day)) {
                unset($stats[$date]);
                continue;
            }
            if (!empty($day['visitors']) && is_array($day['visitors']) && count($day['visitors']) > 5000) {
                $day['visitors'] = array_slice($day['visitors'], -5000, null, true);
            }
            if (!empty($day['pages']) && is_array($day['pages'])) {
                uasort($day['pages'], function($a, $b) {
                    return ((int) ($b['views'] ?? 0)) <=> ((int) ($a['views'] ?? 0));
                });
                $day['pages'] = array_slice($day['pages'], 0, 80, true);
            }
            $stats[$date] = $day;
        }
        return $stats;
    }

    private static function next_reminder_timestamp($hour = 8) {
        $timezone = function_exists('wp_timezone') ? wp_timezone() : new DateTimeZone('UTC');
        $now = new DateTimeImmutable('now', $timezone);
        $target = $now->setTime((int) $hour, 0, 0);
        if ($target <= $now) {
            $target = $target->modify('+1 day');
        }
        return $target->getTimestamp();
    }

    public static function schedule_task_reminder_event() {
        if (!wp_next_scheduled(self::SALES_REMINDER_HOOK)) {
            wp_schedule_event(self::next_reminder_timestamp(8), 'daily', self::SALES_REMINDER_HOOK);
        }
    }

    public function schedule_daily_task_reminder() {
        self::schedule_task_reminder_event();
    }

    public function remove_lakaskereso_legacy_filters() {
        if (is_admin() || wp_doing_ajax() || !(is_front_page() || is_page('lakaskereso'))) {
            return;
        }

        ob_start(function($html) {
            $html = preg_replace('~<div class="epl-premium-filter-wrapper">.*?</form>\s*</div>~is', '', $html);
            return $html;
        });
    }

    public static function activate() {
        add_role(self::ROLE_MANAGER, 'Harmat Sales Manager', array(
            'read' => true,
            self::CAP_VIEW => true,
            self::CAP_MANAGE => true,
            self::CAP_DELETE => true,
        ));

        add_role(self::ROLE_SALES, 'Harmat Sales Staff', array(
            'read' => true,
            self::CAP_VIEW => true,
        ));

        add_role(self::ROLE_BROKER, 'Harmat Broker Viewer', array(
            'read' => true,
            self::CAP_VIEW => true,
        ));

        add_role(self::ROLE_CUSTOMER, 'Harmat Customer Owner', array(
            'read' => true,
            self::CAP_CUSTOMER => true,
        ));

        foreach (array('administrator') as $role_name) {
            $role = get_role($role_name);
            if ($role) {
                $role->add_cap(self::CAP_VIEW);
                $role->add_cap(self::CAP_MANAGE);
                $role->add_cap(self::CAP_DELETE);
                $role->add_cap(self::CAP_CUSTOMER);
            }
        }

        flush_rewrite_rules();
        self::schedule_task_reminder_event();
    }

    public static function deactivate() {
        wp_clear_scheduled_hook(self::SALES_REMINDER_HOOK);
        flush_rewrite_rules();
    }

    public function ensure_roles() {
        if (!get_role(self::ROLE_MANAGER)) {
            add_role(self::ROLE_MANAGER, 'Harmat Sales Manager', array(
                'read' => true,
                self::CAP_VIEW => true,
                self::CAP_MANAGE => true,
                self::CAP_DELETE => true,
            ));
        }
        if (!get_role(self::ROLE_SALES)) {
            add_role(self::ROLE_SALES, 'Harmat Sales Staff', array(
                'read' => true,
                self::CAP_VIEW => true,
            ));
        }
        if (!get_role(self::ROLE_BROKER)) {
            add_role(self::ROLE_BROKER, 'Harmat Broker Viewer', array(
                'read' => true,
                self::CAP_VIEW => true,
            ));
        }
        if (!get_role(self::ROLE_CUSTOMER)) {
            add_role(self::ROLE_CUSTOMER, 'Harmat Customer Owner', array(
                'read' => true,
                self::CAP_CUSTOMER => true,
            ));
        }

        $customer_role = get_role(self::ROLE_CUSTOMER);
        if ($customer_role && !$customer_role->has_cap(self::CAP_CUSTOMER)) {
            $customer_role->add_cap(self::CAP_CUSTOMER);
        }
        $manager_role = get_role(self::ROLE_MANAGER);
        if ($manager_role) {
            $manager_role->add_cap(self::CAP_VIEW);
            $manager_role->add_cap(self::CAP_MANAGE);
            $manager_role->add_cap(self::CAP_DELETE);
        }
        $sales_role = get_role(self::ROLE_SALES);
        if ($sales_role) {
            $sales_role->add_cap(self::CAP_VIEW);
            $sales_role->remove_cap(self::CAP_MANAGE);
            $sales_role->remove_cap(self::CAP_DELETE);
        }
        $broker_role = get_role(self::ROLE_BROKER);
        if ($broker_role) {
            $broker_role->add_cap(self::CAP_VIEW);
            $broker_role->remove_cap(self::CAP_MANAGE);
            $broker_role->remove_cap(self::CAP_DELETE);
        }

        foreach (array('administrator') as $role_name) {
            $role = get_role($role_name);
            if ($role) {
                $role->add_cap(self::CAP_VIEW);
                $role->add_cap(self::CAP_MANAGE);
                $role->add_cap(self::CAP_DELETE);
                $role->add_cap(self::CAP_CUSTOMER);
            }
        }
    }

    public function redirect_room_filter_pages() {
        if (is_admin() || wp_doing_ajax()) {
            return;
        }

        $rooms = '';
        $path = isset($_SERVER['REQUEST_URI']) ? (string) wp_unslash($_SERVER['REQUEST_URI']) : '';
        $path = trim((string) parse_url($path, PHP_URL_PATH), '/');
        if ($path === 'studio-apartman') {
            $rooms = '1';
        }
        if (preg_match('/^([1-5])-szobas$/', $path, $match)) {
            $rooms = $match[1];
        }

        if (!$rooms && isset($_GET['location'])) {
            $location = sanitize_key(wp_unslash($_GET['location']));
            if (preg_match('/^([1-5])-szobas$/', $location, $match)) {
                $rooms = $match[1];
            }
        }

        if (!$rooms) {
            return;
        }

        wp_safe_redirect(add_query_arg('rooms', $rooms, home_url('/lakaskereso/')), 301);
        exit;
    }

