            $this->handle_sales_export();
            exit;
        }

        $lang = $this->active_sales_language();
        if ($this->current_user_must_change_password()) {
            ob_start();
            $this->render_initial_password_change('sales', $lang);
            echo $this->strip_portal_footer_output(ob_get_clean());
