    private function handle_sales_export() {
        if (!$this->is_sales_manager_user()) {
            wp_die('Nincs jogosultsag exportalashoz.');
        }

        $export = isset($_GET['sales_export']) ? sanitize_key(wp_unslash($_GET['sales_export'])) : '';
        if ($export === 'payments_summary') {
            check_admin_referer('harmat_sales_export_payments_summary');
            $this->log_sales_activity('export_payments_summary', 'export', 0, '导出付款汇总 XLSX');
            $this->export_sales_payments_summary_xlsx();
            return;
        }
        if ($export === 'payments_plan') {
            check_admin_referer('harmat_sales_export_payments_plan');
            $this->log_sales_activity('export_payments_plan', 'export', 0, '导出付款节点 XLSX');
            $this->export_sales_payments_plan_xlsx();
            return;
        }
        if ($export === 'deals_table') {
            check_admin_referer('harmat_sales_export_deals_table');
            $this->log_sales_activity('export_deals_table', 'export', 0, '导出销售跟单表格 Excel');
            $this->export_sales_deals_table_excel();
            return;
        }
        if ($export === 'activity_log') {
            check_admin_referer('harmat_sales_export_activity_log');
            $this->log_sales_activity('export_activity_log', 'export', 0, '导出动作记录 CSV');
            $this->export_sales_activity_log_csv();
            return;
        }

        wp_die('Hibás export kérés.');
    }

