    public function register_menu() {
        add_menu_page(
            'Harmat销售管理',
            'Harmat销售管理',
            self::CAP_VIEW,
            self::PAGE_SLUG,
            array($this, 'render_page'),
            'dashicons-chart-line',
            3
        );
    }

    public function admin_assets($hook) {
        if ($hook !== 'toplevel_page_' . self::PAGE_SLUG) {
            return;
        }

        wp_register_style('harmat-sales-manager-admin', false, array(), self::VERSION);
        wp_enqueue_style('harmat-sales-manager-admin');
        wp_add_inline_style('harmat-sales-manager-admin', $this->css());

        wp_register_script('harmat-sales-manager-admin', false, array(), self::VERSION, true);
        wp_enqueue_script('harmat-sales-manager-admin');
        wp_add_inline_script('harmat-sales-manager-admin', $this->js());
    }

    public function frontend_assets() {
        if (is_admin()) {
            return;
        }

        if (!$this->should_load_frontend_assets()) {
            return;
        }

        if (is_singular('property')) {
            $items = $this->frontend_sales_data(array(get_queried_object_id()));
        } else {
            $room_filter = $this->requested_public_room_filter();
            if ($room_filter) {
                $room_ids = $this->public_property_ids_by_rooms($room_filter);
                $items = $room_ids ? $this->frontend_sales_data($room_ids) : array();
            } else {
                $items = $this->frontend_sales_data();
            }
        }
        if (!$items) {
            return;
        }

        wp_register_style('harmat-sales-manager-front', false, array(), self::VERSION);
        wp_enqueue_style('harmat-sales-manager-front');
        wp_add_inline_style('harmat-sales-manager-front', $this->frontend_css());

        wp_register_script('harmat-sales-manager-front', false, array(), self::VERSION, true);
        wp_enqueue_script('harmat-sales-manager-front');
        wp_add_inline_script(
            'harmat-sales-manager-front',
            'window.harmatSalesFront=' . wp_json_encode(array('items' => $items), JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) . ';',
            'before'
        );
        wp_add_inline_script('harmat-sales-manager-front', $this->frontend_js());
    }

    private function should_load_frontend_assets() {
        if (is_front_page() || is_singular('property') || is_post_type_archive('property') || is_tax(array('location', 'tax_feature'))) {
            return true;
        }

        $path = isset($_SERVER['REQUEST_URI']) ? (string) wp_unslash($_SERVER['REQUEST_URI']) : '';
        $path = trim((string) parse_url($path, PHP_URL_PATH), '/');
        if ($path === 'virtualis-lakasvalaszto-elso-utem') {
            return false;
        }
        if (strpos($path, 'virtualis-lakasvalaszto') === 0) {
            return true;
        }

        if (is_page()) {
            $slug = get_post_field('post_name', get_queried_object_id());
            return in_array($slug, array('ajanlatkeres', 'idopont-foglalas', '1-szobas', '2-szobas', '3-szobas', '4-szobas', '5-szobas'), true);
        }

        return false;
    }

    private function requested_public_room_filter() {
        if (!is_page('lakaskereso') || empty($_GET['rooms'])) {
            return '';
        }

        $rooms = sanitize_text_field(wp_unslash($_GET['rooms']));
        return preg_match('/^[1-5]$/', $rooms) ? $rooms : '';
    }

    private function public_property_ids_by_rooms($rooms) {
        $posts = get_posts(array(
            'post_type' => 'property',
            'post_status' => 'publish',
            'posts_per_page' => -1,
            'fields' => 'ids',
            'orderby' => 'title',
            'order' => 'ASC',
            'meta_query' => array(
                array(
                    'key' => 'property_rooms',
                    'value' => (string) $rooms,
                    'compare' => '=',
                ),
            ),
        ));

        return array_map('absint', $posts);
    }

    public function frontend_structured_data() {
        if (!is_singular('property')) {
            return;
        }

        $post_id = get_queried_object_id();
        $price = (int) get_post_meta($post_id, 'property_price', true);
        $sales_area = $this->get_sales_area($post_id);
        $status = $this->sales_status($post_id);
        $hide_price = get_post_meta($post_id, '_harmat_hide_front_price', true) === 'yes';
        $availability = $status === 'sold' ? 'https://schema.org/SoldOut' : 'https://schema.org/InStock';

        if ($hide_price || !$price || !$sales_area) {
            return;
        }

        $data = array(
            '@context' => 'https://schema.org',
            '@type' => 'Apartment',
            'name' => get_the_title($post_id),
            'url' => get_permalink($post_id),
            'floorSize' => array(
                '@type' => 'QuantitativeValue',
                'value' => $sales_area,
                'unitText' => 'MTK',
            ),
            'offers' => array(
                '@type' => 'Offer',
                'price' => $price,
                'priceCurrency' => 'HUF',
                'availability' => $availability,
                'url' => get_permalink($post_id),
            ),
        );

        echo '<script type="application/ld+json" class="harmat-sales-structured-data">' . wp_json_encode($data, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) . '</script>' . "\n";
    }

    public function prefill_cf7_property_data($posted_data) {
        if (!is_array($posted_data)) {
            return $posted_data;
        }

        $has_property_fields = array_intersect(
            array('selected-building', 'selected-floor', 'selected-apartment', 'selected-area', 'selected-rooms', 'selected-price', 'selected-url'),
            array_keys($posted_data)
        );
        if (!$has_property_fields || !empty($posted_data['selected-apartment'])) {
            return $posted_data;
        }

        $referer = wp_get_referer();
        if (!$referer && !empty($_SERVER['HTTP_REFERER'])) {
            $referer = esc_url_raw(wp_unslash($_SERVER['HTTP_REFERER']));
        }

        $post_id = $referer ? url_to_postid($referer) : 0;
        if (!$post_id || get_post_type($post_id) !== 'property') {
            return $posted_data;
        }

        $price = (int) get_post_meta($post_id, 'property_price', true);
        $sales_area = $this->get_sales_area($post_id);
        $rooms = get_post_meta($post_id, 'property_rooms', true);
        $bedrooms = get_post_meta($post_id, 'property_bedrooms', true);

        $posted_data['selected-building'] = get_post_meta($post_id, 'property_address_street', true);
        $posted_data['selected-floor'] = get_post_meta($post_id, 'property_address_street_number', true);
        $posted_data['selected-apartment'] = get_the_title($post_id);
        $posted_data['selected-area'] = $this->format_area($sales_area) . ' m²';
        $posted_data['selected-rooms'] = trim($rooms . ' szoba' . ($bedrooms ? ' / ' . $bedrooms . ' háló' : ''));
        $posted_data['selected-price'] = $this->format_money($price) . ' Ft';
        $posted_data['selected-url'] = get_permalink($post_id);

        if (empty($posted_data['your-message'])) {
            $posted_data['your-message'] = 'A ' . get_the_title($post_id) . ' lakás iránt érdeklődöm.';
        }

        return $posted_data;
    }

    public function capture_cf7_offer_inquiry_sent($contact_form) {
        $this->capture_cf7_offer_inquiry($contact_form, 'sent');
    }

    public function capture_cf7_offer_inquiry_failed($contact_form) {
        $this->capture_cf7_offer_inquiry($contact_form, 'failed');
    }

    private function technical_document_url() {
        return home_url('/wp-content/uploads/2026/06/harmat-lakopark-muszaki-leiras.pdf');
    }

    private function u($escaped) {
        $decoded = json_decode('"' . (string) $escaped . '"');
        return is_string($decoded) ? $decoded : (string) $escaped;
    }

    public function send_public_offer_mail($post_id) {
        $post_id = absint($post_id);
        if (!$post_id || get_post_type($post_id) !== 'harmat_offer_lead') {
            return;
        }

        update_post_meta($post_id, '_harmat_offer_mail_status', 'sending');
        update_post_meta($post_id, '_harmat_offer_mail_started_at', current_time('mysql'));

        $data = $this->offer_inquiry_data($post_id);
        $crm = get_post_meta($post_id, '_harmat_offer_crm_code', true);
        $name = $data['name'];
        $email = sanitize_email($data['email']);
        $apartment = $data['apartment'];
        $message = $data['message'];

        $headers = array('Content-Type: text/html; charset=UTF-8');
        if ($email) {
            $headers[] = 'Reply-To: ' . $name . ' <' . $email . '>';
        }

        $sales_rows = array(
            'CRM' => $crm,
            'Ügyfél' => $name,
            'E-mail' => $email,
            'Telefon' => $data['phone'],
            'Lakás' => $apartment,
            'Alapterület' => $data['area'],
            'Szoba' => $data['rooms'],
            'Ár' => $data['price'],
            'Időpont' => trim($data['date'] . ' ' . $data['time']),
            'Link' => $data['property_url'],
            'Üzenet' => nl2br(esc_html($message ?: '-')),
        );

        $sales_sent = wp_mail(
            self::SALES_REMINDER_EMAIL,
            'Harmat Lakópark - új ajánlatkérés: ' . ($apartment ?: 'lakás'),
            $this->offer_mail_template('Új ajánlatkérés érkezett', $sales_rows, 'A kérés bekerült a Harmat sales rendszerbe.'),
            $headers
        );
        if ($sales_sent) {
            update_post_meta($post_id, '_harmat_offer_sales_mail_sent_at', current_time('mysql'));
            delete_post_meta($post_id, '_harmat_offer_sales_mail_error');
        } else {
            update_post_meta($post_id, '_harmat_offer_sales_mail_error', 'wp_mail returned false');
        }

        $customer_sent = false;
        if ($email) {
            $customer_rows = array(
                'Lakás' => $apartment,
                'Alapterület' => $data['area'],
                'Szoba' => $data['rooms'],
                'Árinformáció' => $data['price'],
                'Időpont' => trim($data['date'] . ' ' . $data['time']),
                'Azonosító' => $crm,
                $this->u('M\u0171szaki le\u00edr\u00e1s') => $this->technical_document_url(),
            );
            $customer_sent = wp_mail(
                $email,
                'Harmat Lakópark - ajánlatkérés visszaigazolása',
                $this->offer_mail_template(
                    'Köszönjük érdeklődését',
                    $customer_rows,
                    'Értékesítési csapatunk hamarosan felveszi Önnel a kapcsolatot.',
                    array(
                        array(
                            'label' => $this->u('M\u0171szaki le\u00edr\u00e1s megnyit\u00e1sa'),
                            'url' => $this->technical_document_url(),
                        ),
                    )
                ),
                array('Content-Type: text/html; charset=UTF-8')
            );
            if ($customer_sent) {
                update_post_meta($post_id, '_harmat_offer_customer_mail_sent_at', current_time('mysql'));
                delete_post_meta($post_id, '_harmat_offer_customer_mail_error');
            } else {
                update_post_meta($post_id, '_harmat_offer_customer_mail_error', 'wp_mail returned false');
            }
        }

        if ($sales_sent && (!$email || $customer_sent)) {
            $status = 'sent';
        } elseif ($sales_sent || $customer_sent) {
            $status = 'partial';
        } else {
            $status = 'failed';
        }

        update_post_meta($post_id, '_harmat_offer_mail_status', $status);
        update_post_meta($post_id, '_harmat_offer_mail_checked_at', current_time('mysql'));
    }

    public function recover_stuck_public_offer_mails() {
        if ((defined('WP_CLI') && WP_CLI) || wp_doing_cron()) {
            return;
        }

        $lock_key = 'harmat_offer_mail_recovery_lock';
        if (get_transient($lock_key)) {
            return;
        }
        set_transient($lock_key, '1', 2 * MINUTE_IN_SECONDS);

        $cutoff = date('Y-m-d H:i:s', current_time('timestamp') - 120);
        $ids = get_posts(array(
            'post_type' => 'harmat_offer_lead',
            'post_status' => 'private',
            'fields' => 'ids',
            'posts_per_page' => 3,
            'orderby' => 'date',
            'order' => 'ASC',
            'meta_query' => array(
                array(
                    'key' => '_harmat_offer_mail_status',
                    'value' => 'queued',
                    'compare' => '=',
                ),
            ),
            'date_query' => array(
                array(
                    'before' => $cutoff,
                    'inclusive' => true,
                ),
            ),
        ));

        foreach ($ids as $id) {
            $id = absint($id);
            if (!$id || wp_next_scheduled(self::SALES_OFFER_MAIL_HOOK, array($id))) {
                continue;
            }
            update_post_meta($id, '_harmat_offer_mail_status', 'retrying');
            update_post_meta($id, '_harmat_offer_mail_retry_at', current_time('mysql'));
            $this->send_public_offer_mail($id);
        }
    }

    private function complete_offer_property_data($stored, $property_id) {
        if ($property_id && get_post_type($property_id) === 'property') {
            if (empty($stored['selected-building'])) {
                $stored['selected-building'] = get_post_meta($property_id, 'property_address_street', true);
            }
            if (empty($stored['selected-floor'])) {
                $stored['selected-floor'] = get_post_meta($property_id, 'property_address_street_number', true);
            }
            if (empty($stored['selected-apartment'])) {
                $stored['selected-apartment'] = get_the_title($property_id);
            }
            if (empty($stored['selected-area'])) {
                $stored['selected-area'] = str_replace('.', ',', $this->format_area($this->get_sales_area($property_id))) . ' m²';
            }
            if (empty($stored['selected-rooms'])) {
                $rooms = get_post_meta($property_id, 'property_rooms', true);
                $bedrooms = get_post_meta($property_id, 'property_bedrooms', true);
                $stored['selected-rooms'] = trim($rooms . ' szoba' . ($bedrooms ? ' / ' . $bedrooms . ' háló' : ''));
            }
            if (empty($stored['selected-price'])) {
                $price = (int) get_post_meta($property_id, 'property_price', true);
                $hide_price = get_post_meta($property_id, '_harmat_hide_front_price', true) === 'yes';
                $stored['selected-price'] = (!$hide_price && $price) ? $this->format_money($price) . ' Ft' : 'Ár egyeztetés alapján';
            }
            if (empty($stored['selected-url'])) {
                $stored['selected-url'] = get_permalink($property_id);
            }
        }

        return $stored;
    }

    private function public_offer_rate_allowed($email) {
        $ip = isset($_SERVER['REMOTE_ADDR']) ? sanitize_text_field(wp_unslash($_SERVER['REMOTE_ADDR'])) : '';
        $key = 'harmat_offer_rate_' . md5($ip . '|' . strtolower((string) $email));
        $count = (int) get_transient($key);
        if ($count >= 12) {
            return false;
        }
        set_transient($key, $count + 1, 10 * MINUTE_IN_SECONDS);
        return true;
    }

    private function public_offer_duplicate_allowed($email, $phone) {
        $email = strtolower(trim((string) $email));
        $phone = preg_replace('/\D+/', '', (string) $phone);
        $fingerprint = trim($email . '|' . $phone, '|');
        if ($fingerprint === '') {
            return true;
        }

        $key = 'harmat_offer_duplicate_' . md5($fingerprint);
        if (get_transient($key)) {
            return false;
        }

        set_transient($key, 1, 3 * MINUTE_IN_SECONDS);
        return true;
    }

    private function public_offer_request_origin_allowed(WP_REST_Request $request) {
        $site_host = wp_parse_url(home_url('/'), PHP_URL_HOST);
        if (!$site_host) {
            return true;
        }

        foreach (array('HTTP_ORIGIN', 'HTTP_REFERER') as $server_key) {
            $raw = isset($_SERVER[$server_key]) ? (string) wp_unslash($_SERVER[$server_key]) : '';
            if ($raw === '') {
                continue;
            }
            $host = wp_parse_url($raw, PHP_URL_HOST);
            if ($host && strcasecmp($host, $site_host) !== 0) {
                return false;
            }
        }

        $source_url = (string) $request->get_param('source_url');
        if ($source_url !== '') {
            $source_host = wp_parse_url($source_url, PHP_URL_HOST);
            if ($source_host && strcasecmp($source_host, $site_host) !== 0) {
                return false;
            }
        }

        return true;
    }

    private function offer_mail_template($title, $rows, $lead, $actions = array()) {
        $html = '<div style="font-family:Arial,sans-serif;color:#253137;background:#fbf5e8;padding:24px">';
        $html .= '<div style="max-width:680px;margin:auto;background:#fffaf3;border:1px solid #ead8b8;padding:24px">';
        $html .= '<h1 style="font-family:Georgia,serif;font-weight:400;color:#253137;margin:0 0 10px">' . esc_html($title) . '</h1>';
        $html .= '<p style="color:#65717a;margin:0 0 18px">' . esc_html($lead) . '</p>';
        $html .= '<table style="width:100%;border-collapse:collapse">';
        foreach ($rows as $label => $value) {
            $value = (string) $value;
            $html .= '<tr><td style="width:34%;padding:10px;border-top:1px solid #ead8b8;color:#a8762d;font-weight:bold">' . esc_html($label) . '</td><td style="padding:10px;border-top:1px solid #ead8b8">' . (strpos($value, '<br') !== false ? $value : esc_html($value)) . '</td></tr>';
        }
        $html .= '</table>';
        if (is_array($actions) && $actions) {
            $html .= '<div style="margin-top:20px">';
            foreach ($actions as $action) {
                if (empty($action['url']) || empty($action['label'])) {
                    continue;
                }
                $html .= '<a href="' . esc_url($action['url']) . '" target="_blank" rel="noopener" style="display:inline-block;margin:0 10px 10px 0;padding:12px 18px;border-radius:999px;background:#253137;color:#fff;text-decoration:none;font-weight:bold">' . esc_html($action['label']) . '</a>';
            }
            $html .= '</div>';
        }
        $html .= '</div></div>';
        return $html;
    }

    private function capture_cf7_offer_inquiry($contact_form, $mail_status = 'sent', $submission = null) {
        if (!$this->is_offer_cf7_submission($contact_form)) {
            return;
        }

        $posted = $this->cf7_submission_posted_data($submission);
        if (!$posted) {
            return;
        }

        $name = $this->cf7_posted_text($posted, 'your-name');
        $email = sanitize_email($this->cf7_posted_text($posted, 'your-email'));
        $phone = $this->cf7_posted_text($posted, 'your-phone');
        $apartment = $this->cf7_posted_text($posted, 'selected-apartment');
        $date = $this->cf7_posted_text($posted, 'your-date');
        $time = $this->cf7_posted_text($posted, 'your-time');
        $message = $this->limit_text($this->cf7_posted_textarea($posted, 'your-message'), 200);

        if ($name === '' || !is_email($email) || $phone === '') {
            return;
        }

        $property_id = $apartment ? $this->property_id_by_title($apartment) : 0;
        if (!$property_id) {
            $url = $this->cf7_posted_text($posted, 'selected-url');
            $property_id = $url ? url_to_postid($url) : 0;
        }
        if (!$apartment && $property_id && get_post_type($property_id) === 'property') {
            $apartment = get_the_title($property_id);
        }

        $stored = array(
            'your-name' => $name,
            'your-email' => $email,
            'your-phone' => $phone,
            'your-date' => $date,
            'your-time' => $time,
            'your-message' => $message,
            'selected-building' => $this->cf7_posted_text($posted, 'selected-building'),
            'selected-floor' => $this->cf7_posted_text($posted, 'selected-floor'),
            'selected-apartment' => $apartment,
            'selected-area' => $this->cf7_posted_text($posted, 'selected-area'),
            'selected-rooms' => $this->cf7_posted_text($posted, 'selected-rooms'),
            'selected-price' => $this->cf7_posted_text($posted, 'selected-price'),
            'selected-url' => $this->cf7_posted_text($posted, 'selected-url'),
            'privacy-acceptance' => $this->cf7_posted_text($posted, 'privacy-acceptance') ? '1' : '',
            'marketing-consent' => $this->cf7_posted_text($posted, 'marketing-consent'),
            'source' => esc_url_raw(wp_get_referer() ?: (isset($_SERVER['HTTP_REFERER']) ? wp_unslash($_SERVER['HTTP_REFERER']) : '')),
        );

        if (!$stored['selected-area'] && $property_id && get_post_type($property_id) === 'property') {
            $stored['selected-area'] = $this->format_area($this->get_sales_area($property_id)) . ' m²';
        }
        if (!$stored['selected-rooms'] && $property_id && get_post_type($property_id) === 'property') {
            $rooms = get_post_meta($property_id, 'property_rooms', true);
            $stored['selected-rooms'] = $rooms ? $rooms . ' szoba' : '';
        }
        if (!$stored['selected-price'] && $property_id && get_post_type($property_id) === 'property') {
            $price = (int) get_post_meta($property_id, 'property_price', true);
            $hide_price = get_post_meta($property_id, '_harmat_hide_front_price', true) === 'yes';
            $stored['selected-price'] = (!$hide_price && $price) ? $this->format_money($price) . ' Ft' : 'Ár egyeztetés alapján';
        }
        if (!$stored['selected-url'] && $property_id && get_post_type($property_id) === 'property') {
            $stored['selected-url'] = get_permalink($property_id);
        }
        if ($stored['your-message'] === '' && $apartment) {
            $stored['your-message'] = 'A ' . $apartment . ' lakás iránt érdeklődöm.';
        }

        $hash = $this->cf7_offer_submission_hash($stored);
        $post_id = $this->existing_cf7_offer_inquiry_id($hash, $stored);

        if (!$post_id) {
            $post_id = wp_insert_post(array(
                'post_type' => 'harmat_offer_lead',
                'post_status' => 'private',
                'post_title' => 'Magán: ' . $name . ' - ' . current_time('ymd-His'),
                'post_content' => $stored['your-message'],
            ), true);

            if (is_wp_error($post_id) || !$post_id) {
                return;
            }
        }

        $crm = get_post_meta($post_id, '_harmat_offer_crm_code', true);
        if (!$crm) {
            $crm = 'WEB-' . current_time('Ymd') . '-' . str_pad((string) $post_id, 5, '0', STR_PAD_LEFT);
        }
        update_post_meta($post_id, '_harmat_offer_posted', $stored);
        update_post_meta($post_id, '_harmat_offer_email', $email);
        update_post_meta($post_id, '_harmat_offer_phone', $phone);
        update_post_meta($post_id, '_harmat_offer_apartment', $apartment);
        update_post_meta($post_id, '_harmat_offer_date', $date);
        update_post_meta($post_id, '_harmat_offer_time', $time);
        update_post_meta($post_id, '_harmat_offer_crm_code', $crm);
        update_post_meta($post_id, '_harmat_offer_mail_status', $mail_status);
        update_post_meta($post_id, '_harmat_offer_mail_checked_at', current_time('mysql'));
        update_post_meta($post_id, '_harmat_cf7_submission_hash', $hash);
        if ($contact_form && method_exists($contact_form, 'id')) {
            update_post_meta($post_id, '_harmat_offer_cf7_form_id', (int) $contact_form->id());
        }
    }

    private function is_offer_cf7_submission($contact_form) {
        $id = ($contact_form && method_exists($contact_form, 'id')) ? (int) $contact_form->id() : 0;
        if (in_array($id, array(1002, 8761), true)) {
            return true;
        }

        $posted = $this->cf7_submission_posted_data(null);
        return is_array($posted) && (isset($posted['selected-apartment']) || isset($posted['selected-url']));
    }

    private function cf7_submission_posted_data($submission = null) {
        if (!$submission && class_exists('WPCF7_Submission')) {
            $submission = WPCF7_Submission::get_instance();
        }
        if (!$submission || !method_exists($submission, 'get_posted_data')) {
            return array();
        }
        $posted = $submission->get_posted_data();
        return is_array($posted) ? $posted : array();
    }

    private function cf7_posted_text($posted, $key) {
        if (!is_array($posted) || !array_key_exists($key, $posted)) {
            return '';
        }

        $value = $posted[$key];
        if (is_array($value)) {
            $value = implode(', ', array_map('sanitize_text_field', array_map('strval', $value)));
        }

        return sanitize_text_field((string) $value);
    }

    private function cf7_posted_textarea($posted, $key) {
        if (!is_array($posted) || !array_key_exists($key, $posted)) {
            return '';
        }

        $value = $posted[$key];
        if (is_array($value)) {
            $value = implode("\n", array_map('strval', $value));
        }

        return sanitize_textarea_field((string) $value);
    }

    private function cf7_offer_submission_hash($stored) {
        $hash_source = array(
            'name' => $stored['your-name'] ?? '',
            'email' => $stored['your-email'] ?? '',
            'phone' => $stored['your-phone'] ?? '',
            'apartment' => $stored['selected-apartment'] ?? '',
            'date' => $stored['your-date'] ?? '',
            'time' => $stored['your-time'] ?? '',
            'message' => $stored['your-message'] ?? '',
        );

        return hash('sha256', wp_json_encode($hash_source));
    }

    private function existing_cf7_offer_inquiry_id($hash, $stored = array()) {
        if ($hash) {
            $existing = get_posts(array(
                'post_type' => 'harmat_offer_lead',
                'post_status' => array('private', 'publish', 'draft'),
                'posts_per_page' => 1,
                'fields' => 'ids',
                'meta_key' => '_harmat_cf7_submission_hash',
                'meta_value' => $hash,
                'date_query' => array(
                    array(
                        'after' => '15 minutes ago',
                        'inclusive' => true,
                    ),
                ),
            ));

            if ($existing) {
                return (int) $existing[0];
            }
        }

        $email = isset($stored['your-email']) ? sanitize_email($stored['your-email']) : '';
        $apartment = isset($stored['selected-apartment']) ? sanitize_text_field($stored['selected-apartment']) : '';
        if ($email === '' || $apartment === '') {
            return 0;
        }

        $meta_query = array(
            'relation' => 'AND',
            array(
                'key' => '_harmat_offer_email',
                'value' => $email,
                'compare' => '=',
            ),
            array(
                'key' => '_harmat_offer_apartment',
                'value' => $apartment,
                'compare' => '=',
            ),
        );

        if (!empty($stored['your-phone'])) {
            $meta_query[] = array(
                'key' => '_harmat_offer_phone',
                'value' => sanitize_text_field($stored['your-phone']),
                'compare' => '=',
            );
        }

        $existing = get_posts(array(
            'post_type' => 'harmat_offer_lead',
            'post_status' => array('private', 'publish', 'draft'),
            'posts_per_page' => 1,
            'fields' => 'ids',
            'meta_query' => $meta_query,
            'date_query' => array(
                array(
                    'after' => '15 minutes ago',
                    'inclusive' => true,
                ),
            ),
        ));

        return $existing ? (int) $existing[0] : 0;
    }

    public function limit_private_roles() {
        if (!is_admin() || wp_doing_ajax() || current_user_can('manage_options')) {
            return;
        }

        if ($this->is_customer_user()) {
            wp_safe_redirect(home_url('/client/'));
            exit;
        }

        if (!$this->is_private_sales_user()) {
            return;
        }

        remove_menu_page('index.php');
        remove_menu_page('profile.php');

        $page = isset($_GET['page']) ? sanitize_key($_GET['page']) : '';
        if ($GLOBALS['pagenow'] === 'admin.php' && $page === self::PAGE_SLUG) {
            return;
        }

        if ($GLOBALS['pagenow'] === 'profile.php') {
            return;
        }

        if ($GLOBALS['pagenow'] !== 'admin.php') {
            wp_safe_redirect(admin_url('admin.php?page=' . self::PAGE_SLUG));
            exit;
        }
    }

    private function is_private_sales_user() {
        $user = wp_get_current_user();
        return array_intersect(array(self::ROLE_MANAGER, self::ROLE_SALES, self::ROLE_BROKER), (array) $user->roles);
    }

    private function can_access_sales_portal() {
        if (!is_user_logged_in()) {
            return false;
        }
        if (current_user_can(self::CAP_MANAGE) || current_user_can('manage_options')) {
            return true;
        }
        $user = wp_get_current_user();
        return in_array(self::ROLE_SALES, (array) $user->roles, true);
    }

    private function is_sales_manager_user() {
        return current_user_can(self::CAP_MANAGE) || current_user_can('manage_options');
    }

    private function can_delete_sales_records() {
        return current_user_can(self::CAP_DELETE) || current_user_can('manage_options');
    }

    private function can_delete_lead_record($lead) {
        if ($this->can_delete_sales_records()) {
            return true;
        }
        if (!$this->is_sales_staff_user() || !is_array($lead)) {
            return false;
        }

        $current_user_id = get_current_user_id();
        return $current_user_id && (int) ($lead['assigned_sales_id'] ?? 0) === $current_user_id;
    }

    private function can_delete_inquiry_record($post_id, $deals = null) {
        if ($this->can_delete_sales_records()) {
            return true;
        }
        if (!$this->is_sales_staff_user()) {
            return false;
        }

        $post_id = absint($post_id);
        if (!$post_id || get_post_type($post_id) !== 'harmat_offer_lead') {
            return false;
        }
        if ($this->offer_inquiry_assigned_sales_id($post_id) !== get_current_user_id()) {
            return false;
        }

        return !$this->find_deal_by_inquiry_id($post_id, $deals);
    }

    private function can_delete_deal_record($deal) {
        if ($this->can_delete_sales_records()) {
            return true;
        }
        if (!$this->is_sales_staff_user() || !is_array($deal)) {
            return false;
        }

        $current_user_id = get_current_user_id();
        if (!$current_user_id || (int) ($deal['assigned_sales_id'] ?? 0) !== $current_user_id) {
            return false;
        }

        return in_array($this->normalize_deal_stage_key($deal['stage'] ?? ''), array('new', 'viewing', 'negotiation', 'lost'), true);
    }

    private function get_sales_trash() {
        $raw = get_option(self::TRASH_OPTION, array());
        if (!is_array($raw)) {
            return array();
        }

        $items = array();
        foreach ($raw as $key => $item) {
            if (!is_array($item)) {
                continue;
            }

            $trash_id = sanitize_key((string) ($item['trash_id'] ?? $key));
            $type = sanitize_key((string) ($item['type'] ?? ''));
            $original_id = absint($item['original_id'] ?? 0);
            $data = isset($item['data']) && is_array($item['data']) ? $item['data'] : array();
            if (!$trash_id || !$original_id || !in_array($type, array('lead', 'deal'), true)) {
                continue;
            }

            $items[$trash_id] = array(
                'trash_id' => $trash_id,
                'type' => $type,
                'original_id' => $original_id,
                'data' => $data,
                'deleted_at' => sanitize_text_field((string) ($item['deleted_at'] ?? '')),
                'deleted_by' => absint($item['deleted_by'] ?? 0),
            );
        }

        uasort($items, function($a, $b) {
            return strcmp((string) ($b['deleted_at'] ?? ''), (string) ($a['deleted_at'] ?? ''));
        });

        return $items;
    }

    private function save_sales_trash($items) {
        update_option(self::TRASH_OPTION, $items, false);
    }

    private function add_sales_trash_item($type, $original_id, $data) {
        $type = sanitize_key((string) $type);
        $original_id = absint($original_id);
        if (!$original_id || !is_array($data) || !in_array($type, array('lead', 'deal'), true)) {
            return '';
        }

        $trash = $this->get_sales_trash();
        $trash_id = $type . '_' . $original_id . '_' . current_time('YmdHis') . '_' . strtolower(wp_generate_password(4, false, false));
        $trash[$trash_id] = array(
            'trash_id' => $trash_id,
            'type' => $type,
            'original_id' => $original_id,
            'data' => $data,
            'deleted_at' => current_time('mysql'),
            'deleted_by' => get_current_user_id(),
        );
        $this->save_sales_trash($trash);

        return $trash_id;
    }

    private function can_view_sales_trash_item($item) {
        if ($this->is_sales_manager_user()) {
            return true;
        }
        if (!$this->is_sales_staff_user() || !is_array($item)) {
            return false;
        }

        $data = isset($item['data']) && is_array($item['data']) ? $item['data'] : array();
        $current_user_id = get_current_user_id();
        return $current_user_id && (
            (int) ($item['deleted_by'] ?? 0) === $current_user_id
            || (int) ($data['assigned_sales_id'] ?? 0) === $current_user_id
        );
    }

    private function can_restore_sales_trash_item($item) {
        return $this->can_view_sales_trash_item($item);
    }

    private function can_purge_sales_trash_item($item) {
        return $this->can_delete_sales_records() && is_array($item);
    }

    private function can_restore_inquiry_record($post_id) {
        $post_id = absint($post_id);
        if (!$post_id || get_post_type($post_id) !== 'harmat_offer_lead' || get_post_status($post_id) !== 'trash') {
            return false;
        }
        if ($this->is_sales_manager_user()) {
            return true;
        }
        if (!$this->is_sales_staff_user()) {
            return false;
        }

        $current_user_id = get_current_user_id();
        return $current_user_id && (
            $this->offer_inquiry_assigned_sales_id($post_id) === $current_user_id
            || (int) get_post_meta($post_id, '_harmat_deleted_by', true) === $current_user_id
        );
    }

    private function is_sales_staff_user() {
        if ($this->is_sales_manager_user()) {
            return false;
        }
        $user = wp_get_current_user();
        return in_array(self::ROLE_SALES, (array) $user->roles, true);
    }

    private function can_view_deal($deal) {
        if ($this->is_sales_manager_user()) {
            return true;
        }
        $current_user_id = get_current_user_id();
        if ((int) ($deal['assigned_sales_id'] ?? 0) === $current_user_id) {
            return true;
        }

        return (int) ($deal['broker_id'] ?? 0) === $current_user_id;
    }

    private function can_view_customer_profile($deal) {
        if ($this->is_sales_manager_user()) {
            return true;
        }
        return $this->is_sales_staff_user() && is_array($deal) && $this->can_view_deal($deal);
    }

    private function can_maintain_customer_profile($deal) {
        if ($this->is_sales_manager_user()) {
            return true;
        }
        if (!$this->is_sales_staff_user() || !is_array($deal)) {
            return false;
        }

        $current_user_id = get_current_user_id();
        return $current_user_id && (int) ($deal['assigned_sales_id'] ?? 0) === $current_user_id;
    }

    private function can_manage_customer_materials($deal) {
        return $this->can_maintain_customer_profile($deal);
    }

    private function is_broker_source_deal($deal) {
        return ($deal['source_type'] ?? '') === 'broker';
    }

    private function has_broker_source_deals($deals) {
        foreach ($deals as $deal) {
            if ($this->is_broker_source_deal($deal)) {
                return true;
            }
        }
        return false;
    }

    private function sales_deal_unit_text($lang = null) {
        $lang = $lang === null || $lang === '' ? $this->active_sales_language() : $lang;
        $lang = $lang === 'hu' ? 'hu' : 'zh';
        $texts = json_decode('{"zh":{"parking":"\u610f\u5411\u8f66\u4f4d","storage":"\u610f\u5411\u50a8\u85cf\u5ba4","none":"\u6682\u672a\u9009\u62e9"},"hu":{"parking":"\u00c9rdekl\u0151d\u00f6tt parkol\u00f3hely","storage":"\u00c9rdekl\u0151d\u00f6tt t\u00e1rol\u00f3","none":"Nincs kiv\u00e1lasztva"}}', true);
        return $texts[$lang] ?? $texts['zh'];
    }

