            $date = (string) ($day['date'] ?? '');
            $inquiries = $can_manage && $date !== '' ? $this->count_offer_inquiries_on_date($date) : null;
            echo '<tr>';
            echo '<td><strong>' . esc_html((string) ($day['label'] ?? $date)) . '</strong><small>' . esc_html($date) . '</small></td>';
            echo '<td>' . esc_html((string) ((int) ($day['visitors'] ?? 0))) . '</td>';
            echo '<td>' . esc_html((string) ((int) ($day['pageviews'] ?? 0))) . '</td>';
            echo '<td>' . esc_html($inquiries === null ? '-' : (string) $inquiries) . '</td>';
            echo '</tr>';
        }
        echo '</tbody></table></div>';
        echo '</div>';
    }

    private function sales_visit_dashboard_stats() {
        $stats = get_option(self::VISIT_STATS_OPTION, array());
        if (!is_array($stats)) {
            $stats = array();
        }

        $today = current_time('Y-m-d');
        $today_data = isset($stats[$today]) && is_array($stats[$today]) ? $stats[$today] : array();
        $seven_day_pageviews = 0;
        $daily = array();
        for ($i = 0; $i < 7; $i++) {
            $date = date('Y-m-d', strtotime('-' . $i . ' days', strtotime($today)));
            $day_data = isset($stats[$date]) && is_array($stats[$date]) ? $stats[$date] : array();
            $pageviews = (int) ($day_data['pageviews'] ?? 0);
            $seven_day_pageviews += $pageviews;
            array_unshift($daily, array(
                'date' => $date,
                'label' => $this->sales_traffic_day_label($date, $today),
                'visitors' => isset($day_data['visitors']) && is_array($day_data['visitors']) ? count($day_data['visitors']) : 0,
                'pageviews' => $pageviews,
            ));
        }

        $top_pages = array();
        $pages = isset($today_data['pages']) && is_array($today_data['pages']) ? $today_data['pages'] : array();
        uasort($pages, function($a, $b) {
            return ((int) ($b['views'] ?? 0)) <=> ((int) ($a['views'] ?? 0));
        });
        foreach (array_slice($pages, 0, 6, true) as $path => $page) {
            $top_pages[] = array(
                'path' => (string) $path,
                'title' => (string) ($page['title'] ?? ''),
                'views' => (int) ($page['views'] ?? 0),
            );
        }

        return array(
            'today_visitors' => isset($today_data['visitors']) && is_array($today_data['visitors']) ? count($today_data['visitors']) : 0,
            'today_pageviews' => (int) ($today_data['pageviews'] ?? 0),
            'seven_day_pageviews' => $seven_day_pageviews,
            'top_pages' => $top_pages,
            'daily' => $daily,
        );
    }

    private function sales_rate_label($value, $total) {
        $value = (int) $value;
        $total = (int) $total;
        if ($total <= 0) {
            return '-';
        }
        return number_format(($value / $total) * 100, 1, ',', ' ') . '%';
    }

    private function sales_recent_visit_totals($days = 7) {
        $stats = get_option(self::VISIT_STATS_OPTION, array());
        if (!is_array($stats)) {
            $stats = array();
        }

        $today = current_time('Y-m-d');
        $visitors = array();
        $pageviews = 0;
        for ($i = 0; $i < max(1, (int) $days); $i++) {
            $date = date('Y-m-d', strtotime('-' . $i . ' days', strtotime($today)));
            $day_data = isset($stats[$date]) && is_array($stats[$date]) ? $stats[$date] : array();
            $pageviews += (int) ($day_data['pageviews'] ?? 0);
            if (isset($day_data['visitors']) && is_array($day_data['visitors'])) {
                foreach ($day_data['visitors'] as $visitor_hash => $flag) {
                    $visitors[$date . ':' . $visitor_hash] = 1;
                }
            }
        }

        return array(
            'visitors' => count($visitors),
            'pageviews' => $pageviews,
        );
    }

    private function sales_stage_at_least($stage, $minimum_stage) {
        $order = array(
            'new' => 10,
            'viewing' => 20,
            'negotiation' => 30,
            'reserved' => 40,
            'contract' => 50,
            'closed' => 60,
            'lost' => 0,
        );
        $stage = $this->normalize_deal_stage_key($stage);
        $minimum_stage = $this->normalize_deal_stage_key($minimum_stage);
        return (int) ($order[$stage] ?? 0) >= (int) ($order[$minimum_stage] ?? 0);
    }

    private function count_sales_deals_at_least($deals, $minimum_stage) {
        $count = 0;
        foreach ($deals as $deal) {
            $stage = $this->normalize_deal_stage_key($deal['stage'] ?? '');
            if ($stage !== 'lost' && $this->sales_stage_at_least($stage, $minimum_stage)) {
                $count++;
            }
        }
        return $count;
    }

    private function count_recent_offer_inquiries($days = 7) {
        $after = date('Y-m-d 00:00:00', strtotime('-' . (max(1, (int) $days) - 1) . ' days', current_time('timestamp')));
        $query = new WP_Query(array(
            'post_type' => 'harmat_offer_lead',
            'post_status' => array('private', 'publish', 'draft'),
            'posts_per_page' => 1,
            'fields' => 'ids',
            'date_query' => array(
                array(
                    'after' => $after,
                    'inclusive' => true,
                ),
            ),
        ));
        return (int) $query->found_posts;
    }

