sszes\u00edt\u0151 export","export_payments_plan":"Fizet\u00e9si \u00fctemez\u00e9s export","export_activity_log":"M\u0171veleti napl\u00f3 export","login":"Bejelentkez\u00e9s","logout":"Kijelentkez\u00e9s","customer_request":"\u00dcgyf\u00e9l \u00e1ltal bek\u00fcld\u00f6tt k\u00e9r\u00e9s"},"objects":{"lead":"\u00dcgyf\u00e9lk\u00f6vet\u00e9s","inquiry":"\u00c9rdekl\u0151d\u00e9s","deal":"\u00c9rt\u00e9kes\u00edt\u00e9si \u00fcgy","customer":"Lez\u00e1rt \u00fcgyf\u00e9l","property":"Lak\u00e1s","user":"Fi\u00f3k","export":"Export","security":"Biztons\u00e1g"}}}', true);
        return $texts[$lang] ?? $texts['zh'];
    }

    private function render_sales_portal_activity_log() {
        $text = $this->sales_activity_text();
        $filters = array(
            'search' => isset($_GET['activity_search']) ? sanitize_text_field(wp_unslash($_GET['activity_search'])) : '',
            'action' => isset($_GET['activity_action']) ? sanitize_key(wp_unslash($_GET['activity_action'])) : '',
        );
        $action_options = $this->sales_activity_action_options();
        if ($filters['action'] && !isset($action_options[$filters['action']])) {
            $filters['action'] = '';
        }

        $rows = $this->filter_sales_activity_log($filters);
        $all_visible_rows = $this->filter_sales_activity_log(array('search' => '', 'action' => ''));
        $export_url = wp_nonce_url($this->sales_portal_url(array('view' => 'activity', 'sales_export' => 'activity_log')), 'harmat_sales_export_activity_log');
        $assign_count = 0;
        $delete_count = 0;
        foreach ($all_visible_rows as $row) {
            $action = (string) ($row['action'] ?? '');
            if (substr($action, -7) === '_assign') {
                $assign_count++;
            }
            if (substr($action, -7) === '_delete') {
                $delete_count++;
            }
        }

        echo '<section class="harmat-sales-kpis harmat-sales-kpis-compact">';
        echo '<article><small>' . esc_html($text['visible']) . '</small><strong>' . count($all_visible_rows) . '</strong></article>';
        echo '<article><small>' . esc_html($text['assign']) . '</small><strong>' . (int) $assign_count . '</strong></article>';
        echo '<article><small>' . esc_html($text['delete']) . '</small><strong>' . (int) $delete_count . '</strong></article>';
        echo '<article><small>' . esc_html($text['current']) . '</small><strong>' . count($rows) . '</strong></article>';
        echo '</section>';

        echo '<section class="harmat-sales-panel">';
        echo '<div class="harmat-sales-panel-head"><div><h2>' . esc_html($text['title']) . '</h2><p>' . esc_html($text['intro']) . '</p></div>';
        echo '<div class="harmat-sales-head-actions"><a href="' . esc_url($export_url) . '">' . esc_html($text['export']) . '</a></div>';
        echo '<form method="get" class="harmat-sales-search harmat-sales-activity-search"><input type="hidden" name="view" value="activity"><input name="activity_search" value="' . esc_attr($filters['search']) . '" placeholder="' . esc_attr($text['search_placeholder']) . '"><select name="activity_action"><option value="">' . esc_html($text['all_actions']) . '</option>';
        foreach ($action_options as $value => $label) {
            echo '<option value="' . esc_attr($value) . '"' . selected($filters['action'], $value, false) . '>' . esc_html($label) . '</option>';
        }
        echo '</select><button>' . esc_html($text['search']) . '</button></form></div>';

        if (!$this->is_sales_manager_user()) {
            echo '<div class="harmat-sales-notice">' . esc_html($text['staff_notice']) . '</div>';
        }

        if (!$rows) {
            echo '<div class="harmat-sales-empty">' . esc_html($text['empty']) . '</div></section>';
            return;
        }

        echo '<div class="harmat-sales-table-wrap"><table class="harmat-sales-table harmat-sales-activity-table"><thead><tr>';
        foreach ($text['headers'] as $header) {
            echo '<th>' . esc_html($header) . '</th>';
        }
        echo '</tr></thead><tbody>';
        foreach ($rows as $row) {
            $this->render_sales_activity_log_row($row);
        }
        echo '</tbody></table></div></section>';
    }

    private function sales_display_value($value, $lang = null) {
        $value = (string) $value;
        if ($value === '') {
            return $value;
        }

        $lang = $lang === null || $lang === '' ? $this->active_sales_language() : $lang;
        if ($lang !== 'hu') {
            return $value;
        }

        $map = json_decode('{"Szoba\u53f7\u5f85\u5b9a":"Lak\u00e1ssz\u00e1m nincs megadva","Lak\u00e1s\u5f85\u9009":"Nincs kiv\u00e1lasztott lak\u00e1s","\u672a\u77e5":"Ismeretlen","\u623f\u6e90\u5f85\u9009":"Nincs kiv\u00e1lasztott lak\u00e1s","\u623f\u95f4\u53f7\u5f85\u5b9a":"Lak\u00e1ssz\u00e1m nincs megadva","\u623f\u53f7\u5f85\u5b9a":"Lak\u00e1ssz\u00e1m nincs megadva","\u53f7\u5f85\u5b9a":"sz\u00e1m nincs megadva","\u5f85\u9009":"nincs kiv\u00e1lasztva"}', true);
        foreach ($map as $from => $to) {
            $value = str_replace($from, $to, $value);
        }

        $unit = json_decode('"\u5957"');
        return preg_replace_callback('/(\\d+)\\s*' . preg_quote($unit, '/') . '/u', function($matches) {
            return $matches[1] . ' db';
        }, $value);
    }

    private function render_sales_activity_log_row($row) {
        $text = $this->sales_activity_text();
        $source_options = $this->deal_source_options();
        $source_type = (string) ($row['source_type'] ?? '');
        $source_label = $source_type && isset($source_options[$source_type]) ? $source_options[$source_type] : '-';
        $assigned_sales_id = (int) ($row['assigned_sales_id'] ?? 0);
        $object_type = (string) ($row['object_type'] ?? '');
        $object_id = (int) ($row['object_id'] ?? 0);
        $object_label = $this->sales_activity_object_label($object_type);
        $client = $this->sales_display_value((string) ($row['client_name'] ?? ''));
        $property = $this->sales_display_value((string) ($row['property_title'] ?? ''));
        $crm_code = (string) ($row['crm_code'] ?? '');

        echo '<tr>';
        echo '<td><strong>' . esc_html($this->format_lead_datetime($row['created_at'] ?? '')) . '</strong><small>#' . esc_html((string) ((int) ($row['id'] ?? 0))) . '</small></td>';
        echo '<td><strong>' . esc_html($row['user_label'] ?: $text['system']) . '</strong><small>User ID ' . esc_html((string) ((int) ($row['user_id'] ?? 0))) . '</small></td>';
        echo '<td><span class="harmat-sales-pill">' . esc_html($this->sales_activity_action_label($row['action'] ?? '')) . '</span></td>';
        echo '<td><strong>' . esc_html($object_label) . '</strong><small>' . esc_html($object_id ? ('ID ' . $object_id) : '-') . '</small></td>';
        echo '<td><strong>' . esc_html($client ?: '-') . '</strong><small>' . esc_html(trim(($property ?: '-') . ($crm_code ? ' / ' . $crm_code : ''))) . '</small></td>';
        echo '<td>' . esc_html($source_label) . '</td>';
        echo '<td>' . esc_html($assigned_sales_id ? $this->assigned_sales_label($assigned_sales_id) : '-') . '</td>';
        echo '<td class="harmat-sales-note-cell">' . esc_html($this->sales_activity_summary_display($row['summary'] ?? '') ?: '-') . '</td>';
        echo '</tr>';
    }

    private function sales_activity_summary_display($summary, $lang = null) {
        $summary = trim((string) $summary);
        if ($summary === '') {
            return '';
        }
        $lang = $lang === null || $lang === '' ? $this->active_sales_language() : $lang;
        if ($lang !== 'hu') {
            $zh_exact = json_decode('{"\u00c9rt\u00e9kes\u00edt\u00e9si port\u00e1l bejelentkez\u00e9s":"\u767b\u5f55\u9500\u552e\u7aef","\u00c9rt\u00e9kes\u00edt\u00e9si port\u00e1l kijelentkez\u00e9s":"\u9000\u51fa\u9500\u552e\u7aef","CRM / portal bejelentkez\u00e9s":"\u767b\u5f55 CRM / portal","Fizet\u00e9si \u00f6sszes\u00edt\u0151 export CSV":"\u5bfc\u51fa\u4ed8\u6b3e\u6c47\u603b CSV","Fizet\u00e9si \u00f6sszes\u00edt\u0151 export XLSX":"\u5bfc\u51fa\u4ed8\u6b3e\u6c47\u603b XLSX","Fizet\u00e9si \u00fctemez\u00e9s export CSV":"\u5bfc\u51fa\u4ed8\u6b3e\u8282\u70b9 CSV","Fizet\u00e9si \u00fctemez\u00e9s export XLSX":"\u5bfc\u51fa\u4ed8\u6b3e\u8282\u70b9 XLSX","\u00c9rt\u00e9kes\u00edt\u00e9si \u00fcgylista export Excel":"\u5bfc\u51fa\u9500\u552e\u8ddf\u5355\u8868\u683c Excel","M\u0171veleti napl\u00f3 export CSV":"\u5bfc\u51fa\u52a8\u4f5c\u8bb0\u5f55 CSV"}', true);
            return $zh_exact[$summary] ?? $summary;
        }

        $exact = json_decode('{"\u767b\u5f55\u9500\u552e\u7aef":"\u00c9rt\u00e9kes\u00edt\u00e9si port\u00e1l bejelentkez\u00e9s","\u9000\u51fa\u9500\u552e\u7aef":"\u00c9rt\u00e9kes\u00edt\u00e9si port\u00e1l kijelentkez\u00e9s","\u767b\u5f55\u00c9rt\u00e9kes\u00edt\u0151\u7aef":"\u00c9rt\u00e9kes\u00edt\u00e9si port\u00e1l bejelentkez\u00e9s","Kil\u00e9p\u00e9s\u00c9rt\u00e9kes\u00edt\u0151\u7aef":"\u00c9rt\u00e9kes\u00edt\u00e9si port\u00e1l kijelentkez\u00e9s","\u767b\u5f55 CRM / portal":"CRM / portal bejelentkez\u00e9s","\u5bfc\u51fa\u4ed8\u6b3e\u6c47\u603b CSV":"Fizet\u00e9si \u00f6sszes\u00edt\u0151 export CSV","\u5bfc\u51fa\u4ed8\u6b3e\u6c47\u603b XLSX":"Fizet\u00e9si \u00f6sszes\u00edt\u0151 export XLSX","\u5bfc\u51fa\u4ed8\u6b3e\u8282\u70b9 CSV":"Fizet\u00e9si \u00fctemez\u00e9s export CSV","\u5bfc\u51fa\u4ed8\u6b3e\u8282\u70b9 XLSX":"Fizet\u00e9si \u00fctemez\u00e9s export XLSX","\u5bfc\u51fa\u9500\u552e\u8ddf\u5355\u8868\u683c Excel":"\u00c9rt\u00e9kes\u00edt\u00e9si \u00fcgylista export Excel","\u5bfc\u51fa\u9500\u552e\u8ddf\u5355\u8868\u683c XLSX":"\u00c9rt\u00e9kes\u00edt\u00e9si \u00fcgylista export XLSX","\u5bfc\u51fa\u9500\u552e\u8ddf\u5355\u8868\u683c CSV":"\u00c9rt\u00e9kes\u00edt\u00e9si \u00fcgylista export CSV","\u5bfc\u51fa\u52a8\u4f5c\u8bb0\u5f55 CSV":"M\u0171veleti napl\u00f3 export CSV"}', true);
        if (isset($exact[$summary])) {
            return $exact[$summary];
        }

        $prefixes = json_decode('[["\u65b0\u589e\u5ba2\u6237\u8ddf\u8fdb\uff1a","\u00daj \u00fcgyf\u00e9lk\u00f6vet\u00e9s: "],["\u4fdd\u5b58\u5ba2\u6237\u8ddf\u8fdb\uff1a","\u00dcgyf\u00e9lk\u00f6vet\u00e9s ment\u00e9se: "],["\u5220\u9664\u5ba2\u6237\u8ddf\u8fdb\uff1a","\u00dcgyf\u00e9lk\u00f6vet\u00e9s t\u00f6rl\u00e9se: "],["\u5220\u9664\u7f51\u7ad9\u8be2\u4ef7\uff1a","Weboldali \u00e9rdekl\u0151d\u00e9s t\u00f6rl\u00e9se: "],["\u6307\u6d3e\u7f51\u7ad9\u8be2\u4ef7\u7ed9\uff1a","Weboldali \u00e9rdekl\u0151d\u00e9s kiosztva: "],["\u6307\u6d3e\u5ba2\u6237\u8ddf\u8fdb\u7ed9\uff1a","\u00dcgyf\u00e9lk\u00f6vet\u00e9s kiosztva: "],["\u6307\u6d3e\u9500\u552e\u8ddf\u5355\u7ed9\uff1a","\u00c9rt\u00e9kes\u00edt\u00e9si \u00fcgy kiosztva: "],["\u751f\u6210\u9500\u552e\u8ddf\u5355\uff1a","\u00c9rt\u00e9kes\u00edt\u00e9si \u00fcgy l\u00e9trehoz\u00e1sa: "],["\u4fdd\u5b58\u9500\u552e\u8ddf\u5355\uff1a","\u00c9rt\u00e9kes\u00edt\u00e9si \u00fcgy ment\u00e9se: "],["\u5220\u9664\u9500\u552e\u8ddf\u5355\uff1a","\u00c9rt\u00e9kes\u00edt\u00e9si \u00fcgy t\u00f6rl\u00e9se: "],["\u7ef4\u62a4\u6210\u4ea4\u5ba2\u6237\u6863\u6848\uff1a","Lez\u00e1rt \u00fcgyf\u00e9lakta karbantart\u00e1sa: "]]', true);
        foreach ($prefixes as $pair) {
            $prefix = (string) ($pair[0] ?? '');
            if ($prefix !== '' && strncmp($summary, $prefix, strlen($prefix)) === 0) {
                return (string) ($pair[1] ?? '') . $this->sales_display_value(trim(substr($summary, strlen($prefix))), $lang);
            }
        }

        return $this->sales_display_value($summary, $lang);
    }

    private function filter_sales_activity_log($filters) {
        $rows = $this->get_sales_activity_log(500);
        $current_user_id = get_current_user_id();
        $search = trim((string) ($filters['search'] ?? ''));
        $action_filter = (string) ($filters['action'] ?? '');
        $filtered = array();

        foreach ($rows as $row) {
            if (!$this->is_sales_manager_user() && !$this->can_view_sales_activity_row($row, $current_user_id)) {
                continue;
            }
            if ($action_filter && (string) ($row['action'] ?? '') !== $action_filter) {
                continue;
            }
            if ($search !== '') {
                $haystack = implode(' ', array(
                    $row['user_label'] ?? '',
                    $this->sales_activity_action_label($row['action'] ?? ''),
                    $this->sales_activity_summary_display($row['summary'] ?? ''),
                    $row['client_name'] ?? '',
                    $row['property_title'] ?? '',
                    $row['crm_code'] ?? '',
                    $row['email'] ?? '',
                    $row['phone'] ?? '',
                    $this->assigned_sales_label((int) ($row['assigned_sales_id'] ?? 0)),
                ));
                if (strpos($this->normalize_sales_filter_text($haystack), $this->normalize_sales_filter_text($search)) === false) {
                    continue;
                }
            }
            $filtered[] = $row;
        }

        return array_slice($filtered, 0, 160);
    }

    private function can_view_sales_activity_row($row, $current_user_id) {
        $current_user_id = (int) $current_user_id;
        if (!$current_user_id) {
            return false;
        }
        if ((int) ($row['user_id'] ?? 0) === $current_user_id) {
            return true;
        }
        if ((int) ($row['assigned_sales_id'] ?? 0) === $current_user_id) {
            return true;
        }
        $related_user_ids = isset($row['related_user_ids']) && is_array($row['related_user_ids']) ? $row['related_user_ids'] : array();
        return in_array($current_user_id, array_map('intval', $related_user_ids), true);
    }

    private function get_sales_activity_log($limit = 160) {
        $raw = get_option(self::ACTIVITY_LOG_OPTION, array());
        if (!is_array($raw)) {
            return array();
        }

        $rows = array();
        foreach ($raw as $key => $row) {
            if (!is_array($row)) {
                continue;
            }
            $id = !empty($row['id']) ? absint($row['id']) : absint($key);
            if (!$id) {
                continue;
            }
            $rows[] = array_merge(array(
                'id' => $id,
                'created_at' => '',
                'user_id' => 0,
                'user_label' => '',
                'action' => '',
                'object_type' => '',
                'object_id' => 0,
                'summary' => '',
                'client_name' => '',
                'phone' => '',
                'email' => '',
                'property_title' => '',
                'crm_code' => '',
                'source_type' => '',
                'assigned_sales_id' => 0,
                'related_user_ids' => array(),
                'lead_id' => 0,
                'deal_id' => 0,
                'inquiry_id' => 0,
            ), $row);
        }

        usort($rows, function($a, $b) {
            $time_compare = strcmp((string) ($b['created_at'] ?? ''), (string) ($a['created_at'] ?? ''));
            if ($time_compare !== 0) {
                return $time_compare;
            }
            return ((int) ($b['id'] ?? 0)) <=> ((int) ($a['id'] ?? 0));
        });

        return array_slice($rows, 0, absint($limit) ?: 160);
    }

    private function log_sales_activity($action, $object_type, $object_id, $summary, $context = array()) {
        $raw = get_option(self::ACTIVITY_LOG_OPTION, array());
        if (!is_array($raw)) {
            $raw = array();
        }

        $ids = array();
        foreach ($raw as $item) {
            if (is_array($item) && !empty($item['id'])) {
                $ids[] = absint($item['id']);
            }
        }
        $next_id = $ids ? max($ids) + 1 : 1;
        $user_id = isset($context['actor_user_id']) ? absint($context['actor_user_id']) : get_current_user_id();
        $user = $user_id ? get_userdata($user_id) : null;
        $assigned_sales_id = isset($context['assigned_sales_id']) ? absint($context['assigned_sales_id']) : 0;
        $related_user_ids = isset($context['related_user_ids']) && is_array($context['related_user_ids']) ? array_map('absint', $context['related_user_ids']) : array();
        if ($assigned_sales_id) {
            $related_user_ids[] = $assigned_sales_id;
        }
        $related_user_ids[] = $user_id;
        $related_user_ids = array_values(array_filter(array_unique($related_user_ids)));

        $raw[] = array(
            'id' => $next_id,
            'created_at' => current_time('mysql'),
            'user_id' => $user_id,
            'user_label' => $user ? ($user->display_name ?: $user->user_login) : '系统',
            'action' => sanitize_key($action),
            'object_type' => sanitize_key($object_type),
            'object_id' => absint($object_id),
            'summary' => sanitize_text_field((string) $summary),
            'client_name' => sanitize_text_field((string) ($context['client_name'] ?? '')),
            'phone' => sanitize_text_field((string) ($context['phone'] ?? '')),
            'email' => sanitize_email((string) ($context['email'] ?? '')),
            'property_title' => sanitize_text_field((string) ($context['property_title'] ?? '')),
            'crm_code' => sanitize_text_field((string) ($context['crm_code'] ?? '')),
            'source_type' => sanitize_key((string) ($context['source_type'] ?? '')),
            'assigned_sales_id' => $assigned_sales_id,
            'related_user_ids' => $related_user_ids,
            'lead_id' => isset($context['lead_id']) ? absint($context['lead_id']) : 0,
            'deal_id' => isset($context['deal_id']) ? absint($context['deal_id']) : 0,
            'inquiry_id' => isset($context['inquiry_id']) ? absint($context['inquiry_id']) : 0,
        );

        if (count($raw) > 500) {
            $raw = array_slice($raw, -500);
        }

        update_option(self::ACTIVITY_LOG_OPTION, array_values($raw), false);
    }

    public function log_sales_portal_login($user_login, $user) {
        if (!$user instanceof WP_User || !$this->is_private_portal_user($user)) {
            return;
        }

        $this->log_sales_activity(
            'login',
            'security',
            (int) $user->ID,
            $this->active_sales_language() === 'hu' ? json_decode('"\u00c9rt\u00e9kes\u00edt\u00e9si port\u00e1l bejelentkez\u00e9s"') : json_decode('"\u767b\u5f55\u9500\u552e\u7aef"'),
            array(
                'actor_user_id' => (int) $user->ID,
                'related_user_ids' => array((int) $user->ID),
            )
        );
    }

    public function log_sales_portal_logout($user_id = 0) {
        $user_id = absint($user_id);
        if (!$user_id) {
            $user_id = get_current_user_id();
        }
        $user = $user_id ? get_userdata($user_id) : null;
        if (!$user instanceof WP_User || !$this->is_private_portal_user($user)) {
            return;
        }

        $this->log_sales_activity(
            'logout',
            'security',
            (int) $user->ID,
            $this->active_sales_language() === 'hu' ? json_decode('"\u00c9rt\u00e9kes\u00edt\u00e9si port\u00e1l kijelentkez\u00e9s"') : json_decode('"\u9000\u51fa\u9500\u552e\u7aef"'),
            array(
                'actor_user_id' => (int) $user->ID,
                'related_user_ids' => array((int) $user->ID),
            )
        );
    }

    private function is_private_portal_user($user) {
        if (!$user instanceof WP_User) {
            return false;
        }
        return (bool) array_intersect(
            array(self::ROLE_MANAGER, self::ROLE_SALES, self::ROLE_BROKER, self::ROLE_CUSTOMER),
            (array) $user->roles
        );
    }

    private function sales_activity_action_options($lang = null) {
        $text = $this->sales_activity_text($lang);
        return $text['actions'];
    }

    private function sales_activity_action_label($action) {
        $options = $this->sales_activity_action_options();
        $action = (string) $action;
        return $options[$action] ?? ($action ?: '-');
    }

    private function sales_activity_object_label($object_type, $lang = null) {
        $text = $this->sales_activity_text($lang);
        $labels = $text['objects'];
        $object_type = (string) $object_type;
        return $labels[$object_type] ?? ($object_type ?: '-');
    }

    private function sales_task_page_text($lang = null) {
        $lang = $lang === null || $lang === '' ? $this->active_sales_language() : $lang;
        $lang = $lang === 'hu' ? 'hu' : 'zh';
