    private function render_sales_deal_stage_board($deals) {
        $stage_options = $this->deal_stage_options();
        $columns = array_fill_keys(array_keys($stage_options), array());
        foreach ($deals as $deal) {
            $stage = $this->normalize_deal_stage_key($deal['stage'] ?? '');
            if (!isset($columns[$stage])) {
                $stage = 'new';
            }
            $columns[$stage][] = $deal;
        }

        echo '<div class="harmat-sales-stage-board-intro"><div><strong>' . esc_html(json_decode('\"\\u81ea\\u52a8\\u89c4\\u5219\"')) . '</strong><span>' . esc_html(json_decode('\"\\u7cfb\\u7edf\\u4f1a\\u81ea\\u52a8\\u6807\\u8bb0\\u9700\\u8981\\u5904\\u7406\\u7684\\u4e8b\\u9879\\u3002\"')) . '</span></div><small>' . esc_html(json_decode('\"\\u4fdd\\u6301\\u8ddf\\u8fdb\"')) . '</small></div>';
        echo '<div class="harmat-sales-stage-board">';
        foreach ($columns as $stage => $items) {
            if (!$items) {
                continue;
            }
            echo '<section class="harmat-sales-stage-column harmat-sales-stage-column-' . esc_attr($stage) . '"><header><strong>' . esc_html($stage_options[$stage]) . '</strong><span>' . esc_html((string) count($items)) . '</span></header><div class="harmat-sales-stage-column-body">';
            foreach (array_slice($items, 0, 12) as $deal) {
                $this->render_sales_deal_stage_board_card($deal);
            }
            if (count($items) > 12) {
                echo '<a class="harmat-sales-stage-more" href="' . esc_url($this->sales_portal_url(array('view' => 'deals', 'deal_stage' => $stage))) . '">?? ' . esc_html((string) (count($items) - 12)) . '</a>';
            }
            echo '</div></section>';
        }
        echo '</div>';
    }

    private function render_sales_deal_stage_board_card($deal) {
        $lang = $this->active_sales_language();
        $fallbacks = json_decode('{"zh":{"no_client":"\u672a\u586b\u5199\u5ba2\u6237","no_property":"\u672a\u6307\u5b9a\u623f\u6e90","no_amount":"\u91d1\u989d\u672a\u586b\u5199"},"hu":{"no_client":"Nincs \u00fcgyf\u00e9l megadva","no_property":"Nincs lak\u00e1s megadva","no_amount":"Nincs \u00f6sszeg megadva"}}', true);
        $fallback = $fallbacks[$lang === 'hu' ? 'hu' : 'zh'];
        $stage_options = $this->deal_stage_options();
        $stage = $this->normalize_deal_stage_key($deal['stage'] ?? '');
        $property_title = !empty($deal['property_id']) ? $this->sales_display_value(get_the_title((int) $deal['property_id']), $lang) : '';
        $followup_meta = $this->sales_deal_followup_meta($deal);
        $amount = (int) ($deal['amount'] ?? 0);
        $url = $this->sales_portal_url(array('view' => 'deals', 'edit_deal' => (int) ($deal['id'] ?? 0)));
        $next_text = !empty($deal['next_followup']) ? $this->format_followup_datetime($deal['next_followup']) . ' / ' . $followup_meta['label'] : $followup_meta['label'];

        echo '<a class="harmat-sales-stage-card harmat-sales-stage-card-' . esc_attr($stage) . '" href="' . esc_url($url) . '">';
        echo '<small>' . esc_html($deal['crm_code'] ?? '-') . '</small>';
        echo '<strong>' . esc_html($this->sales_display_value($deal['client_name'] ?: $fallback['no_client'], $lang)) . '</strong>';
        echo '<span>' . esc_html($property_title ?: $fallback['no_property']) . '</span>';
        echo '<em class="harmat-sales-task-pill harmat-sales-task-' . esc_attr($followup_meta['class']) . '">' . esc_html($next_text) . '</em>';
        echo '<b>' . esc_html($amount > 0 ? $this->format_money($amount) . ' Ft' : $fallback['no_amount']) . '</b>';
        echo '</a>';
    }

    private function sales_deal_followup_meta($deal, $lang = null) {
        $lang = $lang === null || $lang === '' ? $this->active_sales_language() : $lang;
        $lang = $lang === 'hu' ? 'hu' : 'zh';
        $labels = json_decode('{"zh":{"closed":"\u5df2\u6210\u4ea4","lost":"\u5df2\u6d41\u5931","none":"\u672a\u8bbe\u7f6e\u8ddf\u8fdb","invalid":"\u65e5\u671f\u9700\u68c0\u67e5","overdue":"\u5df2\u903e\u671f","today":"\u4eca\u5929","upcoming":"\u672a\u67657\u5929","future":"\u672a\u6765\u8ddf\u8fdb"},"hu":{"closed":"Lez\u00e1rva","lost":"Elveszett","none":"Nincs k\u00f6vet\u00e9s be\u00e1ll\u00edtva","invalid":"D\u00e1tum ellen\u0151rzend\u0151","overdue":"Lej\u00e1rt","today":"Ma","upcoming":"K\u00f6vetkez\u0151 7 nap","future":"K\u00e9s\u0151bbi k\u00f6vet\u00e9s"}}', true);
        $labels = $labels[$lang] ?? $labels['zh'];
        $stage = $this->normalize_deal_stage_key($deal['stage'] ?? '');
        if (in_array($stage, array('closed', 'lost'), true)) {
            return array(
                'class' => 'done',
                'label' => $stage === 'closed' ? $labels['closed'] : $labels['lost'],
                'order' => 60,
                'timestamp' => PHP_INT_MAX,
                'active' => false,
            );
        }

        $date = !empty($deal['next_followup']) ? (string) $deal['next_followup'] : '';
        if (!$date) {
            return array(
                'class' => 'none',
                'label' => $labels['none'],
                'order' => 40,
                'timestamp' => PHP_INT_MAX,
                'active' => true,
            );
        }

        $today = strtotime(current_time('Y-m-d'));
        $week = strtotime('+7 days', $today);
        $followup_ts = strtotime($date);
        if (!$followup_ts) {
            return array(
                'class' => 'none',
                'label' => $labels['invalid'],
                'order' => 45,
                'timestamp' => PHP_INT_MAX,
                'active' => true,
            );
        }
        $followup_day = strtotime(date('Y-m-d', $followup_ts));

        if ($followup_day < $today) {
            $class = 'overdue';
            $label = $labels['overdue'];
            $order = 10;
        } elseif ($followup_day === $today) {
            $class = 'today';
            $label = $labels['today'];
            $order = 20;
        } elseif ($followup_day <= $week) {
            $class = 'upcoming';
            $label = $labels['upcoming'];
            $order = 30;
        } else {
            $class = 'future';
            $label = $labels['future'];
            $order = 35;
        }

        return array(
            'class' => $class,
            'label' => $label,
            'order' => $order,
            'timestamp' => $followup_ts,
            'active' => true,
        );
    }

    private function sort_sales_deals_by_priority($deals) {
        $deals = array_values($deals);
        usort($deals, function($a, $b) {
            $a_meta = $this->sales_deal_followup_meta($a);
            $b_meta = $this->sales_deal_followup_meta($b);
            if ($a_meta['order'] !== $b_meta['order']) {
                return $a_meta['order'] <=> $b_meta['order'];
            }
            if ($a_meta['timestamp'] !== $b_meta['timestamp']) {
                return $a_meta['timestamp'] <=> $b_meta['timestamp'];
            }
            $a_updated = !empty($a['updated_at']) ? strtotime((string) $a['updated_at']) : 0;
            $b_updated = !empty($b['updated_at']) ? strtotime((string) $b['updated_at']) : 0;
            if ($a_updated !== $b_updated) {
                return $b_updated <=> $a_updated;
            }
            return ((int) ($b['id'] ?? 0)) <=> ((int) ($a['id'] ?? 0));
        });
        return $deals;
    }

    private function render_sales_deal_followup_summary($deals, $text = null) {
        $text = $text ?: $this->sales_deals_page_text($this->active_sales_language());
        $counts = array(
            'overdue' => 0,
            'today' => 0,
            'upcoming' => 0,
            'none' => 0,
        );
        foreach ($deals as $deal) {
            $meta = $this->sales_deal_followup_meta($deal);
            if (empty($meta['active'])) {
                continue;
            }
            if (isset($counts[$meta['class']])) {
                $counts[$meta['class']]++;
            }
