        echo '<div class="harmat-sales-filter-actions"><button>' . esc_html($text['apply']) . '</button><a href="' . esc_url($this->sales_portal_url($reset_args)) . '">' . esc_html($text['reset']) . '</a></div>';
        echo '</form>';
