        $add_row($txt['contract_status'], !empty($deal['contract_status']) && isset($contract_options[$deal['contract_status']]) ? $contract_options[$deal['contract_status']] : '', 'payment');
        $add_row($txt['note'], $deal['note'] ?? '', 'long');

