        if ($source_type === 'broker') {
            $source_meta .= ' / ' . $text['row']['broker'] . ': ' . ($broker ? $broker->display_name : '-');
        }
        echo '<span>' . esc_html($source_meta) . '</span></div>';
        echo '<div class="harmat-sales-deal-card-metrics">';
        echo '<span><small>' . esc_html($text['row']['amount']) . '</small><strong>' . esc_html($amount > 0 ? $this->format_money($amount) . ' Ft' : '-') . '</strong></span>';
        echo '<span><small>' . esc_html($text['row']['received_balance']) . '</small><strong>' . esc_html($this->format_money($received) . ' / ' . $this->format_money($balance) . ' Ft') . '</strong></span>';
        echo '<span><small>' . esc_html($text['row']['payment']) . '</small><strong>' . esc_html($payment_label) . '</strong><em>' . esc_html($payment_statuses[$payment_status] ?? $payment_status) . '</em></span>';
        echo '<span><small>' . esc_html($text['row']['contract']) . '</small><strong>' . esc_html($contract_label) . '</strong></span>';
        echo '</div>';
        if (isset($text['followup'][$followup_class])) {
            $followup_label = $text['followup'][$followup_class];
        }
        echo '<div class="harmat-sales-deal-card-next"><small>' . esc_html($text['row']['next']) . '</small><strong>' . esc_html($next_step_label ?: '-') . '</strong><span class="harmat-sales-task-pill harmat-sales-task-' . esc_attr($followup_class) . '">' . esc_html($next_followup ? $next_followup . ' / ' . $followup_label : $followup_label) . '</span></div>';
        echo '<footer><span>' . esc_html($text['row']['updated']) . esc_html($this->format_lead_datetime($deal['updated_at'] ?? '') ?: '-') . '</span><div><a href="' . esc_url($this->sales_portal_url(array('view' => 'deals', 'edit_deal' => (int) $deal['id']))) . '">' . esc_html($text['row']['edit']) . '</a>';
        if ($this->can_view_customer_profile($deal)) {
            echo '<a href="' . esc_url($this->sales_portal_url(array('view' => 'customers', 'customer_id' => (int) $deal['id']))) . '">' . esc_html($text['row']['profile']) . '</a>';
        }
        if ($this->can_delete_deal_record($deal)) {
            echo '<form method="post" class="harmat-sales-card-delete-form">';
            wp_nonce_field('harmat_sales_action_delete_deal');
            echo '<input type="hidden" name="harmat_sales_action" value="delete_deal">';
            echo '<input type="hidden" name="return_to" value="sales_deals">';
            echo '<input type="hidden" name="deal_id" value="' . esc_attr((int) $deal['id']) . '">';
            echo '<button type="submit" onclick="return confirm(\'' . esc_js($text['editor']['delete_confirm']) . '\')">' . esc_html($text['row']['delete']) . '</button>';
            echo '</form>';
        }
        echo '</div></footer></article>';
    }

    private function render_sales_portal_client_row($lead, $text = null) {
        $text = $text ?: $this->sales_clients_page_text($this->active_sales_language());
        $status_options = $text['status'];
        $status = isset($status_options[$lead['status']]) ? $lead['status'] : 'new';
        $broker = !empty($lead['broker_id']) ? get_userdata((int) $lead['broker_id']) : null;
        $assigned_sales_id = (int) ($lead['assigned_sales_id'] ?? 0);
        $assigned_sales_label = $assigned_sales_id ? $this->assigned_sales_label($assigned_sales_id) : $text['row'][14];
        $days_left = $this->lead_protection_days_left($lead);
        $protection_class = $days_left > 0 ? 'active' : 'expired';
        $property_title = $lead['property_id'] ? $this->sales_display_value(get_the_title((int) $lead['property_id'])) : '';
        $property_url = $lead['property_id'] ? get_permalink((int) $lead['property_id']) : '';
        $source_type = $this->lead_source_type($lead);
        $source_label = $text['source'][$source_type] ?? $text['source']['walkin'];

        echo '<tr><td><strong>' . esc_html($this->sales_display_value($lead['client_name'])) . '</strong><small>' . esc_html($source_label) . '</small><small>' . esc_html($lead['phone'] ?: '-') . '</small><small>' . esc_html($lead['email'] ?: '-') . '</small></td><td>';
        echo ($property_title && $property_url) ? '<a href="' . esc_url($property_url) . '" target="_blank" rel="noopener">' . esc_html($property_title) . '</a>' : esc_html($text['row'][0]);
        echo '<small><span class="harmat-sales-pill">' . esc_html($status_options[$status]) . '</span></small>';
        echo '<small><span class="harmat-sales-protection harmat-sales-protection-' . esc_attr($protection_class) . '">' . esc_html($days_left > 0 ? $text['row'][1] . $days_left . $text['row'][2] : $text['row'][3]) . '</span></small></td><td>';
        echo '<strong>' . esc_html($this->format_followup_datetime($lead['next_followup'] ?? '')) . '</strong><small>' . esc_html($text['row'][4] . $this->format_lead_datetime($lead['created_at'] ?? '')) . '</small><small>' . esc_html($text['row'][5] . ($this->lead_protection_expires_at($lead) ?: '-')) . '</small></td>';
        $broker_label = ($broker && $this->is_broker_user((int) $broker->ID)) ? $broker->display_name : '-';
        echo '<td><strong>' . esc_html($assigned_sales_label) . '</strong>';
        if ($this->is_sales_manager_user()) {
            echo '<form method="post" class="harmat-sales-inline-form harmat-sales-assign-form">';
            wp_nonce_field('harmat_sales_action_assign_lead');
            echo '<input type="hidden" name="harmat_sales_action" value="assign_lead"><input type="hidden" name="lead_id" value="' . esc_attr((int) $lead['id']) . '">';
            $this->render_assigned_sales_select('assigned_sales_id', $assigned_sales_id, true, $text['row'][14]);
            echo '<button>' . esc_html($text['row'][6]) . '</button></form>';
        } else {
            echo '<small>' . esc_html($text['row'][7] . $assigned_sales_label) . '</small>';
        }
        echo '</td><td>' . esc_html($broker_label) . '</td><td class="harmat-sales-note-cell">' . esc_html($lead['note'] ?: '-') . '</td>';
        $linked_deal = $this->find_deal_by_lead_id((int) ($lead['id'] ?? 0));
        $deal_url = $linked_deal ? $this->sales_portal_url(array('view' => 'deals', 'edit_deal' => (int) ($linked_deal['id'] ?? 0))) : $this->sales_portal_url(array('view' => 'deals', 'lead_id' => (int) $lead['id']));
        echo '<td class="harmat-sales-actions"><a href="' . esc_url($this->sales_portal_url(array('view' => 'clients', 'edit_lead' => (int) $lead['id']))) . '">' . esc_html($text['row'][8]) . '</a><a class="' . esc_attr($linked_deal ? 'harmat-sales-secondary-action' : 'harmat-sales-primary-action') . '" href="' . esc_url($deal_url) . '">' . esc_html($linked_deal ? $text['row'][9] : $text['row'][10]) . '</a>';
        if (!$linked_deal) { echo '<small>' . esc_html($text['row'][11]) . '</small>'; }
        if ($this->can_delete_lead_record($lead) && (!$linked_deal || $this->can_delete_sales_records())) {
            echo '<form method="post">';
            wp_nonce_field('harmat_sales_action_delete_lead');
            echo '<input type="hidden" name="harmat_sales_action" value="delete_lead"><input type="hidden" name="return_to" value="sales_clients"><input type="hidden" name="lead_id" value="' . esc_attr($lead['id']) . '"><button onclick="return confirm(\'' . esc_js($text['row'][13]) . '\')">' . esc_html($text['row'][12]) . '</button></form>';
        }
        echo '</td></tr>';
    }

    private function render_sales_portal_property_row($property) {
        $post_id = (int) $property->ID;
        $status = $this->sales_status($post_id);
        $status_options = $this->status_options($this->active_sales_language());
        $price = (int) get_post_meta($post_id, 'property_price', true);
        $hide_price = get_post_meta($post_id, '_harmat_hide_front_price', true) === 'yes';
        $sales_area = $this->get_sales_area($post_id);
        $terrace = get_post_meta($post_id, 'property_land_area', true);
        $note = get_post_meta($post_id, '_harmat_sales_note', true);
        $form_id = 'harmat-sales-property-' . $post_id;
        $can_manage = $this->is_sales_manager_user();
        $front_price = ($hide_price || !$price) ? ($this->active_sales_language() === 'hu' ? json_decode('"\\u00c1r egyeztet\\u00e9s alapj\\u00e1n"') : json_decode('"\\u4ef7\\u683c\\u5f85\\u8bae"')) : $this->format_money($price) . ' Ft';

        echo '<tr>';
        echo '<td><strong>' . esc_html(get_the_title($post_id)) . '</strong>';
        if ($can_manage) {
            echo '<form method="post" id="' . esc_attr($form_id) . '">';
            wp_nonce_field('harmat_sales_action_update_property');
            echo '<input type="hidden" name="harmat_sales_action" value="update_property">';
            echo '<input type="hidden" name="return_to" value="sales_properties">';
            echo '<input type="hidden" name="post_id" value="' . esc_attr($post_id) . '">';
            echo '</form>';
        }
        echo '</td>';
        if ($can_manage) {
            echo '<td><select form="' . esc_attr($form_id) . '" name="sales_status">';
            foreach ($status_options as $value => $label) {
                echo '<option value="' . esc_attr($value) . '"' . selected($status, $value, false) . '>' . esc_html($label) . '</option>';
            }
            echo '</select></td>';
        } else {
            echo '<td><span class="harmat-sales-pill">' . esc_html($status_options[$status] ?? $status) . '</span></td>';
        }
        echo '<td>' . esc_html(get_post_meta($post_id, 'property_address_street', true) ?: '-') . '</td>';
        echo '<td>' . esc_html(get_post_meta($post_id, 'property_address_street_number', true) ?: '-') . '</td>';
        echo '<td>' . esc_html(get_post_meta($post_id, 'property_rooms', true) ?: '-') . '</td>';
        echo '<td>' . esc_html($sales_area ? $this->format_area($sales_area) . ' m²' : '-') . '</td>';
        echo '<td>' . esc_html($terrace ? $this->format_area($terrace) . ' m²' : '-') . '</td>';
        if ($can_manage) {
            echo '<td><input form="' . esc_attr($form_id) . '" name="property_price" value="' . esc_attr($price) . '" inputmode="numeric"></td>';
            echo '<td><select form="' . esc_attr($form_id) . '" name="price_visibility"><option value="show"' . selected(!$hide_price, true, false) . '>显示价格</option><option value="hide"' . selected($hide_price, true, false) . '>隐藏价格</option></select><small>' . esc_html($front_price) . '</small></td>';
            echo '<td><input form="' . esc_attr($form_id) . '" name="sales_note" value="' . esc_attr($note) . '" placeholder="内部备注"></td>';
        } else {
            echo '<td>' . esc_html($price ? $this->format_money($price) . ' Ft' : '-') . '</td>';
            echo '<td><span>' . esc_html($front_price) . '</span></td>';
            echo '<td>' . esc_html($note ?: '-') . '</td>';
        }
        echo '<td><a href="' . esc_url(get_permalink($post_id)) . '" target="_blank" rel="noopener">打开</a></td>';
        echo '<td class="harmat-sales-actions">' . ($can_manage ? '<button form="' . esc_attr($form_id) . '">保存</button>' : '<span>只读</span>') . '</td>';
        echo '</tr>';
    }

    private function render_sales_portal_trash() {
        $lang = $this->active_sales_language() === 'hu' ? 'hu' : 'zh';
        $texts = json_decode('{"zh":{"title":"\u5220\u9664\u56de\u6536\u7ad9","intro":"\u8bef\u5220\u6216\u91cd\u590d\u8bb0\u5f55\u4f1a\u5148\u8fdb\u5165\u8fd9\u91cc\u3002\u6062\u590d\u540e\u56de\u5230\u539f\u4e1a\u52a1\u5217\u8868\uff1b\u6c38\u4e45\u5220\u9664\u53ea\u5efa\u8bae\u5728\u786e\u8ba4\u65e0\u7528\u540e\u7531\u4e3b\u7ba1\u64cd\u4f5c\u3002","empty":"\u5f53\u524d\u56de\u6536\u7ad9\u4e3a\u7a7a\u3002","headers":["\u7c7b\u578b","\u8bb0\u5f55","\u623f\u6e90/CRM","\u8d1f\u8d23\u4eba","\u5220\u9664\u65f6\u95f4","\u5220\u9664\u4eba","\u64cd\u4f5c"],"types":{"lead":"\u5ba2\u6237\u8ddf\u8fdb","deal":"\u9500\u552e\u8ddf\u5355","inquiry":"\u7f51\u7ad9\u8be2\u4ef7"},"no_client":"\u672a\u586b\u5199","restore":"\u6062\u590d","purge":"\u6c38\u4e45\u5220\u9664","purge_confirm":"\u786e\u5b9a\u6c38\u4e45\u5220\u9664\u8fd9\u6761\u8bb0\u5f55\u5417\uff1f\u6b64\u64cd\u4f5c\u4e0d\u53ef\u6062\u590d\u3002"},"hu":{"title":"T\u00f6rl\u00e9si lomt\u00e1r","intro":"A t\u00e9vesen t\u00f6r\u00f6lt vagy duplik\u00e1lt rekordok ide ker\u00fclnek. Vissza\u00e1ll\u00edt\u00e1s ut\u00e1n az eredeti \u00fczleti list\u00e1ba ker\u00fclnek vissza; v\u00e9gleges t\u00f6rl\u00e9st csak vezet\u0151i ellen\u0151rz\u00e9s ut\u00e1n \u00e9rdemes haszn\u00e1lni.","empty":"A lomt\u00e1r jelenleg \u00fcres.","headers":["T\u00edpus","Rekord","Lak\u00e1s / CRM","Felel\u0151s","T\u00f6rl\u00e9s ideje","T\u00f6r\u00f6lte","M\u0171velet"],"types":{"lead":"\u00dcgyf\u00e9lk\u00f6vet\u00e9s","deal":"\u00c9rt\u00e9kes\u00edt\u00e9si \u00fcgy","inquiry":"Weboldali \u00e9rdekl\u0151d\u00e9s"},"no_client":"Nincs megadva","restore":"Vissza\u00e1ll\u00edt\u00e1s","purge":"V\u00e9gleges t\u00f6rl\u00e9s","purge_confirm":"Biztosan v\u00e9glegesen t\u00f6rli ezt a rekordot? Ez a m\u0171velet nem vonhat\u00f3 vissza."}}', true);
        $text = $texts[$lang] ?? $texts['zh'];
        $rows = array();
        foreach ($this->get_sales_trash() as $item) {
            if (!$this->can_view_sales_trash_item($item)) {
                continue;
            }
            $data = isset($item['data']) && is_array($item['data']) ? $item['data'] : array();
            $property_title = !empty($data['property_id']) ? get_the_title((int) $data['property_id']) : '';
            $rows[] = array(
                'type' => (string) ($item['type'] ?? ''),
                'trash_id' => (string) ($item['trash_id'] ?? ''),
                'original_id' => (int) ($item['original_id'] ?? 0),
                'client' => $data['client_name'] ?? '',
                'contact' => trim(($data['phone'] ?? '') . ' ' . ($data['email'] ?? '')),
                'property' => $property_title,
                'crm' => $data['crm_code'] ?? '',
                'assigned_sales_id' => (int) ($data['assigned_sales_id'] ?? 0),
                'deleted_at' => (string) ($item['deleted_at'] ?? ''),
                'deleted_by' => (int) ($item['deleted_by'] ?? 0),
                'sort' => strtotime((string) ($item['deleted_at'] ?? '')) ?: 0,
                'can_restore' => $this->can_restore_sales_trash_item($item),
                'can_purge' => $this->can_purge_sales_trash_item($item),
            );
        }

        $trashed_inquiries = get_posts(array(
            'post_type' => 'harmat_offer_lead',
            'post_status' => 'trash',
            'posts_per_page' => 160,
            'orderby' => 'modified',
            'order' => 'DESC',
        ));
        foreach ($trashed_inquiries as $post) {
            $post_id = (int) $post->ID;
            if (!$this->can_restore_inquiry_record($post_id) && !$this->is_sales_manager_user()) {
                continue;
            }
            $data = $this->offer_inquiry_data($post_id);
            $deleted_at = get_post_meta($post_id, '_harmat_deleted_at', true);
            $deleted_by = (int) get_post_meta($post_id, '_harmat_deleted_by', true);
            $rows[] = array(
                'type' => 'inquiry',
                'trash_id' => '',
                'original_id' => $post_id,
                'client' => $data['name'],
                'contact' => trim(($data['phone'] ?: '') . ' ' . ($data['email'] ?: '')),
                'property' => $data['apartment'],
                'crm' => '',
                'assigned_sales_id' => $this->offer_inquiry_assigned_sales_id($post_id),
                'deleted_at' => $deleted_at ?: get_the_modified_date('Y-m-d H:i', $post_id),
                'deleted_by' => $deleted_by,
                'sort' => strtotime((string) ($deleted_at ?: get_post_modified_time('Y-m-d H:i:s', false, $post_id))) ?: 0,
                'can_restore' => $this->can_restore_inquiry_record($post_id),
                'can_purge' => $this->can_delete_sales_records(),
            );
        }

        usort($rows, function($a, $b) {
            return ((int) ($b['sort'] ?? 0)) <=> ((int) ($a['sort'] ?? 0));
        });

        echo '<section class="harmat-sales-panel">';
        echo '<div class="harmat-sales-panel-head"><div><h2>' . esc_html($text['title']) . '</h2><p>' . esc_html($text['intro']) . '</p></div><strong>' . esc_html((string) count($rows)) . '</strong></div>';
        if (!$rows) {
            echo '<div class="harmat-sales-empty">' . esc_html($text['empty']) . '</div></section>';
            return;
        }

        echo '<div class="harmat-sales-table-wrap"><table class="harmat-sales-table harmat-sales-trash-table"><thead><tr>';
        foreach ($text['headers'] as $header) {
            echo '<th>' . esc_html($header) . '</th>';
        }
        echo '</tr></thead><tbody>';
        foreach ($rows as $row) {
            $deleted_user = !empty($row['deleted_by']) ? get_userdata((int) $row['deleted_by']) : null;
            $type_labels = $text['types'];
            echo '<tr>';
            echo '<td><span class="harmat-sales-pill">' . esc_html($type_labels[$row['type']] ?? $row['type']) . '</span><small>#' . esc_html((string) $row['original_id']) . '</small></td>';
            echo '<td><strong>' . esc_html($this->sales_display_value($row['client'] ?: $text['no_client'], $lang)) . '</strong><small>' . esc_html($row['contact'] ?: '-') . '</small></td>';
            echo '<td><strong>' . esc_html($this->sales_display_value($row['property'] ?: '-', $lang)) . '</strong><small>' . esc_html($row['crm'] ?: '-') . '</small></td>';
            echo '<td>' . esc_html($this->assigned_sales_label((int) ($row['assigned_sales_id'] ?? 0))) . '</td>';
            echo '<td>' . esc_html($this->format_lead_datetime($row['deleted_at'] ?? '')) . '</td>';
            echo '<td>' . esc_html($deleted_user ? ($deleted_user->display_name ?: $deleted_user->user_login) : '-') . '</td>';
            echo '<td class="harmat-sales-actions">';
            if (!empty($row['can_restore'])) {
                echo '<form method="post">';
                wp_nonce_field('harmat_sales_action_restore_trash');
                echo '<input type="hidden" name="harmat_sales_action" value="restore_trash">';
                echo '<input type="hidden" name="trash_type" value="' . esc_attr($row['type']) . '">';
                if ($row['type'] === 'inquiry') {
                    echo '<input type="hidden" name="inquiry_id" value="' . esc_attr((int) $row['original_id']) . '">';
                } else {
                    echo '<input type="hidden" name="trash_id" value="' . esc_attr($row['trash_id']) . '">';
                }
                echo '<button type="submit">' . esc_html($text['restore']) . '</button>';
                echo '</form>';
            }
            if (!empty($row['can_purge'])) {
                echo '<form method="post">';
                wp_nonce_field('harmat_sales_action_purge_trash');
                echo '<input type="hidden" name="harmat_sales_action" value="purge_trash">';
                echo '<input type="hidden" name="trash_type" value="' . esc_attr($row['type']) . '">';
                if ($row['type'] === 'inquiry') {
                    echo '<input type="hidden" name="inquiry_id" value="' . esc_attr((int) $row['original_id']) . '">';
                } else {
                    echo '<input type="hidden" name="trash_id" value="' . esc_attr($row['trash_id']) . '">';
                }
                echo '<button type="submit" onclick="return confirm(\'' . esc_js($text['purge_confirm']) . '\')">' . esc_html($text['purge']) . '</button>';
                echo '</form>';
            }
            echo '</td>';
            echo '</tr>';
        }
        echo '</tbody></table></div></section>';
    }

    private function get_offer_inquiry_posts($limit = 20, $search = '') {
        $args = array(
            'post_type' => 'harmat_offer_lead',
            'post_status' => array('private', 'publish', 'draft'),
            'posts_per_page' => absint($limit),
            'orderby' => 'date',
            'order' => 'DESC',
        );
        if ($search !== '') {
            $args['s'] = $search;
        }

        return get_posts($args);
    }

    private function count_offer_inquiries() {
        $query = new WP_Query(array(
            'post_type' => 'harmat_offer_lead',
            'post_status' => array('private', 'publish', 'draft'),
            'posts_per_page' => 1,
            'fields' => 'ids',
        ));
        return (int) $query->found_posts;
    }

    private function count_offer_inquiries_on_date($date) {
        $query = new WP_Query(array(
            'post_type' => 'harmat_offer_lead',
            'post_status' => array('private', 'publish', 'draft'),
            'posts_per_page' => 1,
            'fields' => 'ids',
            'date_query' => array(
                array(
                    'after' => $date . ' 00:00:00',
                    'before' => $date . ' 23:59:59',
                    'inclusive' => true,
                ),
            ),
        ));
        return (int) $query->found_posts;
    }

    private function offer_inquiry_data($post_id) {
        $posted = get_post_meta($post_id, '_harmat_offer_posted', true);
        if (!is_array($posted)) {
            $posted = array();
        }

        $name = $this->inquiry_value($posted, 'your-name');
        if ($name === '') {
            $parts = explode(' - ', get_the_title($post_id));
            $name = trim($parts[0]);
            $name = preg_replace('/^Magán:\s*/u', '', $name);
        }

        $tracking = get_post_meta($post_id, '_harmat_offer_tracking', true);
        if (!is_array($tracking)) {
            $tracking = array();
        }
        $utm = get_post_meta($post_id, '_harmat_offer_utm', true);
        if (!is_array($utm)) {
            $utm = array();
        }
        if (isset($tracking['utm']) && is_array($tracking['utm'])) {
            $utm = array_merge($tracking['utm'], $utm);
        }
        $source_page = get_post_meta($post_id, '_harmat_offer_source_page', true);
        $lead_source = (string) ($tracking['lead_source'] ?? ($utm['lead_source'] ?? $this->inquiry_value($posted, 'lead_source')));
        if ($lead_source === '') {
            $lead_source = 'website';
        }

        return array(
            'name' => $name,
            'email' => get_post_meta($post_id, '_harmat_offer_email', true) ?: $this->inquiry_value($posted, 'your-email'),
            'phone' => get_post_meta($post_id, '_harmat_offer_phone', true) ?: $this->inquiry_value($posted, 'your-phone'),
            'apartment' => get_post_meta($post_id, '_harmat_offer_apartment', true) ?: $this->inquiry_value($posted, 'selected-apartment'),
            'date' => get_post_meta($post_id, '_harmat_offer_date', true) ?: $this->inquiry_value($posted, 'your-date'),
            'time' => get_post_meta($post_id, '_harmat_offer_time', true) ?: $this->inquiry_value($posted, 'your-time'),
            'area' => $this->inquiry_value($posted, 'selected-area'),
            'rooms' => $this->inquiry_value($posted, 'selected-rooms'),
            'price' => $this->inquiry_value($posted, 'selected-price'),
            'property_url' => $this->inquiry_value($posted, 'selected-url'),
            'message' => $this->inquiry_value($posted, 'your-message') ?: get_post_field('post_content', $post_id),
            'mail_status' => get_post_meta($post_id, '_harmat_offer_mail_status', true),
            'checked_at' => get_post_meta($post_id, '_harmat_offer_mail_checked_at', true),
            'crm_code' => get_post_meta($post_id, '_harmat_offer_crm_code', true),
            'lead_source' => $lead_source,
            'source_page' => esc_url_raw($source_page ?: ($tracking['source_page'] ?? ($utm['source_page'] ?? $this->inquiry_value($posted, 'source_url')))),
            'landing_page' => esc_url_raw($tracking['landing_page'] ?? ($utm['landing_page'] ?? $this->inquiry_value($posted, 'landing_page'))),
            'referrer' => esc_url_raw($tracking['referrer'] ?? ($utm['referrer'] ?? $this->inquiry_value($posted, 'referrer'))),
            'utm_source' => sanitize_text_field((string) ($tracking['utm_source'] ?? ($utm['utm_source'] ?? $this->inquiry_value($posted, 'utm_source')))),
            'utm_medium' => sanitize_text_field((string) ($tracking['utm_medium'] ?? ($utm['utm_medium'] ?? $this->inquiry_value($posted, 'utm_medium')))),
            'utm_campaign' => sanitize_text_field((string) ($tracking['utm_campaign'] ?? ($utm['utm_campaign'] ?? $this->inquiry_value($posted, 'utm_campaign')))),
            'utm_content' => sanitize_text_field((string) ($tracking['utm_content'] ?? ($utm['utm_content'] ?? $this->inquiry_value($posted, 'utm_content')))),
            'utm_term' => sanitize_text_field((string) ($tracking['utm_term'] ?? ($utm['utm_term'] ?? $this->inquiry_value($posted, 'utm_term')))),
            'privacy_consent' => $this->inquiry_value($posted, 'privacy-acceptance') !== '' ? 'accepted' : '',
            'marketing_consent' => $this->inquiry_value($posted, 'marketing-consent'),
            'security' => get_post_meta($post_id, '_harmat_offer_security', true),
            'ai_context' => get_post_meta($post_id, '_harmat_offer_ai_context', true),
            'ai_lead_details' => get_post_meta($post_id, '_harmat_offer_ai_lead_details', true),
            'crm_summary' => get_post_meta($post_id, '_harmat_offer_crm_summary', true),
            'conversation_summary' => get_post_meta($post_id, '_harmat_offer_conversation_summary', true) ?: (string) ($tracking['conversation_summary'] ?? ''),
            'customer_intent' => sanitize_text_field((string) ($tracking['customer_intent'] ?? '')),
            'preferred_room_count' => get_post_meta($post_id, '_harmat_offer_preferred_room_count', true) ?: (string) ($tracking['preferred_room_count'] ?? ''),
            'preferred_contact_time' => get_post_meta($post_id, '_harmat_offer_preferred_contact_time', true) ?: (string) ($tracking['preferred_contact_time'] ?? ''),
            'budget_range' => $this->inquiry_value($posted, 'budget_range'),
            'apartment_type' => $this->inquiry_value($posted, 'apartment_type'),
        );
    }

    private function render_agent_lead_row($lead) {
        $status_options = $this->lead_status_options();
        $status = isset($status_options[$lead['status']]) ? $lead['status'] : 'new';
        $property_title = $lead['property_id'] ? get_the_title((int) $lead['property_id']) : '';
        $broker = current_user_can(self::CAP_MANAGE) && !empty($lead['broker_id']) ? get_userdata((int) $lead['broker_id']) : null;
        $days_left = $this->lead_protection_days_left($lead);
        $protection_class = $days_left > 0 ? 'active' : 'expired';
        $protection_label = $days_left > 0 ? '剩余 ' . $days_left . ' 天' : '已过期';

        echo '<tr class="harmat-agent-lead-row harmat-agent-lead-' . esc_attr($status) . '">';
        echo '<td><strong>' . esc_html($lead['client_name']) . '</strong><small>' . esc_html($this->lead_source_label($lead)) . '</small></td>';
        echo '<td>' . esc_html($lead['phone'] ?: '-') . '</td>';
        echo '<td>' . esc_html($lead['email'] ?: '-') . '</td>';
        echo '<td>' . esc_html($property_title ?: '暂未指定') . '</td>';
        echo '<td><span class="harmat-agent-status-pill">' . esc_html($status_options[$status]) . '</span></td>';
        echo '<td>' . esc_html($this->format_lead_datetime($lead['created_at'] ?? '')) . '</td>';
        echo '<td><span class="harmat-agent-protection harmat-agent-protection-' . esc_attr($protection_class) . '">' . esc_html($protection_label) . '</span></td>';
        echo '<td>' . esc_html($this->format_followup_datetime($lead['next_followup'] ?? '')) . '</td>';
        if ($broker) {
            echo '<td>' . esc_html($broker->display_name) . '</td>';
        } elseif (current_user_can(self::CAP_MANAGE)) {
            echo '<td>-</td>';
        }
        echo '<td class="harmat-agent-note-cell">' . esc_html($lead['note'] ?: '-') . '</td>';
        echo '<td class="harmat-agent-actions"><a href="' . esc_url(add_query_arg('edit_lead', (int) $lead['id'], home_url('/agent/'))) . '">编辑</a>';
        if ($this->can_delete_sales_records()) {
            echo '<form method="post">';
            wp_nonce_field('harmat_sales_action_delete_lead');
            echo '<input type="hidden" name="harmat_sales_action" value="delete_lead">';
            echo '<input type="hidden" name="return_to" value="agent_clients">';
            echo '<input type="hidden" name="lead_id" value="' . esc_attr($lead['id']) . '">';
            echo '<button onclick="return confirm(\'确定删除这个客户记录吗？\')">删除</button>';
            echo '</form>';
        }
        echo '</td></tr>';
    }

    private function render_inquiries() {
        $search = isset($_GET['inquiry_s']) ? sanitize_text_field(wp_unslash($_GET['inquiry_s'])) : '';
        $query_args = array(
            'post_type' => 'harmat_offer_lead',
            'post_status' => array('private', 'publish', 'draft'),
            'posts_per_page' => 80,
            'orderby' => 'date',
            'order' => 'DESC',
            's' => $search,
        );
        $query = new WP_Query($query_args);

        echo '<div class="harmat-inquiry-toolbar">';
        echo '<div><h2>网站询价记录</h2><p>这里显示客户从网站表单提交的询价、预约和房源选择信息。只有销售管理账号可以查看。</p></div>';
        echo '<form method="get" class="harmat-inquiry-search">';
        echo '<input type="hidden" name="page" value="' . esc_attr(self::PAGE_SLUG) . '">';
        echo '<input type="hidden" name="tab" value="inquiries">';
        echo '<input type="search" name="inquiry_s" value="' . esc_attr($search) . '" placeholder="搜索客户、邮箱、房号">';
        echo '<button class="button">搜索</button>';
        if ($search !== '') {
            echo '<a class="button" href="' . esc_url($this->page_url(array('tab' => 'inquiries'))) . '">清除</a>';
        }
        echo '</form></div>';

        echo '<div class="harmat-inquiry-summary">';
        echo '<span>当前显示 <b>' . esc_html((string) $query->post_count) . '</b></span>';
        echo '<span>来源 <b>网站表单</b></span>';
        echo '<span>权限 <b>销售管理</b></span>';
        echo '</div>';

        if (!$query->have_posts()) {
            echo '<div class="harmat-empty-state">目前没有找到网站询价记录。</div>';
            wp_reset_postdata();
            return;
        }

        echo '<div class="harmat-inquiry-grid">';
        while ($query->have_posts()) {
            $query->the_post();
            $this->render_inquiry_card(get_the_ID());
        }
        echo '</div>';
        wp_reset_postdata();
    }

    private function render_inquiry_card($post_id) {
        $posted = get_post_meta($post_id, '_harmat_offer_posted', true);
        if (!is_array($posted)) {
            $posted = array();
        }

        $name = $this->inquiry_value($posted, 'your-name');
        if ($name === '') {
            $parts = explode(' - ', get_the_title($post_id));
            $name = trim($parts[0]);
        }

        $email = get_post_meta($post_id, '_harmat_offer_email', true);
        if ($email === '') {
            $email = $this->inquiry_value($posted, 'your-email');
        }

        $phone = get_post_meta($post_id, '_harmat_offer_phone', true);
        if ($phone === '') {
            $phone = $this->inquiry_value($posted, 'your-phone');
        }

        $apartment = get_post_meta($post_id, '_harmat_offer_apartment', true);
        if ($apartment === '') {
            $apartment = $this->inquiry_value($posted, 'selected-apartment');
        }

        $date = get_post_meta($post_id, '_harmat_offer_date', true);
        if ($date === '') {
            $date = $this->inquiry_value($posted, 'your-date');
        }

        $time = get_post_meta($post_id, '_harmat_offer_time', true);
        if ($time === '') {
            $time = $this->inquiry_value($posted, 'your-time');
        }

        $area = $this->inquiry_value($posted, 'selected-area');
        $rooms = $this->inquiry_value($posted, 'selected-rooms');
        $price = $this->inquiry_value($posted, 'selected-price');
        $property_url = $this->inquiry_value($posted, 'selected-url');
        $message = $this->inquiry_value($posted, 'your-message');
        if ($message === '') {
            $message = get_post_field('post_content', $post_id);
        }
        $ai_context = get_post_meta($post_id, '_harmat_offer_ai_context', true);
        $ai_conversation = get_post_meta($post_id, '_harmat_offer_conversation_summary', true);
        $ai_lead_details = get_post_meta($post_id, '_harmat_offer_ai_lead_details', true);
        $crm_summary = trim((string) get_post_meta($post_id, '_harmat_offer_crm_summary', true));
        if (!is_array($ai_lead_details)) {
            $ai_lead_details = array();
        }
        $mail_status = get_post_meta($post_id, '_harmat_offer_mail_status', true);
        $checked_at = get_post_meta($post_id, '_harmat_offer_mail_checked_at', true);

        echo '<article class="harmat-inquiry-card">';
        echo '<header>';
        echo '<div><h3>' . esc_html($name ?: '未填写姓名') . '</h3>';
        echo '<p>' . esc_html(get_the_date('Y-m-d H:i:s', $post_id)) . '</p></div>';
        echo '<span>' . esc_html($apartment ?: '未选择房源') . '</span>';
        echo '</header>';
        echo '<dl class="harmat-inquiry-details">';
        echo '<div><dt>电话</dt><dd>' . esc_html($phone ?: '-') . '</dd></div>';
        echo '<div><dt>邮箱</dt><dd>' . esc_html($email ?: '-') . '</dd></div>';
        echo '<div><dt>看房日期</dt><dd>' . esc_html($date ?: '-') . '</dd></div>';
        echo '<div><dt>时间段</dt><dd>' . esc_html($time ?: '-') . '</dd></div>';
        echo '<div><dt>面积</dt><dd>' . esc_html($area ?: '-') . '</dd></div>';
        echo '<div><dt>房间</dt><dd>' . esc_html($rooms ?: '-') . '</dd></div>';
        echo '<div><dt>价格显示</dt><dd>' . esc_html($price ?: '-') . '</dd></div>';
        echo '<div><dt>邮件状态</dt><dd>' . esc_html($mail_status ?: '-') . ($checked_at ? '<small>' . esc_html($checked_at) . '</small>' : '') . '</dd></div>';
        echo '</dl>';
        if ($message !== '') {
            echo '<div class="harmat-inquiry-message"><strong>客户留言</strong><p>' . nl2br(esc_html($message)) . '</p></div>';
        }
        if ($crm_summary !== '') {
            echo '<div class="harmat-inquiry-message harmat-inquiry-crm-summary"><strong>AI CRM 摘要</strong><p>' . nl2br(esc_html($crm_summary)) . '</p></div>';
        }
        if ($ai_context !== '' || $ai_conversation !== '' || !empty($ai_lead_details)) {
            echo '<details class="harmat-inquiry-message harmat-inquiry-ai-log">';
            echo '<summary class="button">查看 AI 聊天记录</summary>';
            if (!empty($ai_lead_details)) {
                echo '<p><strong>AI 提取需求</strong><br>';
                foreach ($ai_lead_details as $detail_key => $detail_value) {
                    if ((string) $detail_value === '') {
                        continue;
                    }
                    echo esc_html($detail_key . ': ' . $detail_value) . '<br>';
                }
                echo '</p>';
            }
            if ($ai_context !== '') {
                echo '<p><strong>触发上下文</strong><br>' . nl2br(esc_html($ai_context)) . '</p>';
            }
            if ($ai_conversation !== '') {
                echo '<p><strong>聊天摘要</strong><br>' . nl2br(esc_html($ai_conversation)) . '</p>';
            }
            echo '</details>';
        }
        echo '<footer>';
        if ($property_url !== '') {
            echo '<a class="button" href="' . esc_url($property_url) . '" target="_blank" rel="noopener">打开房源</a>';
        }
        echo '<a class="button" href="' . esc_url(get_edit_post_link($post_id, '')) . '" target="_blank" rel="noopener">后台原始记录</a>';
        if ($this->can_delete_sales_records()) {
            echo '<form method="post" class="harmat-inline-form">';
            wp_nonce_field('harmat_sales_action_delete_inquiry');
            echo '<input type="hidden" name="harmat_sales_action" value="delete_inquiry">';
            echo '<input type="hidden" name="inquiry_id" value="' . esc_attr($post_id) . '">';
            echo '<button class="button button-link-delete" onclick="return confirm(\'确定删除这个网站询价记录吗？\')">删除</button>';
            echo '</form>';
        }
        echo '</footer>';
        echo '</article>';
    }

    private function inquiry_value($posted, $key) {
        if (!isset($posted[$key])) {
            return '';
        }
        if (is_array($posted[$key])) {
            return implode(', ', array_map('sanitize_text_field', $posted[$key]));
        }
        return sanitize_text_field((string) $posted[$key]);
    }

    private function limit_text($text, $max_chars) {
        $text = trim((string) $text);
        $max_chars = max(1, (int) $max_chars);
        if (function_exists('mb_substr')) {
            return mb_substr($text, 0, $max_chars, 'UTF-8');
        }
        return substr($text, 0, $max_chars);
    }

    private function render_leads() {
        $all_leads = $this->get_leads();
        $visible_leads = $this->visible_leads($all_leads);
        $edit_id = isset($_GET['edit_lead']) ? absint($_GET['edit_lead']) : 0;
        $editing = array();

        if ($edit_id && isset($all_leads[$edit_id])) {
            if (
                current_user_can(self::CAP_MANAGE)
                || (int) $all_leads[$edit_id]['broker_id'] === get_current_user_id()
                || (int) ($all_leads[$edit_id]['assigned_sales_id'] ?? 0) === get_current_user_id()
            ) {
                $editing = $all_leads[$edit_id];
            }
        }

        $defaults = array(
            'id' => 0,
            'broker_id' => get_current_user_id(),
            'client_name' => '',
            'phone' => '',
            'email' => '',
            'property_id' => 0,
            'status' => 'new',
            'source' => '',
            'next_followup' => '',
            'note' => '',
        );
        $form = array_merge($defaults, $editing);
        $status_counts = array_fill_keys(array_keys($this->lead_status_options()), 0);
        foreach ($visible_leads as $lead) {
            if (isset($status_counts[$lead['status']])) {
                $status_counts[$lead['status']]++;
            }
        }

        echo '<div class="harmat-lead-summary">';
        echo '<span>客户总数 <b>' . count($visible_leads) . '</b></span>';
        echo '<span>新客户 <b>' . (int) $status_counts['new'] . '</b></span>';
        echo '<span>已看房 <b>' . (int) $status_counts['visited'] . '</b></span>';
        echo '<span>已成交 <b>' . (int) $status_counts['closed'] . '</b></span>';
        echo '</div>';

        echo '<div class="harmat-leads-layout">';
        echo '<div class="harmat-card harmat-lead-editor">';
        echo '<h2>' . ($form['id'] ? '编辑客户跟进' : '新增客户跟进') . '</h2>';
        echo '<p>经纪人只能看到和维护自己录入的客户；销售管理可以查看全部客户跟进。</p>';
        echo '<form method="post" class="harmat-lead-form">';
        wp_nonce_field('harmat_sales_action_save_lead');
        echo '<input type="hidden" name="harmat_sales_action" value="save_lead">';
        echo '<input type="hidden" name="lead_id" value="' . esc_attr($form['id']) . '">';
        echo '<label>' . esc_html($text['editor']['client_name']) . '<input required name="client_name" value="' . esc_attr($form['client_name']) . '" placeholder="' . esc_attr($text['editor']['client_name']) . '"></label>';
        echo '<label>' . esc_html($text['editor']['phone']) . '<input name="client_phone" value="' . esc_attr($form['phone']) . '" placeholder="+36..."></label>';
        echo '<label>' . esc_html($text['editor']['email']) . '<input type="email" name="client_email" value="' . esc_attr($form['email']) . '" placeholder="name@email.com"></label>';
        echo '<label>来源<select name="client_source">';
        $current_source = $this->normalize_lead_source_type($form['source'], (int) ($form['broker_id'] ?? 0));
        foreach ($this->deal_source_options() as $value => $label) {
            echo '<option value="' . esc_attr($value) . '"' . selected($current_source, $value, false) . '>' . esc_html($label) . '</option>';
        }
        echo '</select></label>';
        echo '<label>' . esc_html($text['editor']['property']) . '<select name="property_id">';
        echo '<option value="0">' . esc_html($text['editor']['property_none']) . '</option>';
        foreach ($this->get_properties() as $property) {
            echo '<option value="' . esc_attr($property->ID) . '"' . selected((int) $form['property_id'], (int) $property->ID, false) . '>' . esc_html(get_the_title($property)) . '</option>';
        }
        echo '</select></label>';
        echo '<label>跟进状态<select name="lead_status">';
        foreach ($this->lead_status_options() as $value => $label) {
            echo '<option value="' . esc_attr($value) . '"' . selected($form['status'], $value, false) . '>' . esc_html($label) . '</option>';
        }
        echo '</select></label>';
        echo '<label>' . esc_html($text['editor']['next_followup']) . '<input type="datetime-local" name="next_followup" value="' . esc_attr($this->followup_input_value($form['next_followup'])) . '"></label>';
        if (current_user_can(self::CAP_MANAGE)) {
            echo '<label>负责经纪人<select name="broker_id">';
            foreach ($this->get_sales_users() as $user) {
                echo '<option value="' . esc_attr($user->ID) . '"' . selected((int) $form['broker_id'], (int) $user->ID, false) . '>' . esc_html($user->display_name . ' (' . $user->user_login . ')') . '</option>';
            }
            echo '</select></label>';
        }
        echo '<label class="harmat-lead-note">备注<textarea name="client_note" rows="4" placeholder="客户预算、看房意向、沟通记录等">' . esc_textarea($form['note']) . '</textarea></label>';
        echo '<div class="harmat-lead-actions"><button class="button button-primary button-hero">' . ($form['id'] ? '保存修改' : '新增客户') . '</button>';
        if ($form['id']) {
            echo '<a class="button" href="' . esc_url($this->page_url(array('tab' => 'leads'))) . '">' . esc_html($text['editor']['cancel']) . '</a>';
        }
        echo '</div>';
        echo '</form>';
        echo '</div>';

        echo '<div class="harmat-lead-list">';
        echo '<h2>客户跟进列表</h2>';
        if (!$visible_leads) {
            echo '<div class="harmat-empty-state">目前还没有客户记录。先录入一个客户，后续可以继续扩展成交、合同和客户门户联动。</div>';
        } else {
            echo '<div class="harmat-lead-table-wrap"><table class="widefat striped harmat-lead-table">';
            echo '<thead><tr>';
            echo '<th>客户</th><th>联系方式</th><th>意向房源</th><th>状态</th><th>登记时间</th><th>保护到期</th><th>保护状态</th><th>下次跟进</th>';
            if (current_user_can(self::CAP_MANAGE)) {
                echo '<th>负责经纪人</th>';
            }
            echo '<th>备注</th><th>操作</th>';
            echo '</tr></thead><tbody>';
            foreach ($visible_leads as $lead) {
                $this->render_lead_table_row($lead);
            }
            echo '</tbody></table></div>';
        }
        echo '</div></div>';
    }

    private function render_lead_table_row($lead) {
        $status_options = $this->lead_status_options();
        $status = isset($status_options[$lead['status']]) ? $lead['status'] : 'new';
        $property_title = $lead['property_id'] ? get_the_title((int) $lead['property_id']) : '';
        $property_url = $lead['property_id'] ? get_permalink((int) $lead['property_id']) : '';
        $broker = !empty($lead['broker_id']) ? get_userdata((int) $lead['broker_id']) : null;
        $days_left = $this->lead_protection_days_left($lead);
        $protection_class = $days_left > 0 ? 'active' : 'expired';
        $protection_label = $days_left > 0 ? '保护中 / 剩余 ' . $days_left . ' 天' : '已过期';
        $created_at = $this->format_lead_datetime($lead['created_at'] ?? '');
        $expires_at = $this->lead_protection_expires_at($lead);

        echo '<tr class="harmat-lead-row harmat-lead-' . esc_attr($status) . '">';
        echo '<td class="harmat-lead-customer"><strong>' . esc_html($lead['client_name']) . '</strong><small>' . esc_html($this->lead_source_label($lead)) . '</small></td>';
        echo '<td><span>' . esc_html($lead['phone'] ?: '-') . '</span><small>' . esc_html($lead['email'] ?: '-') . '</small></td>';
        echo '<td>';
        if ($property_title && $property_url) {
            echo '<a href="' . esc_url($property_url) . '" target="_blank" rel="noopener">' . esc_html($property_title) . '</a>';
        } else {
            echo '暂未指定';
        }
        echo '</td>';
        echo '<td><span class="harmat-lead-status-pill harmat-lead-status-' . esc_attr($status) . '">' . esc_html($status_options[$status]) . '</span></td>';
        echo '<td>' . esc_html($created_at) . '</td>';
        echo '<td>' . esc_html($expires_at ?: '-') . '</td>';
        echo '<td><span class="harmat-lead-protection harmat-lead-protection-' . esc_attr($protection_class) . '">' . esc_html($protection_label) . '</span></td>';
        echo '<td>' . esc_html($this->format_followup_datetime($lead['next_followup'] ?? '')) . '</td>';
        if (current_user_can(self::CAP_MANAGE)) {
            echo '<td>' . esc_html($broker ? $broker->display_name : '-') . '</td>';
        }
        echo '<td class="harmat-lead-table-note">' . esc_html($lead['note'] ?: '-') . '</td>';
        echo '<td class="harmat-lead-table-actions">';
        echo '<a class="button button-small" href="' . esc_url($this->page_url(array('tab' => 'leads', 'edit_lead' => (int) $lead['id']))) . '">编辑</a>';
        if ($this->can_delete_sales_records()) {
            echo '<form method="post" class="harmat-inline-form">';
            wp_nonce_field('harmat_sales_action_delete_lead');
            echo '<input type="hidden" name="harmat_sales_action" value="delete_lead">';
            echo '<input type="hidden" name="lead_id" value="' . esc_attr($lead['id']) . '">';
            echo '<button class="button button-small button-link-delete" onclick="return confirm(\'确定删除这个客户跟进记录吗？\')">删除</button>';
            echo '</form>';
        }
        echo '<small>更新：' . esc_html($this->format_lead_datetime($lead['updated_at'] ?? '')) . '</small>';
        echo '</td>';
        echo '</tr>';
    }

    private function render_lead_card($lead) {
        $status_options = $this->lead_status_options();
        $status = isset($status_options[$lead['status']]) ? $lead['status'] : 'new';
        $property_title = $lead['property_id'] ? get_the_title((int) $lead['property_id']) : '';
        $property_url = $lead['property_id'] ? get_permalink((int) $lead['property_id']) : '';
        $broker = !empty($lead['broker_id']) ? get_userdata((int) $lead['broker_id']) : null;

        echo '<article class="harmat-lead-card harmat-lead-' . esc_attr($status) . '">';
        echo '<div class="harmat-lead-card-head">';
        echo '<div><h3>' . esc_html($lead['client_name']) . '</h3>';
        echo '<p>' . esc_html($this->lead_source_label($lead)) . '</p></div>';
        echo '<span>' . esc_html($status_options[$status]) . '</span>';
        echo '</div>';
        echo '<dl>';
        echo '<div><dt>电话</dt><dd>' . esc_html($lead['phone'] ?: '-') . '</dd></div>';
        echo '<div><dt>邮箱</dt><dd>' . esc_html($lead['email'] ?: '-') . '</dd></div>';
        echo '<div><dt>意向房源</dt><dd>';
        if ($property_title && $property_url) {
            echo '<a href="' . esc_url($property_url) . '" target="_blank" rel="noopener">' . esc_html($property_title) . '</a>';
        } else {
            echo '-';
        }
        echo '</dd></div>';
        echo '<div><dt>下次跟进</dt><dd>' . esc_html($this->format_followup_datetime($lead['next_followup'] ?? '')) . '</dd></div>';
        if (current_user_can(self::CAP_MANAGE)) {
            echo '<div><dt>负责经纪人</dt><dd>' . esc_html($broker ? $broker->display_name : '-') . '</dd></div>';
        }
        echo '</dl>';
        if (!empty($lead['note'])) {
            echo '<p class="harmat-lead-note-preview">' . nl2br(esc_html($lead['note'])) . '</p>';
        }
        echo '<div class="harmat-lead-card-actions">';
        echo '<a class="button" href="' . esc_url($this->page_url(array('tab' => 'leads', 'edit_lead' => (int) $lead['id']))) . '">编辑</a>';
        if ($this->can_delete_sales_records()) {
            echo '<form method="post" class="harmat-inline-form">';
            wp_nonce_field('harmat_sales_action_delete_lead');
            echo '<input type="hidden" name="harmat_sales_action" value="delete_lead">';
            echo '<input type="hidden" name="lead_id" value="' . esc_attr($lead['id']) . '">';
            echo '<button class="button button-link-delete" onclick="return confirm(\'确定删除这个客户跟进记录吗？\')">删除</button>';
            echo '</form>';
        }
        echo '<small>更新：' . esc_html($lead['updated_at'] ?: '-') . '</small>';
        echo '</div>';
        echo '</article>';
    }

    private function get_leads() {
        $raw = get_option('harmat_broker_leads_v1', array());
        if (!is_array($raw)) {
            return array();
        }

        $leads = array();
        foreach ($raw as $key => $lead) {
            if (!is_array($lead)) {
                continue;
            }
            $id = !empty($lead['id']) ? absint($lead['id']) : absint($key);
            if (!$id) {
                continue;
            }
            $leads[$id] = array_merge(array(
                'id' => $id,
                'broker_id' => 0,
                'assigned_sales_id' => 0,
                'client_name' => '',
                'phone' => '',
                'email' => '',
                'property_id' => 0,
                'status' => 'new',
                'source' => '',
                'next_followup' => '',
                'note' => '',
                'created_at' => '',
                'updated_at' => '',
                'updated_by' => 0,
            ), $lead);
            $leads[$id]['id'] = $id;
        }

        return $leads;
    }

    private function save_leads($leads) {
        update_option('harmat_broker_leads_v1', $leads, false);
    }

    private function next_lead_id($leads) {
        $ids = array_map('absint', array_keys($leads));
        return $ids ? max($ids) + 1 : 1;
    }

    private function get_deals() {
        $raw = get_option('harmat_sales_deals_v1', array());
        if (!is_array($raw)) {
            return array();
        }

        $deals = array();
        foreach ($raw as $key => $deal) {
            if (!is_array($deal)) {
                continue;
            }
            $id = !empty($deal['id']) ? absint($deal['id']) : absint($key);
            if (!$id) {
                continue;
            }
            $deals[$id] = array_merge(array(
                'id' => $id,
                'crm_code' => '',
                'lead_id' => 0,
                'inquiry_id' => 0,
                'source_type' => '',
                'property_id' => 0,
                'parking_space' => '',
                'storage_unit' => '',
                'broker_id' => 0,
                'assigned_sales_id' => 0,
                'stage' => 'new',
                'client_name' => '',
                'phone' => '',
                'email' => '',
                'amount' => '',
                'deposit' => '',
                'payment_received' => '',
                'expected_close' => '',
                'next_followup' => '',
                'next_step' => '',
                'last_contacted_at' => '',
                'sales_followup_note' => '',
                'payment_method' => '',
                'payment_due_date' => '',
                'payment_status' => '',
                'payment_schedule' => '',
                'payment_plan_items' => array(),
                'document_checklist' => array(),
                'contract_status' => '',
                'handover_note' => '',
                'aftercare_note' => '',
                'closed_at' => '',
                'commission_rate' => '',
                'commission_amount' => '',
                'commission_due_date' => '',
                'commission_status' => '',
                'commission_note' => '',
                'note' => '',
                'customer_user_id' => 0,
                'customer_account_created_at' => '',
                'customer_account_sent_at' => '',
                'customer_materials' => array(),
                'customer_requests' => array(),
                'created_at' => '',
                'updated_at' => '',
                'updated_by' => 0,
            ), $deal);
            $deals[$id]['id'] = $id;
            $deals[$id]['stage'] = $this->normalize_deal_stage_key($deals[$id]['stage'] ?? '');
            if (empty($deals[$id]['crm_code'])) {
                $deals[$id]['crm_code'] = $this->generate_deal_crm_code($id, $deals[$id]['created_at'] ?? '');
            }
            if (empty($deals[$id]['source_type']) || !isset($this->deal_source_options()[$deals[$id]['source_type']])) {
                if (!empty($deals[$id]['inquiry_id'])) {
                    $deals[$id]['source_type'] = 'website';
                } elseif (!empty($deals[$id]['commission_rate']) || !empty($deals[$id]['commission_amount'])) {
                    $deals[$id]['source_type'] = 'broker';
                } else {
                    $deals[$id]['source_type'] = 'walkin';
                }
            }
        }

        uasort($deals, function($a, $b) {
            return strcmp((string) ($b['updated_at'] ?? ''), (string) ($a['updated_at'] ?? ''));
        });

        return $deals;
    }

    private function save_deals($deals) {
        update_option('harmat_sales_deals_v1', $deals, false);
    }

    private function next_deal_id($deals) {
        $ids = array_map('absint', array_keys($deals));
        return $ids ? max($ids) + 1 : 1;
    }

    private function find_deal_by_inquiry_id($inquiry_id, $deals = null, $exclude_deal_id = 0) {
        $inquiry_id = absint($inquiry_id);
        if (!$inquiry_id) {
            return null;
        }
        if ($deals === null) {
            $deals = $this->get_deals();
        }
        foreach ($deals as $deal) {
            if ((int) ($deal['id'] ?? 0) === (int) $exclude_deal_id) {
                continue;
            }
            if ((int) ($deal['inquiry_id'] ?? 0) === $inquiry_id) {
                return $deal;
            }
        }
        return null;
    }

    private function find_deal_by_lead_id($lead_id, $deals = null, $exclude_deal_id = 0) {
        $lead_id = absint($lead_id);
        if (!$lead_id) {
            return null;
        }
        if ($deals === null) {
            $deals = $this->get_deals();
        }
        foreach ($deals as $deal) {
            if ((int) ($deal['id'] ?? 0) === (int) $exclude_deal_id) {
                continue;
            }
            if ((int) ($deal['lead_id'] ?? 0) === $lead_id) {
                return $deal;
            }
        }
        return null;
    }

    private function sales_duplicate_contact_dataset($current_deal_id = 0) {
        $items = array();
        foreach ($this->visible_deals($this->get_deals()) as $deal) {
            if ((int) ($deal['id'] ?? 0) === (int) $current_deal_id) {
                continue;
            }
            $this->add_duplicate_contact_item(
                $items,
                '销售跟单 #' . (int) ($deal['id'] ?? 0),
                (int) ($deal['id'] ?? 0),
                $deal['client_name'] ?? '',
                $deal['phone'] ?? '',
                $deal['email'] ?? '',
                $this->sales_portal_url(array('view' => 'deals', 'edit_deal' => (int) ($deal['id'] ?? 0))),
                'deal'
            );
        }

        foreach ($this->visible_leads($this->get_leads()) as $lead) {
            $this->add_duplicate_contact_item(
                $items,
                '客户档案 #' . (int) ($lead['id'] ?? 0),
                (int) ($lead['id'] ?? 0),
                $lead['client_name'] ?? '',
                $lead['phone'] ?? '',
                $lead['email'] ?? '',
                $this->sales_portal_url(array('view' => 'clients', 'edit_lead' => (int) ($lead['id'] ?? 0))),
                'lead'
            );
        }

        $can_manage = $this->is_sales_manager_user();
        $current_user_id = get_current_user_id();
        foreach ($this->get_offer_inquiry_posts(120) as $inquiry_post) {
            $assigned_sales_id = $this->offer_inquiry_assigned_sales_id((int) $inquiry_post->ID);
            if (!$can_manage && $assigned_sales_id !== $current_user_id) {
                continue;
            }
            $data = $this->offer_inquiry_data((int) $inquiry_post->ID);
            $this->add_duplicate_contact_item(
                $items,
                '网站询价 #' . (int) $inquiry_post->ID,
                (int) $inquiry_post->ID,
                $data['name'],
                $data['phone'],
                $data['email'],
                $this->sales_portal_url(array('view' => 'inquiries')),
                'inquiry'
            );
        }

        return array_values($items);
    }

    private function sales_find_lead_by_contact($client_name, $phone, $email, $leads = null) {
        $leads = is_array($leads) ? $leads : $this->get_leads();
        $email_key = strtolower(sanitize_email((string) $email));
        $phone_key = $this->normalize_contact_phone($phone);
        $name_key = $this->normalize_lead_name($client_name);
        $best = null;
        $best_score = 0;

        foreach ($leads as $lead) {
            if (!$this->can_view_lead($lead)) {
                continue;
            }
            $score = 0;
            if ($email_key !== '' && strtolower(sanitize_email((string) ($lead['email'] ?? ''))) === $email_key) {
                $score += 60;
            }
            if ($phone_key !== '' && $this->normalize_contact_phone($lead['phone'] ?? '') === $phone_key) {
                $score += 60;
            }
            if ($name_key !== '' && !empty($lead['client_name'])) {
                similar_text($name_key, $this->normalize_lead_name($lead['client_name']), $percent);
                if ($percent >= 86) {
                    $score += 12;
                }
            }
            if ($score > $best_score) {
                $best_score = $score;
                $best = $lead;
            }
        }

        return $best_score >= 60 ? $best : null;
    }

    private function add_duplicate_contact_item(&$items, $source_label, $source_id, $client_name, $phone, $email, $url = '', $kind = '') {
        $email = sanitize_email((string) $email);
        $phone_digits = $this->normalize_contact_phone($phone);
        if ($email === '' && $phone_digits === '') {
            return;
        }
        $items[] = array(
            'source' => (string) $source_label,
            'id' => absint($source_id),
            'client' => sanitize_text_field((string) $client_name),
            'phone' => (string) $phone,
            'phone_digits' => $phone_digits,
            'email' => strtolower($email),
            'url' => esc_url_raw($url),
            'kind' => sanitize_key((string) $kind),
        );
    }

    private function sales_duplicate_matches_for_contact($client_name, $phone, $email, $current_deal_id = 0, $exclude_lead_id = 0, $exclude_inquiry_id = 0) {
        $email_key = strtolower(sanitize_email((string) $email));
        $phone_key = $this->normalize_contact_phone($phone);
        $name_key = $this->normalize_lead_name($client_name);
        $matches = array();
        $current_deal = $current_deal_id ? ($this->get_deals()[(int) $current_deal_id] ?? null) : null;
        $current_inquiry_id = $exclude_inquiry_id ?: ($current_deal ? (int) ($current_deal['inquiry_id'] ?? 0) : 0);
        $current_lead_id = $exclude_lead_id ?: ($current_deal ? (int) ($current_deal['lead_id'] ?? 0) : 0);

        foreach ($this->sales_duplicate_contact_dataset((int) $current_deal_id) as $item) {
            $item_source = (string) ($item['source'] ?? '');
            if ($current_inquiry_id && (int) ($item['id'] ?? 0) === $current_inquiry_id && (($item['kind'] ?? '') === 'inquiry' || strpos($item_source, '询价') !== false)) {
                continue;
            }
            if ($current_lead_id && (int) ($item['id'] ?? 0) === $current_lead_id && (($item['kind'] ?? '') === 'lead' || strpos($item_source, '客户跟进') !== false || strpos($item_source, '客户档案') !== false)) {
                continue;
            }
            $matched_by = array();
            if ($email_key !== '' && !empty($item['email']) && strtolower((string) $item['email']) === $email_key) {
                $matched_by[] = 'e-mail';
            }
            if ($phone_key !== '' && !empty($item['phone_digits']) && (string) $item['phone_digits'] === $phone_key) {
                $matched_by[] = 'telefon';
            }
            if (!$matched_by && $name_key !== '' && !empty($item['client'])) {
                similar_text($name_key, $this->normalize_lead_name($item['client']), $percent);
                if ($percent >= 86) {
                    $matched_by[] = 'hasonló név';
                }
            }
            if ($matched_by) {
                $item['matched_by'] = implode(', ', $matched_by);
                $matches[] = $item;
            }
            if (count($matches) >= 6) {
                break;
            }
        }

        return $matches;
    }

    private function render_sales_duplicate_contact_notice($deal, $lang = null) {
        $lang = $lang === null || $lang === '' ? $this->active_sales_language() : $lang;
        $lang = $lang === 'hu' ? 'hu' : 'zh';
        $text = $this->sales_customers_page_text('duplicate', $lang);
        $matches = $this->sales_duplicate_matches_for_contact(
            $deal['client_name'] ?? '',
            $deal['phone'] ?? '',
            $deal['email'] ?? '',
            (int) ($deal['id'] ?? 0)
        );
        if (!$matches) {
            return;
        }

        echo '<section class="harmat-sales-panel harmat-sales-duplicate-panel">';
        echo '<div class="harmat-sales-panel-head"><div><h2>' . esc_html($text['title']) . '</h2><p>' . esc_html($text['intro']) . '</p></div></div>';
        echo '<div class="harmat-sales-duplicate-list">';
        foreach ($matches as $match) {
            $kind = sanitize_key((string) ($match['kind'] ?? ''));
            $source_label = (string) ($match['source'] ?? '-');
            if ($kind !== '' && !empty($text['sources'][$kind])) {
                $source_label = $text['sources'][$kind] . ' #' . (int) ($match['id'] ?? 0);
            }
            echo '<article>';
            echo '<strong>' . esc_html($match['client'] ?: $text['no_client']) . '</strong>';
            echo '<span>' . esc_html($source_label) . '</span>';
            echo '<small>' . esc_html(($match['matched_by'] ?? '-') . ' / ' . (($match['email'] ?? '') ?: ($match['phone'] ?? '-'))) . '</small>';
            if (!empty($match['url'])) {
                echo '<a href="' . esc_url($match['url']) . '">' . esc_html($text['open']) . '</a>';
            }
            echo '</article>';
        }
        echo '</div></section>';
    }

    private function sales_registered_property_dataset($current_lead_id = 0, $current_deal_id = 0) {
        $items = array();
        foreach ($this->get_deals() as $deal) {
            $property_id = (int) ($deal['property_id'] ?? 0);
            if (!$property_id || (int) ($deal['id'] ?? 0) === (int) $current_deal_id) {
                continue;
            }
            $stage = $this->normalize_deal_stage_key($deal['stage'] ?? '');
            if (!$this->deal_stage_locks_property($stage)) {
                continue;
            }
            $url = $this->can_view_deal($deal) ? $this->sales_portal_url(array('view' => 'deals', 'edit_deal' => (int) ($deal['id'] ?? 0))) : '';
            $this->add_registered_property_item($items, $property_id, '销售跟单 #' . (int) ($deal['id'] ?? 0), $deal['client_name'] ?? '', $this->deal_stage_options()[$stage] ?? $stage, $url);
        }

        foreach ($this->get_leads() as $lead) {
            $property_id = (int) ($lead['property_id'] ?? 0);
            if (!$property_id || (int) ($lead['id'] ?? 0) === (int) $current_lead_id) {
                continue;
            }
            $status = (string) ($lead['status'] ?? '');
            if ($status !== 'reserved') {
                continue;
            }
            $url = in_array($lead, $this->visible_leads(array($lead)), true) ? $this->sales_portal_url(array('view' => 'clients', 'edit_lead' => (int) ($lead['id'] ?? 0))) : '';
            $this->add_registered_property_item($items, $property_id, '客户跟进 #' . (int) ($lead['id'] ?? 0), $lead['client_name'] ?? '', $this->lead_status_options()[$status] ?? $status, $url);
        }

        foreach ($this->get_properties() as $property) {
            $property_id = (int) $property->ID;
            $status = $this->sales_status($property_id);
            if (!in_array($status, array('reserved', 'sold'), true)) {
                continue;
            }
            $property_status_options = $this->status_options($this->active_sales_language());
            $this->add_registered_property_item($items, $property_id, '房源库存', '', $property_status_options[$status] ?? $status, $this->sales_portal_url(array('view' => 'properties', 'sales_search' => get_the_title($property_id))));
        }

        return array_values($items);
    }

    private function add_registered_property_item(&$items, $property_id, $source, $client_name, $state, $url = '') {
        $property_id = absint($property_id);
        if (!$property_id || get_post_type($property_id) !== 'property') {
            return;
        }
        if (!isset($items[$property_id])) {
            $items[$property_id] = array(
                'property_id' => $property_id,
                'property' => get_the_title($property_id),
                'items' => array(),
            );
        }
        $items[$property_id]['items'][] = array(
            'source' => sanitize_text_field((string) $source),
            'client' => sanitize_text_field((string) $client_name),
            'state' => sanitize_text_field((string) $state),
            'url' => esc_url_raw($url),
        );
    }

    private function sales_property_registration_conflict($property_id, $current_lead_id = 0, $current_deal_id = 0) {
        $property_id = absint($property_id);
        if (!$property_id) {
            return '';
        }
        foreach ($this->sales_registered_property_dataset((int) $current_lead_id, (int) $current_deal_id) as $item) {
            if ((int) ($item['property_id'] ?? 0) !== $property_id) {
                continue;
            }
            $details = array();
            foreach ((array) ($item['items'] ?? array()) as $registered) {
                $parts = array_filter(array($registered['source'] ?? '', $registered['client'] ?? '', $registered['state'] ?? ''));
                if ($parts) {
                    $details[] = implode(' / ', $parts);
                }
            }
            return $details ? implode('；', $details) : (string) ($item['property'] ?? get_the_title($property_id));
        }
        return '';
    }

    private function normalize_contact_phone($phone) {
        $digits = preg_replace('/\D+/', '', (string) $phone);
        return strlen($digits) >= 7 ? $digits : '';
    }

    private function agent_tasks($leads) {
        $tasks = array();

        foreach ($leads as $lead) {
            if (empty($lead['next_followup'])) {
                continue;
            }

            $tasks[] = $this->make_sales_task(
                $lead['next_followup'],
                '客户跟进',
                '跟进客户',
                $lead['client_name'] ?? '',
                !empty($lead['property_id']) ? get_the_title((int) $lead['property_id']) : '',
                add_query_arg('edit_lead', (int) $lead['id'], home_url('/agent/'))
            );
        }

        $tasks = array_values(array_filter($tasks));
        usort($tasks, function($a, $b) {
            return ((int) ($a['timestamp'] ?? PHP_INT_MAX)) <=> ((int) ($b['timestamp'] ?? PHP_INT_MAX));
        });

        return $tasks;
    }

    private function sales_rule_due_datetime($base_datetime, $offset_seconds) {
        $timestamp = strtotime((string) $base_datetime);
        if (!$timestamp) {
            $timestamp = current_time('timestamp');
        }
        $timestamp += (int) $offset_seconds;
        return date_i18n('Y-m-d H:i', $timestamp);
    }

    private function sales_task_text($lang = null) {
        $lang = $lang === null || $lang === '' ? $this->active_sales_language() : $lang;
        $lang = $lang === 'hu' ? 'hu' : 'zh';
        $texts = json_decode('{"zh":{"type_auto":"\u81ea\u52a8\u4efb\u52a1","type_viewing":"\u770b\u623f\u63d0\u9192","type_client":"\u5ba2\u6237\u8ddf\u8fdb","type_deal":"\u9500\u552e\u8ddf\u5355","type_payment":"\u4ed8\u6b3e\u63d0\u9192","type_commission":"\u4f63\u91d1\u4ed8\u6b3e","type_expected":"\u9884\u8ba1\u6210\u4ea4","type_customer":"\u6210\u4ea4\u5ba2\u6237\u8ddf\u8fdb","manager_assign":"\u4e3b\u7ba1\u9700\u6307\u6d3e\u8be2\u4ef7","assigned_to_deal":"\u5df2\u6307\u6d3e\u8be2\u4ef7\u9700\u751f\u6210\u8ddf\u5355","quote_feedback":"\u62a5\u4ef7\u53d1\u51fa3\u5929\u540e\u9700\u786e\u8ba4\u5ba2\u6237\u53cd\u9988","tomorrow_viewing":"\u660e\u5929\u6709\u9884\u7ea6\u770b\u623f\uff0c\u8bf7\u63d0\u524d\u786e\u8ba4","new_client_contact":"\u65b0\u5ba2\u6237\u9700\u9996\u6b21\u8054\u7cfb","set_next_followup":"\u8bf7\u8bbe\u7f6e\u4e0b\u6b21\u8ddf\u8fdb","set_next_step":"\u8bf7\u8bbe\u7f6e\u4e0b\u4e00\u6b65\u8ddf\u8fdb","after_viewing":"\u770b\u623f\u540e\u9700\u56de\u8bbf\u5ba2\u6237","price_update":"\u4ef7\u683c\u6c9f\u901a\u9700\u66f4\u65b0\u7ed3\u679c","reserved_contract":"\u9884\u8ba2\u540e\u9700\u63a8\u8fdb\u5408\u540c","contract_confirm":"\u5408\u540c\u4e2d\u9700\u786e\u8ba4\u7b7e\u7ea6/\u4ed8\u6b3e","inactive":"\u5ba2\u62377\u5929\u672a\u6d3b\u8dc3\uff0c\u8bf7\u5b89\u6392\u4e0b\u4e00\u6b21\u8054\u7cfb","follow_client":"\u8ddf\u8fdb\u5ba2\u6237\uff1a","no_client":"\u672a\u586b\u5199\u5ba2\u6237","follow_deal":"\u8ddf\u8fdb\u9500\u552e\u673a\u4f1a","payment_node":"\u4ed8\u6b3e\u8282\u70b9","unpaid":"\u672a\u6536\u6b3e\uff1a","broker_commission":"\u7ecf\u7eaa\u4eba\u4f63\u91d1\uff1a","amount_pending":"\u91d1\u989d\u5f85\u786e\u8ba4","expected_close":"\u9884\u8ba1\u6210\u4ea4/\u7b7e\u7ea6\u65e5\u671f","maintain_customer":"\u7ef4\u62a4\u6210\u4ea4\u5ba2\u6237","urgency_overdue":"\u5df2\u903e\u671f","urgency_today":"\u4eca\u5929","urgency_week":"\u672a\u67657\u5929","urgency_future":"\u8fdc\u671f","due_overdue":"\u903e\u671f ","due_today":"\u4eca\u5929\u5904\u7406","d