0e9s","unpaid":"H\u00e1tral\u00e9k: ","broker_commission":"K\u00f6zvet\u00edt\u0151i jutal\u00e9k: ","amount_pending":"\u00d6sszeg meger\u0151s\u00edt\u00e9sre v\u00e1r","expected_close":"V\u00e1rhat\u00f3 lez\u00e1r\u00e1si/szerz\u0151d\u00e9si d\u00e1tum","maintain_customer":"Lez\u00e1rt \u00fcgyf\u00e9l karbantart\u00e1sa","urgency_overdue":"Lej\u00e1rt","urgency_today":"Ma","urgency_week":"K\u00f6vetkez\u0151 7 nap","urgency_future":"T\u00e1volabbi","due_overdue":"Lej\u00e1rt ","due_today":"Ma kezelend\u0151","due_in":"H\u00e1tral\u00e9v\u0151 id\u0151: ","day":" nap","no_property":"Nincs lak\u00e1s megadva","open":"Megnyit\u00e1s"}}', true);
        return $texts[$lang] ?? $texts['zh'];
    }

    private function sales_automatic_rule_tasks() {
        $tasks = array();
        $task_text = $this->sales_task_text();
        $can_manage = $this->is_sales_manager_user();
        $current_user_id = get_current_user_id();
        $visible_deals = $this->visible_deals($this->get_deals());
        $visible_leads = $this->visible_leads($this->get_leads());

        foreach ($this->get_offer_inquiry_posts(160) as $inquiry_post) {
            $post_id = (int) $inquiry_post->ID;
            $assigned_sales_id = $this->offer_inquiry_assigned_sales_id($post_id);
            if (!$can_manage && $assigned_sales_id !== $current_user_id) {
                continue;
            }
            if ($this->find_deal_by_inquiry_id($post_id, $visible_deals)) {
                continue;
            }

            $data = $this->offer_inquiry_data($post_id);
            $created_at = get_post_field('post_date', $post_id);
            if (!$assigned_sales_id && $can_manage) {
                $tasks[] = $this->make_sales_task(
                    $this->sales_rule_due_datetime($created_at, 2 * HOUR_IN_SECONDS),
                    $task_text['type_auto'],
                    $task_text['manager_assign'],
                    $data['name'] ?? '',
                    $data['apartment'] ?? '',
                    $this->sales_portal_url(array('view' => 'inquiries'))
                );
            } elseif ($assigned_sales_id) {
                $tasks[] = $this->make_sales_task(
                    $this->sales_rule_due_datetime($created_at, DAY_IN_SECONDS),
                    $task_text['type_auto'],
                    $task_text['assigned_to_deal'],
                    $data['name'] ?? '',
                    $data['apartment'] ?? '',
                    $this->sales_portal_url(array('view' => 'deals', 'inquiry_id' => $post_id))
                );
            }

            if (($data['mail_status'] ?? '') === 'sent') {
                $tasks[] = $this->make_sales_task(
                    $this->sales_rule_due_datetime($created_at, 3 * DAY_IN_SECONDS),
                    $task_text['type_auto'],
                    $task_text['quote_feedback'],
                    $data['name'] ?? '',
                    $data['apartment'] ?? '',
                    $this->sales_portal_url(array('view' => 'inquiries'))
                );
            }

            if (!empty($data['date']) && (string) $data['date'] === date('Y-m-d', strtotime('+1 day', current_time('timestamp')))) {
                $tasks[] = $this->make_sales_task(
                    trim((string) $data['date'] . ' ' . ((string) ($data['time'] ?? '') ?: '09:00')),
                    $task_text['type_viewing'],
                    $task_text['tomorrow_viewing'],
                    $data['name'] ?? '',
                    $data['apartment'] ?? '',
                    $this->sales_portal_url(array('view' => 'inquiries'))
                );
            }
        }

        foreach ($visible_leads as $lead) {
            $lead_id = (int) ($lead['id'] ?? 0);
            if (!$lead_id || $this->find_deal_by_lead_id($lead_id, $visible_deals)) {
                continue;
            }
            $status = (string) ($lead['status'] ?? 'new');
            if (in_array($status, array('closed', 'lost'), true) || !empty($lead['next_followup'])) {
                continue;
            }
            $created_at = $lead['created_at'] ?? current_time('mysql');
            $updated_at = $lead['updated_at'] ?? $created_at;
            $tasks[] = $this->make_sales_task(
                $this->sales_rule_due_datetime($status === 'new' ? $created_at : $updated_at, DAY_IN_SECONDS),
                $task_text['type_auto'],
                $status === 'new' ? $task_text['new_client_contact'] : $task_text['set_next_followup'],
                $lead['client_name'] ?? '',
                !empty($lead['property_id']) ? get_the_title((int) $lead['property_id']) : '',
                $this->sales_portal_url(array('view' => 'clients', 'edit_lead' => $lead_id))
            );
        }

        foreach ($visible_deals as $deal) {
            $stage = $this->normalize_deal_stage_key($deal['stage'] ?? 'new');
            if (in_array($stage, array('closed', 'lost'), true) || !empty($deal['next_followup'])) {
                continue;
            }
            $property_title = !empty($deal['property_id']) ? get_the_title((int) $deal['property_id']) : '';
            $deal_url = $this->sales_portal_url(array('view' => 'deals', 'edit_deal' => (int) ($deal['id'] ?? 0)));
            $base_datetime = $deal['updated_at'] ?: ($deal['created_at'] ?? current_time('mysql'));
            $title = $task_text['set_next_step'];
            if ($stage === 'viewing') {
                $title = $task_text['after_viewing'];
            } elseif ($stage === 'negotiation') {
                $title = $task_text['price_update'];
            } elseif ($stage === 'reserved') {
                $title = $task_text['reserved_contract'];
            } elseif ($stage === 'contract') {
                $title = $task_text['contract_confirm'];
            }

            $tasks[] = $this->make_sales_task(
                $this->sales_rule_due_datetime($base_datetime, DAY_IN_SECONDS),
                $task_text['type_auto'],
                $title,
                $deal['client_name'] ?? '',
                $property_title,
                $deal_url
            );

            $inactive_base = $deal['last_contacted_at'] ?: ($deal['updated_at'] ?: ($deal['created_at'] ?? ''));
            if ($inactive_base && strtotime((string) $inactive_base) <= strtotime('-7 days', current_time('timestamp'))) {
                $tasks[] = $this->make_sales_task(
                    $this->sales_rule_due_datetime($inactive_base, 7 * DAY_IN_SECONDS),
                    $task_text['type_auto'],
                    $task_text['inactive'],
                    $deal['client_name'] ?? '',
                    $property_title,
                    $deal_url
                );
            }
        }

        return array_values(array_filter($tasks));
    }

    private function sales_tasks() {
        $tasks = array();
        $task_text = $this->sales_task_text();

        foreach ($this->visible_leads($this->get_leads()) as $lead) {
            if (!empty($lead['next_followup'])) {
                $tasks[] = $this->make_sales_task(
                    $lead['next_followup'],
                    $task_text['type_client'],
                    $task_text['follow_client'] . ($lead['client_name'] ?: $task_text['no_client']),
                    $lead['client_name'] ?? '',
                    !empty($lead['property_id']) ? get_the_title((int) $lead['property_id']) : '',
                    $this->sales_portal_url(array('view' => 'clients', 'edit_lead' => (int) $lead['id']))
                );
            }
        }

        foreach ($this->visible_deals($this->get_deals()) as $deal) {
            $property_title = !empty($deal['property_id']) ? get_the_title((int) $deal['property_id']) : '';
            $deal_url = $this->sales_portal_url(array('view' => 'deals', 'edit_deal' => (int) $deal['id']));
            $next_step_label = $this->sales_deal_next_step_label($deal['next_step'] ?? '');
            if (!empty($deal['next_followup'])) {
                $tasks[] = $this->make_sales_task(
                    $deal['next_followup'],
                    $task_text['type_deal'],
                    $next_step_label ?: $task_text['follow_deal'],
                    $deal['client_name'] ?? '',
                    $property_title,
                    $deal_url
                );
            }
            $payment_task_added = false;
            foreach ($this->payment_plan_display_items($deal) as $payment_item) {
                $due_date = (string) ($payment_item['due_date'] ?? '');
                $item_amount = (int) ($payment_item['amount'] ?? 0);
                $paid_amount = (int) ($payment_item['paid_amount'] ?? 0);
                $status = $this->infer_payment_plan_status($item_amount, $paid_amount, $due_date);
                $balance = max(0, $item_amount - $paid_amount);
                if (!$due_date || $balance <= 0 || $status === 'paid') {
                    continue;
                }
                $label = $this->payment_plan_label_display(trim((string) ($payment_item['label'] ?? '')));
                $tasks[] = $this->make_sales_task(
                    $due_date,
                    $task_text['type_payment'],
                    ($label ?: $task_text['payment_node']) . ': ' . $this->format_money($balance) . ' Ft',
                    $deal['client_name'] ?? '',
                    $property_title,
                    $deal_url
                );
                $payment_task_added = true;
            }
            if (!$payment_task_added && !empty($deal['payment_due_date']) && $this->deal_payment_balance($deal) > 0) {
                $tasks[] = $this->make_sales_task(
                    $deal['payment_due_date'],
                    $task_text['type_payment'],
                    $task_text['unpaid'] . $this->format_money($this->deal_payment_balance($deal)) . ' Ft',
                    $deal['client_name'] ?? '',
                    $property_title,
                    $deal_url
                );
            }
            if (($deal['source_type'] ?? '') === 'broker' && ($deal['stage'] ?? '') === 'closed' && !empty($deal['commission_due_date']) && ($deal['commission_status'] ?? '') !== 'paid') {
                $tasks[] = $this->make_sales_task(
                    $deal['commission_due_date'],
                    $task_text['type_commission'],
                    $task_text['broker_commission'] . ($this->deal_commission_amount($deal) ? $this->format_money($this->deal_commission_amount($deal)) . ' Ft' : $task_text['amount_pending']),
                    $deal['client_name'] ?? '',
                    $property_title,
                    $this->sales_portal_url(array('view' => 'commissions'))
                );
            }
            if (!empty($deal['expected_close']) && !in_array(($deal['stage'] ?? ''), array('closed', 'lost'), true)) {
                $tasks[] = $this->make_sales_task(
                    $deal['expected_close'],
                    $task_text['type_expected'],
                    $task_text['expected_close'],
                    $deal['client_name'] ?? '',
                    $property_title,
                    $deal_url
                );
            }
        }

        if ($this->is_sales_staff_user()) {
            foreach ($this->get_deals() as $deal) {
                if (($deal['stage'] ?? '') !== 'closed' || !$this->can_view_customer_profile($deal) || $this->can_view_deal($deal) || empty($deal['next_followup'])) {
                    continue;
                }
                $property_title = !empty($deal['property_id']) ? get_the_title((int) $deal['property_id']) : '';
                $next_step_label = $this->sales_deal_next_step_label($deal['next_step'] ?? '');
                $tasks[] = $this->make_sales_task(
                    $deal['next_followup'],
                    $task_text['type_customer'],
                    $next_step_label ?: $task_text['maintain_customer'],
                    $deal['client_name'] ?? '',
                    $property_title,
                    $this->sales_portal_url(array('view' => 'customers', 'customer_id' => (int) $deal['id']))
                );
            }
        }

        $tasks = array_merge($tasks, $this->sales_automatic_rule_tasks());

        $tasks = array_values(array_filter($tasks));
        usort($tasks, function($a, $b) {
            return ((int) ($a['timestamp'] ?? PHP_INT_MAX)) <=> ((int) ($b['timestamp'] ?? PHP_INT_MAX));
        });

        return $tasks;
    }

    private function make_sales_task($date, $type, $title, $client, $property, $url) {
        $task_text = $this->sales_task_text();
        $timestamp = strtotime((string) $date);
        if (!$timestamp) {
            return null;
        }

        $today = strtotime(current_time('Y-m-d'));
        $task_day = strtotime(date('Y-m-d', $timestamp));
        $days_left = (int) floor(($task_day - $today) / DAY_IN_SECONDS);
        if ($task_day < $today) {
            $urgency_key = 'overdue';
            $urgency = $task_text['urgency_overdue'];
            $due_text = $task_text['due_overdue'] . abs($days_left) . $task_text['day'];
        } elseif ($task_day === $today) {
            $urgency_key = 'today';
            $urgency = $task_text['urgency_today'];
            $due_text = $task_text['due_today'];
        } elseif ($days_left <= 7) {
            $urgency_key = 'upcoming';
            $urgency = $task_text['urgency_week'];
            $due_text = $task_text['due_in'] . $days_left . $task_text['day'];
        } else {
            $urgency_key = 'future';
            $urgency = $task_text['urgency_future'];
            $due_text = $task_text['due_in'] . $days_left . $task_text['day'];
        }

        return array(
            'date' => $this->format_task_datetime($date),
            'timestamp' => $timestamp,
            'type' => $type,
            'title' => $this->sales_display_value($title),
            'client' => $this->sales_display_value($client),
            'property' => $this->sales_display_value($property),
            'url' => $url,
            'urgency' => $urgency,
            'urgency_key' => $urgency_key,
            'days_left' => $days_left,
            'due_text' => $due_text,
        );
    }

    private function payment_deals() {
        return array_values(array_filter($this->get_deals(), function($deal) {
            return !empty($deal['amount']) || !empty($deal['deposit']) || !empty($deal['payment_received']) || !empty($deal['payment_due_date']) || !empty($deal['payment_status']);
        }));
    }

    private function sort_payment_deals($deals) {
        $deals = array_values($deals);
        $status_order = array(
            'overdue' => 10,
            'partial' => 20,
            'not_started' => 30,
            'paid' => 50,
        );
        usort($deals, function($a, $b) use ($status_order) {
            $a_status = $this->infer_payment_status($a['amount'] ?? '', $this->deal_payment_received_total($a), $a['payment_due_date'] ?? '', $a['payment_status'] ?? '');
            $b_status = $this->infer_payment_status($b['amount'] ?? '', $this->deal_payment_received_total($b), $b['payment_due_date'] ?? '', $b['payment_status'] ?? '');
            $a_order = $status_order[$a_status] ?? 40;
            $b_order = $status_order[$b_status] ?? 40;
            if ($a_order !== $b_order) {
                return $a_order <=> $b_order;
            }

            $a_due = !empty($a['payment_due_date']) ? strtotime((string) $a['payment_due_date']) : PHP_INT_MAX;
            $b_due = !empty($b['payment_due_date']) ? strtotime((string) $b['payment_due_date']) : PHP_INT_MAX;
            if ($a_due !== $b_due) {
                return $a_due <=> $b_due;
            }

            $a_updated = !empty($a['updated_at']) ? strtotime((string) $a['updated_at']) : 0;
            $b_updated = !empty($b['updated_at']) ? strtotime((string) $b['updated_at']) : 0;
            if ($a_updated !== $b_updated) {
                return $b_updated <=> $a_updated;
            }

            return ((int) ($b['id'] ?? 0)) <=> ((int) ($a['id'] ?? 0));
        });
        return $deals;
    }

    private function payment_plan_status_options() {
        return array(
            'pending' => 'Fizetésre vár',
            'partial' => 'Részben fizetve',
            'paid' => 'Kifizetve',
            'overdue' => 'Lejárt',
        );
    }

    private function auto_payment_plan_items($payment_method, $amount, $deposit = '', $payment_due_date = '', $expected_close = '', $payment_received = '', $lang = null) {
        $total = (int) preg_replace('/[^\d]/', '', (string) $amount);
        if ($total <= 0) {
            return array();
        }

        $label_text = $this->payment_plan_template_labels($lang);
        $deposit = min($total, (int) preg_replace('/[^\d]/', '', (string) $deposit));
        $payment_received_total = (int) preg_replace('/[^\d]/', '', (string) $payment_received);
        $remaining_paid = min($total, $deposit + $payment_received_total);
        $items = array();
        $project_year = 2026;
        $year_end_due_date = $project_year . '-12-31';
        $next_june_due_date = ($project_year + 1) . '-06-01';
        $percent_value = function($item_amount) use ($total) {
            $item_amount = (int) $item_amount;
            if ($total <= 0 || $item_amount <= 0) {
                return '';
            }
            return rtrim(rtrim(number_format(($item_amount / $total) * 100, 2, '.', ''), '0'), '.');
        };

        $add_item = function($label, $item_amount, $due_date = '', $percent = '') use (&$items, &$remaining_paid, $percent_value) {
            $item_amount = (int) $item_amount;
            if ($item_amount <= 0) {
                return;
            }
            if ($percent === '') {
                $percent = $percent_value($item_amount);
            }

            $paid_amount = min($item_amount, max(0, $remaining_paid));
            $remaining_paid -= $paid_amount;
            $items[] = array(
                'label' => $label,
                'percent' => (string) $percent,
                'amount' => (string) $item_amount,
                'due_date' => $due_date,
                'paid_amount' => $paid_amount ? (string) $paid_amount : '',
                'status' => $this->infer_payment_plan_status($item_amount, $paid_amount, $due_date),
                'note' => '',
            );
        };
        $add_template = function($rows) use ($total, $add_item) {
            $allocated = 0;
            $last_index = count($rows) - 1;
            foreach ($rows as $index => $row) {
                $percent = isset($row['percent']) ? (float) $row['percent'] : 0;
                if ($percent <= 0) {
                    continue;
                }
                $item_amount = ($index === $last_index) ? max(0, $total - $allocated) : (int) round($total * $percent / 100);
                $allocated += $item_amount;
                $add_item($row['label'], $item_amount, $row['due_date'] ?? '', (string) $row['percent']);
            }
        };

        if ($payment_method === 'full') {
            $add_template(array(
                array('label' => $label_text['advance_25'], 'percent' => '25', 'due_date' => $expected_close),
                array('label' => $label_text['final_75'], 'percent' => '75', 'due_date' => $year_end_due_date),
            ));
        } elseif ($payment_method === 'half_half') {
            $add_template(array(
                array('label' => $label_text['advance_25'], 'percent' => '25', 'due_date' => $expected_close),
                array('label' => $label_text['second_25_2026'], 'percent' => '25', 'due_date' => $year_end_due_date),
                array('label' => $label_text['final_50_2027'], 'percent' => '50', 'due_date' => $next_june_due_date),
            ));
        } elseif ($payment_method === 'installment') {
            $add_template(array(
                array('label' => $label_text['deposit_10'], 'percent' => '10', 'due_date' => $expected_close),
                array('label' => $label_text['advance_15'], 'percent' => '15', 'due_date' => $expected_close),
                array('label' => $label_text['second_25_structure'], 'percent' => '25', 'due_date' => ''),
                array('label' => $label_text['third_25_interior'], 'percent' => '25', 'due_date' => ''),
                array('label' => $label_text['fourth_20_notice'], 'percent' => '20', 'due_date' => ''),
                array('label' => $label_text['final_5_handover'], 'percent' => '5', 'due_date' => ''),
            ));
        } else {
            if ($deposit > 0) {
                $deposit_percent = $percent_value($deposit);
                $add_item($label_text['deposit'], $deposit, $expected_close, $deposit_percent);
            }
            $balance_percent = $deposit > 0 ? rtrim(rtrim(number_format(max(0, 100 - (float) $percent_value($deposit)), 2, '.', ''), '0'), '.') : '100';
            $add_item($label_text['balance'], $total - $deposit, $payment_due_date, $balance_percent);
        }

        return $this->sanitize_payment_plan_items($items);
    }

    private function payment_plan_schedule_text($items, $lang = null) {
        $lang = $lang === null || $lang === '' ? $this->active_sales_language() : $lang;
        $lang = $lang === 'hu' ? 'hu' : 'zh';
        $text = $lang === 'hu'
            ? array('paid' => json_decode('"befizetve: "'), 'due' => json_decode('"hat\u00e1rid\u0151: "'))
            : array('paid' => json_decode('"\u5df2\u4ed8\uff1a"'), 'due' => json_decode('"\u622a\u6b62\u65e5\uff1a"'));
        $fallback = $this->payment_plan_template_labels($lang)['default_node'];
        $lines = array();
        foreach ($items as $item) {
            $percent = !empty($item['percent']) ? ' (' . $item['percent'] . '%)' : '';
            $amount = !empty($item['amount']) ? $this->format_money($item['amount']) . ' Ft' : '-';
            $due = !empty($item['due_date']) ? $item['due_date'] : '-';
            $paid = !empty($item['paid_amount']) ? ', ' . $text['paid'] . $this->format_money($item['paid_amount']) . ' Ft' : '';
            $label = $this->payment_plan_label_display($item['label'] ?? '', $lang) ?: $fallback;
            $lines[] = trim($label . $percent . ': ' . $amount . ', ' . $text['due'] . $due . $paid);
        }
        return implode("\n", $lines);
    }

    private function sanitize_payment_plan_items($raw) {
        if (!is_array($raw)) {
            return array();
        }

        $statuses = $this->payment_plan_status_options();
        $items = array();
        foreach ($raw as $item) {
            if (!is_array($item)) {
                continue;
            }

            $label = isset($item['label']) ? sanitize_text_field($item['label']) : '';
            $percent = isset($item['percent']) ? sanitize_text_field(str_replace(',', '.', (string) $item['percent'])) : '';
            $percent = preg_replace('/[^0-9.]/', '', $percent);
            $amount = isset($item['amount']) ? preg_replace('/[^\d]/', '', (string) $item['amount']) : '';
            $due_date = isset($item['due_date']) ? sanitize_text_field($item['due_date']) : '';
            $paid_amount = isset($item['paid_amount']) ? preg_replace('/[^\d]/', '', (string) $item['paid_amount']) : '';
            $status = isset($item['status']) ? sanitize_key($item['status']) : '';
            $note = isset($item['note']) ? sanitize_text_field($item['note']) : '';

            if (substr_count($percent, '.') > 1 || ($percent !== '' && !preg_match('/^\d+(\.\d{1,4})?$/', $percent))) {
                $percent = '';
            }
            if ($label === '' && $percent === '' && $amount === '' && $due_date === '' && $paid_amount === '' && $note === '') {
                continue;
            }
            if ($due_date && !preg_match('/^\d{4}-\d{2}-\d{2}$/', $due_date)) {
                $due_date = '';
            }
            if (!$status || !isset($statuses[$status])) {
                $status = $this->infer_payment_plan_status($amount, $paid_amount, $due_date);
            }

            $items[] = array(
                'label' => $label,
                'percent' => $percent,
                'amount' => $amount,
                'due_date' => $due_date,
                'paid_amount' => $paid_amount,
                'status' => $status,
                'note' => $note,
            );

            if (count($items) >= 12) {
                break;
            }
        }

        return $items;
    }

    private function infer_payment_plan_status($amount, $paid_amount, $due_date = '') {
        $amount = (int) $amount;
        $paid_amount = (int) $paid_amount;
        if ($amount > 0 && $paid_amount >= $amount) {
            return 'paid';
        }
        if ($paid_amount > 0) {
            return 'partial';
        }
        if ($due_date && strtotime($due_date) < strtotime(current_time('Y-m-d'))) {
            return 'overdue';
        }
        return 'pending';
    }

    private function deal_payment_plan_items($deal) {
        $items = isset($deal['payment_plan_items']) && is_array($deal['payment_plan_items']) ? $deal['payment_plan_items'] : array();
        return $this->sanitize_payment_plan_items($items);
    }

    private function payment_plan_form_rows($deal, $min_rows = 6) {
        $rows = $this->deal_payment_plan_items($deal);
        if (!$rows && !empty($deal['payment_method']) && !empty($deal['amount'])) {
            $rows = $this->auto_payment_plan_items(
                $deal['payment_method'],
                $deal['amount'] ?? '',
                $deal['deposit'] ?? '',
                $deal['payment_due_date'] ?? '',
                $deal['expected_close'] ?? '',
                $deal['payment_received'] ?? '',
                $this->active_sales_language()
            );
        }
        if (!$rows) {
            $deposit = (string) ($deal['deposit'] ?? '');
            $amount = (string) ($deal['amount'] ?? '');
            $received = (string) ($deal['payment_received'] ?? '');
            $total_amount = (int) preg_replace('/[^\d]/', '', $amount);
            $percent_from_amount = function($value) use ($total_amount) {
                $value = (int) preg_replace('/[^\d]/', '', (string) $value);
                if ($total_amount <= 0 || $value <= 0) {
                    return '';
                }
                return rtrim(rtrim(number_format(($value / $total_amount) * 100, 2, '.', ''), '0'), '.');
            };
            if ($deposit !== '') {
                $rows[] = array(
                    'label' => $this->payment_plan_template_labels($this->active_sales_language())['deposit'],
                    'percent' => $percent_from_amount($deposit),
                    'amount' => $deposit,
                    'due_date' => $deal['expected_close'] ?? '',
                    'paid_amount' => ((int) $received >= (int) $deposit) ? $deposit : '',
                    'status' => ((int) $received >= (int) $deposit) ? 'paid' : 'pending',
                    'note' => '',
                );
            }
            if ($amount !== '') {
                $balance = max(0, (int) $amount - (int) $deposit);
                $rows[] = array(
                    'label' => $this->payment_plan_template_labels($this->active_sales_language())['balance'],
                    'percent' => $percent_from_amount($balance),
                    'amount' => $balance ? (string) $balance : '',
                    'due_date' => $deal['payment_due_date'] ?? '',
                    'paid_amount' => '',
                    'status' => $this->infer_payment_plan_status($balance, 0, $deal['payment_due_date'] ?? ''),
                    'note' => '',
                );
            }
        }

        while (count($rows) < $min_rows) {
            $rows[] = array(
                'label' => '',
                'percent' => '',
                'amount' => '',
                'due_date' => '',
                'paid_amount' => '',
                'status' => '',
                'note' => '',
            );
        }

        return $rows;
    }

    private function payment_plan_display_items($deal) {
        $items = $this->deal_payment_plan_items($deal);
        if ($items) {
            return $items;
        }
        return array_values(array_filter($this->payment_plan_form_rows($deal, 0), function($item) {
            return !empty($item['label']) || !empty($item['amount']) || !empty($item['due_date']) || !empty($item['paid_amount']);
        }));
    }

