    private function broker_phone($user_id) {
        return (string) get_user_meta((int) $user_id, '_harmat_broker_phone', true);
    }

    private function broker_commission_rate($user_id) {
        return (string) get_user_meta((int) $user_id, '_harmat_broker_commission_rate', true);
    }

    private function sanitize_commission_rate($rate) {
        $rate = trim(str_replace(',', '.', (string) $rate));
        if ($rate === '') {
            return '';
        }
        if (!preg_match('/^\d+(\.\d{1,4})?$/', $rate)) {
            return '';
        }
        return rtrim(rtrim($rate, '0'), '.');
    }

    private function is_sales_user($user_id) {
        $user = $user_id ? get_userdata((int) $user_id) : null;
        return $user && array_intersect(array(self::ROLE_MANAGER, self::ROLE_SALES, self::ROLE_BROKER), (array) $user->roles);
    }

    private function is_internal_sales_user($user_id) {
        $user = $user_id ? get_userdata((int) $user_id) : null;
        return $user && array_intersect(array(self::ROLE_MANAGER, self::ROLE_SALES), (array) $user->roles);
    }

    private function is_broker_user($user_id) {
        $user = $user_id ? get_userdata((int) $user_id) : null;
        return $user && in_array(self::ROLE_BROKER, (array) $user->roles, true);
    }

    private function assigned_sales_label($user_id) {
        $user = $user_id ? get_userdata((int) $user_id) : null;
        if (!$user) {
            return '未指派';
        }

        return $user->display_name ?: $user->user_login;
    }

    private function render_assigned_sales_select($name, $selected = 0, $include_empty = true, $empty_label = '') {
        $empty_label = $empty_label !== '' ? $empty_label : json_decode('"\u672a\u6307\u6d3e"');
        echo '<select name="' . esc_attr($name) . '">';
        if ($include_empty) {
            echo '<option value="0"' . selected((int) $selected, 0, false) . '>' . esc_html($empty_label) . '</option>';
        }
        foreach ($this->get_internal_sales_users() as $sales_user) {
            echo '<option value="' . esc_attr($sales_user->ID) . '"' . selected((int) $selected, (int) $sales_user->ID, false) . '>' . esc_html(($sales_user->display_name ?: $sales_user->user_login) . ' (' . $sales_user->user_login . ')') . '</option>';
        }
        echo '</select>';
    }

    private function offer_inquiry_assigned_sales_id($post_id) {
        return (int) get_post_meta((int) $post_id, '_harmat_assigned_sales_id', true);
    }

    private function can_use_assigned_inquiry($post_id) {
        $post_id = absint($post_id);
        if (!$post_id || get_post_type($post_id) !== 'harmat_offer_lead') {
            return false;
        }
        if ($this->is_sales_manager_user()) {
            return true;
        }

        return $this->offer_inquiry_assigned_sales_id($post_id) === get_current_user_id();
    }

    private function property_id_by_title($title) {
        $title = trim((string) $title);
        if ($title === '') {
            return 0;
        }

        foreach ($this->get_properties() as $property) {
            if (strcasecmp(get_the_title($property), $title) === 0) {
                return (int) $property->ID;
            }
        }

        return 0;
    }

    private function get_properties($search = '') {
        $args = array(
            'post_type' => 'property',
            'post_status' => 'publish',
            'posts_per_page' => -1,
            'orderby' => 'title',
            'order' => 'ASC',
        );

        if ($search) {
            $args['s'] = $search;
        }

        return get_posts($args);
    }

    private function sales_status($post_id) {
        $status = get_post_meta($post_id, 'property_status', true);
        $under_offer = get_post_meta($post_id, 'property_under_offer', true);
        if ($status === 'sold') {
            return 'sold';
        }
        if ($under_offer) {
            return 'reserved';
        }
        return 'current';
    }

    private function status_options($lang = null) {
        if ($lang === 'zh') {
            return array(
                'current' => json_decode('"\u5728\u552e"'),
                'reserved' => json_decode('"\u5df2\u9884\u8ba2"'),
                'sold' => json_decode('"\u5df2\u51fa\u552e"'),
            );
        }
        if ($lang === 'hu') {
            return array(
                'current' => json_decode('"El\u00e9rhet\u0151"'),
                'reserved' => json_decode('"Foglalva"'),
                'sold' => json_decode('"Eladva"'),
            );
        }
        return array(
