    private function account_return_url($args = array()) {
        $return_to = isset($_POST['return_to']) ? sanitize_key(wp_unslash($_POST['return_to'])) : '';
        if ($return_to === 'sales_brokers') {
            return $this->sales_portal_url(array_merge(array('view' => 'brokers'), $args));
        }
        if ($return_to === 'sales_broker_detail') {
            $user_id = isset($_POST['user_id']) ? absint($_POST['user_id']) : 0;
            return $this->sales_portal_url(array_merge(array('view' => 'brokers', 'broker_id' => $user_id), $args));
        }

        return $this->page_url(array_merge(array('tab' => 'accounts'), $args));
    }

    private function property_return_url($args = array()) {
        $return_to = isset($_POST['return_to']) ? sanitize_key(wp_unslash($_POST['return_to'])) : '';
        if ($return_to === 'sales_properties') {
            return $this->sales_portal_url(array_merge(array('view' => 'properties'), $args));
        }

        return $this->page_url($args);
    }

    private function deal_return_url($args = array()) {
        $return_to = isset($_POST['return_to']) ? sanitize_key(wp_unslash($_POST['return_to'])) : '';
        if ($return_to === 'sales_deals') {
            return $this->sales_portal_url(array_merge(array('view' => 'deals'), $args));
        }

        return $this->sales_portal_url(array_merge(array('view' => 'deals'), $args));
    }

    private function lead_return_url($args = array()) {
        $return_to = isset($_POST['return_to']) ? sanitize_key(wp_unslash($_POST['return_to'])) : '';
        if ($return_to === 'sales_clients') {
            return $this->sales_portal_url(array_merge(array('view' => 'clients'), $args));
        }
        if ($return_to === 'sales_inquiries') {
            return $this->sales_portal_url(array_merge(array('view' => 'inquiries'), $args));
        }
        if ($return_to === 'agent_clients') {
            return add_query_arg(array_merge(array('view' => 'clients'), $args), home_url('/agent/'));
        }
        if ($return_to === 'agent') {
            return add_query_arg($args, home_url('/agent/'));
        }

        return $this->page_url(array_merge(array('tab' => 'leads'), $args));
    }

    private function sales_portal_script() {
        return <<<'JS'
        (function(){
            var salesLang = document.body && document.body.getAttribute("data-sales-lang") === "hu" ? "hu" : "zh";
            var salesCopy = salesLang === "hu" ? {
                duplicateIntro: "M\u00e1r van kapcsol\u00f3d\u00f3 rekord. Biztosan l\u00e9trehozza vagy menti az \u00e9rt\u00e9kes\u00edt\u00e9si \u00fcgyet?",
                duplicateTail: "Ha ezek a rekordok nem ennek az \u00fcgynek a forr\u00e1sai, meger\u0151s\u00edt\u00e9s ut\u00e1n menthet\u0151.",
                noClient: "Nincs \u00fcgyf\u00e9l megadva",
                registered: "M\u00e1r r\u00f6gz\u00edtve",
                propertyLocked: "Ez a lak\u00e1s m\u00e1r r\u00f6gz\u00edtve vagy z\u00e1rolva van:",
                propertyConfirm: "K\u00e9rj\u00fck, egyeztessen a vezet\u0151vel. Biztosan ezt a lak\u00e1st v\u00e1lasztja?",
                planWaiting: "Kit\u00f6lt\u00e9sre v\u00e1r",
                planNeedAmount: "El\u0151bb adja meg a v\u00e9tel\u00e1rat",
                planNeedRows: "Adja meg a fizet\u00e9si \u00fctemeket",
                planBalanced: "\u00d6sszeg egyezik",
                planMissing: "Hi\u00e1nyzik ",
                planExtra: "T\u00f6bblet ",
                paymentTemplates: {
                    full: [
                        { label: "El\u0151leg 25%", percent: "25", due: "expected" },
                        { label: "V\u00e9gs\u0151 r\u00e9szlet 75% - 2026.12.31-ig", percent: "75", due: "yearEnd" }
                    ],
                    half_half: [
                        { label: "El\u0151leg 25%", percent: "25", due: "expected" },
                        { label: "M\u00e1sodik r\u00e9szlet 25% - 2026.12.31-ig", percent: "25", due: "yearEnd" },
                        { label: "V\u00e9gs\u0151 r\u00e9szlet 50% - 2027.06.01-ig", percent: "50", due: "nextJune" }
                    ],
                    installment: [
                        { label: "Foglal\u00f3 10%", percent: "10", due: "expected" },
                        { label: "El\u0151leg 15% - a foglal\u00f3val egy\u00fctt az els\u0151 fizet\u00e9s", percent: "15", due: "expected" },
                        { label: "M\u00e1sodik r\u00e9szlet 25% - szerkezetk\u00e9sz \u00e1llapot ut\u00e1n", percent: "25" },
                        { label: "Harmadik r\u00e9szlet 25% - bels\u0151\u00e9p\u00edt\u00e9szeti munk\u00e1k kezdetekor", percent: "25" },
                        { label: "Negyedik r\u00e9szlet 20% - a lak\u00e1s elk\u00e9sz\u00fclt\u00e9r\u0151l sz\u00f3l\u00f3 \u00e9rtes\u00edt\u00e9s ut\u00e1n", percent: "20" },
                        { label: "V\u00e9gs\u0151 r\u00e9szlet 5% - kulcs\u00e1tad\u00e1skor", percent: "5" }
                    ],
                    deposit: "Foglal\u00f3",
                    balance: "H\u00e1tral\u00e9k"
                }
            } : {
                duplicateIntro: "\u5df2\u6709\u76f8\u5173\u8bb0\u5f55\uff0c\u8bf7\u786e\u8ba4\u662f\u5426\u4ecd\u9700\u65b0\u5efa\u6216\u4fdd\u5b58\u9500\u552e\u8ddf\u5355\uff1a",
                duplicateTail: "\u5982\u679c\u8fd9\u4e9b\u8bb0\u5f55\u4e0d\u662f\u5f53\u524d\u9500\u552e\u8ddf\u5355\u7684\u6765\u6e90\uff0c\u8bf7\u786e\u8ba4\u540e\u518d\u4fdd\u5b58\u3002",
                noClient: "\u672a\u586b\u5199\u5ba2\u6237",
                registered: "\u5df2\u767b\u8bb0",
                propertyLocked: "\u8fd9\u5957\u623f\u6e90\u5df2\u7ecf\u88ab\u767b\u8bb0\u6216\u9501\u5b9a\uff1a",
                propertyConfirm: "\u8bf7\u5148\u8054\u7cfb\u4e3b\u7ba1\u786e\u8ba4\uff0c\u662f\u5426\u4ecd\u7136\u9009\u62e9\u8fd9\u5957\u623f\uff1f",
                planWaiting: "\u5f85\u586b\u5199",
                planNeedAmount: "\u8bf7\u5148\u586b\u5199\u6210\u4ea4\u91d1\u989d",
                planNeedRows: "\u8bf7\u586b\u5199\u4ed8\u6b3e\u8282\u70b9",
                planBalanced: "\u91d1\u989d\u4e00\u81f4",
                planMissing: "\u5dee\u989d ",
                planExtra: "\u8d85\u51fa ",
                paymentTemplates: {
                    full: [
                        { label: "\u9996\u4ed8\u6b3e 25%", percent: "25", due: "expected" },
                        { label: "\u5c3e\u6b3e 75% - 2026.12.31\u524d", percent: "75", due: "yearEnd" }
                    ],
                    half_half: [
                        { label: "\u9996\u4ed8\u6b3e 25%", percent: "25", due: "expected" },
                        { label: "\u7b2c\u4e8c\u7b14 25% - 2026.12.31\u524d", percent: "25", due: "yearEnd" },
                        { label: "\u5c3e\u6b3e 50% - 2027.06.01\u524d", percent: "50", due: "nextJune" }
                    ],
                    installment: [
                        { label: "\u5b9a\u91d1 10%", percent: "10", due: "expected" },
                        { label: "\u9996\u4ed8\u6b3e 15% - \u4e0e\u5b9a\u91d1\u540c\u6b21\u652f\u4ed8", percent: "15", due: "expected" },
                        { label: "\u7b2c\u4e8c\u671f 25% - \u7ed3\u6784\u5b8c\u6210\u540e", percent: "25" },
                        { label: "\u7b2c\u4e09\u671f 25% - \u5ba4\u5185\u5de5\u7a0b\u5f00\u59cb\u65f6", percent: "25" },
                        { label: "\u7b2c\u56db\u671f 20% - \u623f\u5c4b\u5b8c\u5de5\u901a\u77e5\u540e", percent: "20" },
                        { label: "\u5c3e\u6b3e 5% - \u4ea4\u94a5\u5319\u65f6", percent: "5" }
                    ],
                    deposit: "\u5b9a\u91d1",
                    balance: "\u5c3e\u6b3e"
                }
            };

            function toNumber(value) {
                var number = parseInt(String(value || "").replace(/[^\d]/g, ""), 10);
                return isNaN(number) ? 0 : number;
            }

            function money(value) {
                if (!value) {
                    return "0";
                }
                try {
                    return new Intl.NumberFormat("hu-HU").format(value);
                } catch (error) {
                    return String(value).replace(/\B(?=(\d{3})+(?!\d))/g, " ");
                }
            }

            function setGroupVisible(group, visible) {
                group.hidden = !visible;
                group.style.display = visible ? "grid" : "none";
                group.setAttribute("aria-hidden", visible ? "false" : "true");
                Array.prototype.forEach.call(group.querySelectorAll("input,select,textarea,button"), function(control) {
                    control.disabled = !visible;
                });
            }

            function syncPaymentPlan(form, eventTarget) {
                var amountInput = form.querySelector("[data-harmat-deal-amount]");
                var methodInput = form.querySelector("[data-harmat-payment-method]");
                var depositInput = form.querySelector("[data-harmat-deal-deposit]");
                var receivedInput = form.querySelector("[data-harmat-payment-received]");
                var dueDateInput = form.querySelector("[data-harmat-payment-due-date]");
                var expectedCloseInput = form.querySelector("[data-harmat-expected-close]");
                var total = toNumber(amountInput ? amountInput.value : "");
                var deposit = Math.min(total, toNumber(depositInput ? depositInput.value : ""));
                var received = toNumber(receivedInput ? receivedInput.value : "");
                var finalDueDate = dueDateInput ? dueDateInput.value : "";
                var expectedCloseDate = expectedCloseInput ? expectedCloseInput.value : "";
                var method = methodInput ? methodInput.value : "";
                var yearEndDueDate = "2026-12-31";
                var nextJuneDueDate = "2027-06-01";
                var labels = Array.prototype.slice.call(form.querySelectorAll("[data-harmat-plan-label]"));
                var percents = Array.prototype.slice.call(form.querySelectorAll("[data-harmat-plan-percent]"));
                var amounts = Array.prototype.slice.call(form.querySelectorAll("[data-harmat-plan-amount]"));
                var dueDates = Array.prototype.slice.call(form.querySelectorAll("[data-harmat-plan-due]"));
                var paidInputs = Array.prototype.slice.call(form.querySelectorAll("[data-harmat-plan-paid]"));
                var statusInputs = Array.prototype.slice.call(form.querySelectorAll("[data-harmat-plan-status]"));
                var note = form.querySelector("[data-harmat-payment-percent-note]");
                var summary = form.querySelector("[data-harmat-payment-summary]");
                var autoRows = {};
                var changedPercent = eventTarget && eventTarget.matches && eventTarget.matches("[data-harmat-plan-percent]");
                var changedAmount = eventTarget && eventTarget.matches && eventTarget.matches("[data-harmat-plan-amount]");
                var changedTotal = eventTarget && eventTarget.matches && eventTarget.matches("[data-harmat-deal-amount]");
                var changedMethod = eventTarget && eventTarget.matches && eventTarget.matches("[data-harmat-payment-method]");
                var changedDeposit = eventTarget && eventTarget.matches && eventTarget.matches("[data-harmat-deal-deposit]");
                var changedPlanRow = eventTarget && eventTarget.matches && eventTarget.matches("[data-harmat-plan-label],[data-harmat-plan-percent],[data-harmat-plan-amount],[data-harmat-plan-due],[data-harmat-plan-paid],[data-harmat-plan-status]");

                function planIsEmpty() {
                    return labels.every(function(input) {
                        return !input.value;
                    }) && amounts.every(function(input) {
                        return !toNumber(input.value);
                    }) && percents.every(function(input) {
                        return !toDecimal(input.value);
                    });
                }

                function toDecimal(value) {
                    var text = String(value || "").replace(",", ".").replace(/[^0-9.]/g, "");
                    var firstDot = text.indexOf(".");
                    if (firstDot !== -1) {
                        text = text.slice(0, firstDot + 1) + text.slice(firstDot + 1).replace(/\./g, "");
                    }
                    var number = parseFloat(text);
                    return isNaN(number) ? 0 : number;
                }

                function formatPercent(value) {
                    if (!isFinite(value) || value <= 0) {
                        return "";
                    }
                    var rounded = Math.round(value * 100) / 100;
                    return String(rounded).replace(/\.0+$/, "").replace(/(\.\d*[1-9])0+$/, "$1");
                }

                function percentFromAmount(rowAmount) {
                    return total > 0 && rowAmount > 0 ? rowAmount / total * 100 : 0;
                }

                function amountFromPercent(percent) {
                    return total > 0 && percent > 0 ? Math.round(total * percent / 100) : 0;
                }

                function setSummaryValue(selector, value) {
                    if (!summary) {
                        return;
                    }
                    var node = summary.querySelector(selector);
                    if (node) {
                        node.textContent = value;
                    }
                }

                function updatePaymentSummary(planTotal, planPercentTotal) {
                    if (!summary) {
                        return;
                    }
                    var receivedBalance = Math.max(0, total - received);
                    var delta = total - planTotal;
                    var hasPlan = planTotal > 0 || planPercentTotal > 0;
                    var isBalanced = total > 0 && hasPlan && Math.abs(delta) <= 1;
                    var isWarning = total > 0 && hasPlan && Math.abs(delta) > 1;
                    var statusText = salesCopy.planWaiting;

                    if (total <= 0) {
                        statusText = salesCopy.planNeedAmount;
                    } else if (!hasPlan) {
                        statusText = salesCopy.planNeedRows;
                    } else if (isBalanced) {
                        statusText = salesCopy.planBalanced;
                    } else if (delta > 0) {
                        statusText = salesCopy.planMissing + money(delta) + " HUF";
                    } else {
                        statusText = salesCopy.planExtra + money(Math.abs(delta)) + " HUF";
                    }

                    setSummaryValue("[data-harmat-summary-total]", total > 0 ? money(total) + " HUF" : "-");
                    setSummaryValue("[data-harmat-summary-plan]", planTotal > 0 ? money(planTotal) + " HUF" : "-");
                    setSummaryValue("[data-harmat-summary-percent]", planPercentTotal > 0 ? formatPercent(planPercentTotal) + "%" : "-");
                    setSummaryValue("[data-harmat-summary-balance]", money(received) + " / " + money(receivedBalance) + " HUF");
                    setSummaryValue("[data-harmat-summary-status]", statusText);
                    summary.classList.toggle("is-balanced", isBalanced);
                    summary.classList.toggle("is-warning", isWarning);
                }

                function todayIso() {
                    var date = new Date();
                    date.setHours(0, 0, 0, 0);
                    var month = String(date.getMonth() + 1).padStart(2, "0");
                    var day = String(date.getDate()).padStart(2, "0");
                    return date.getFullYear() + "-" + month + "-" + day;
                }

                function inferRowStatus(rowAmount, paidAmount, dueDate) {
                    if (rowAmount > 0 && paidAmount >= rowAmount) {
                        return "paid";
                    }
                    if (paidAmount > 0) {
                        return "partial";
                    }
                    if (dueDate && dueDate < todayIso()) {
                        return "overdue";
                    }
                    return rowAmount > 0 ? "pending" : "";
                }

                function setRow(index, label, amount, dueDate, percent) {
                    if (labels[index]) {
                        labels[index].value = label;
                    }
                    if (percents[index]) {
                        percents[index].value = percent !== undefined && percent !== "" ? formatPercent(percent) : formatPercent(percentFromAmount(amount));
                    }
                    if (amounts[index]) {
                        amounts[index].value = amount ? String(amount) : "";
                    }
                    if (dueDates[index]) {
                        dueDates[index].value = dueDate || "";
                    }
                    autoRows[index] = true;
                }

                function clearRow(index) {
                    setRow(index, "", "", "", "");
                    if (paidInputs[index]) {
                        paidInputs[index].value = "";
                    }
                    if (statusInputs[index]) {
                        statusInputs[index].value = "";
                    }
                }

                function distributeReceivedToAutoRows() {
                    var remaining = received;
                    amounts.forEach(function(input, index) {
                        if (!autoRows[index]) {
                            return;
                        }
                        var rowAmount = toNumber(input.value);
                        var rowPaid = rowAmount > 0 ? Math.min(rowAmount, Math.max(0, remaining)) : 0;
                        remaining -= rowPaid;
                        if (paidInputs[index]) {
                            paidInputs[index].value = rowPaid > 0 ? String(rowPaid) : "";
                        }
                        if (statusInputs[index]) {
                            statusInputs[index].value = inferRowStatus(rowAmount, rowPaid, dueDates[index] ? dueDates[index].value : "");
                        }
                    });
                }

                function applyTemplate(rows) {
                    var allocated = 0;
                    rows.forEach(function(row, index) {
                        var percent = toDecimal(row.percent);
                        var rowAmount = index === rows.length - 1 ? Math.max(0, total - allocated) : amountFromPercent(percent);
                        allocated += rowAmount;
                        setRow(index, row.label, rowAmount, row.dueDate || "", percent);
                    });
                    for (var clearIndex = rows.length; clearIndex < amounts.length; clearIndex++) {
                        clearRow(clearIndex);
                    }
                }

                function paymentTemplate(selectedMethod) {
                    return (salesCopy.paymentTemplates[selectedMethod] || []).map(function(row) {
                        return {
                            label: row.label,
                            percent: row.percent,
                            dueDate: row.due === "yearEnd" ? yearEndDueDate : (row.due === "nextJune" ? nextJuneDueDate : (row.due === "expected" ? expectedCloseDate : ""))
                        };
                    });
                }

                if (total > 0 && (changedMethod || planIsEmpty())) {
                    var template = paymentTemplate(method);
                    if (template.length) {
                        applyTemplate(template);
                    } else if (deposit > 0 && planIsEmpty()) {
                        var depositPercent = percentFromAmount(deposit);
                        setRow(0, salesCopy.paymentTemplates.deposit, deposit, expectedCloseDate, depositPercent);
                        setRow(1, salesCopy.paymentTemplates.balance, total - deposit, finalDueDate, Math.max(0, 100 - depositPercent));
                    }
                }

                var hasPercentValue = percents.some(function(input) {
                    return toDecimal(input.value) > 0;
                });
                var usePercentForAmount = total > 0 && !changedAmount && (changedPercent || (changedTotal && hasPercentValue));
                if (usePercentForAmount) {
                    percents.forEach(function(input, index) {
                        if (!amounts[index]) {
                            return;
                        }
                        var percent = toDecimal(input.value);
                        var rowAmount = amountFromPercent(percent);
                        amounts[index].value = rowAmount > 0 ? String(rowAmount) : "";
                    });
                } else {
                    amounts.forEach(function(input, index) {
                        if (!percents[index]) {
                            return;
                        }
                        var rowAmount = toNumber(input.value);
                        percents[index].value = formatPercent(percentFromAmount(rowAmount));
                    });
                }

                distributeReceivedToAutoRows();

                var planTotal = 0;
                var planPercentTotal = 0;
                amounts.forEach(function(input) {
                    var rowAmount = toNumber(input.value);
                    planTotal += rowAmount;
                });
                percents.forEach(function(input) {
                    planPercentTotal += toDecimal(input.value);
                });
                amounts.forEach(function(input) {
                    var rowAmount = toNumber(input.value);
                    var cell = input.closest("td");
                    if (!cell) {
                        return;
                    }
                    var hint = cell.querySelector(".harmat-sales-plan-percent");
                    if (!hint) {
                        hint = document.createElement("small");
                        hint.className = "harmat-sales-plan-percent";
                        cell.appendChild(hint);
                    }
                    hint.textContent = total > 0 && rowAmount > 0 ? (rowAmount / total * 100).toFixed(1).replace(".0", "") + "%" : "";
                });

                updatePaymentSummary(planTotal, planPercentTotal);

                if (note) {
                    if (total > 0) {
                        var percentText = planTotal > 0 ? (planTotal / total * 100).toFixed(1).replace(".0", "") + "%" : "0%";
                        var balance = Math.max(0, total - received);
                        var percentMessage = planPercentTotal > 0 ? "; ütemezési arány összesen " + formatPercent(planPercentTotal) + "%" : "";
                        var message = "Vételár " + money(total) + " HUF; fizetési terv összesen " + money(planTotal) + " HUF, arány " + percentText + percentMessage + "; befizetve " + money(received) + " HUF; hátralék " + money(balance) + " HUF.";
                        if (planTotal > 0 && planTotal !== total) {
                            message += " Kérjük, ellenőrizze, hogy a fizetési terv összege megegyezik-e a vételárral.";
                        }
                        if (method === "installment" && deposit <= 0 && planTotal === total) {
                            message += " Részletfizetés esetén az egyes ütemek manuálisan tovább bonthatók.";
                        }
                        note.textContent = message;
                    } else {
                        note.textContent = "";
                    }
                }
            }

            function syncDealPriceBreakdown(form, eventTarget) {
                var propertySelect = form.querySelector("[data-harmat-deal-property]");
                var parkingSelect = form.querySelector("[data-harmat-deal-parking]");
                var storageSelect = form.querySelector("[data-harmat-deal-storage]");
                var amountInput = form.querySelector("[data-harmat-deal-amount]");
                var summary = form.querySelector("[data-harmat-price-breakdown]");

                function selected(select) {
                    return select && select.selectedIndex >= 0 ? select.options[select.selectedIndex] : null;
                }

                function optionAmount(option, attr) {
                    return toNumber(option ? option.getAttribute(attr) : "");
                }

                function setSummary(selector, value) {
                    if (!summary) {
                        return;
                    }
                    var node = summary.querySelector(selector);
                    if (node) {
                        node.textContent = value > 0 ? money(value) + " HUF" : "-";
                    }
                }

                var propertyAmount = optionAmount(selected(propertySelect), "data-price");
                var parkingAmount = optionAmount(selected(parkingSelect), "data-gross");
                var storageAmount = optionAmount(selected(storageSelect), "data-gross");
                var total = propertyAmount + parkingAmount + storageAmount;

                setSummary("[data-harmat-price-property]", propertyAmount);
                setSummary("[data-harmat-price-parking]", parkingAmount);
                setSummary("[data-harmat-price-storage]", storageAmount);
                setSummary("[data-harmat-price-total]", total);

                if (amountInput && total > 0 && !(eventTarget && eventTarget.matches && eventTarget.matches("[data-harmat-deal-amount]"))) {
                    amountInput.value = String(total);
                }
            }

            function syncDealForm(form, eventTarget) {
                var sourceInput = form.querySelector("[data-harmat-deal-source]");
                var source = sourceInput ? sourceInput.value : "";
                var brokerVisible = source === "broker";
                var websiteVisible = source === "website";

                Array.prototype.forEach.call(form.querySelectorAll(".harmat-sales-source-broker"), function(group) {
                    setGroupVisible(group, brokerVisible);
                });
                Array.prototype.forEach.call(form.querySelectorAll(".harmat-sales-source-website"), function(group) {
                    setGroupVisible(group, websiteVisible);
                });

                var brokerSelect = form.querySelector("select[name='deal_broker_id']");
                var rateInput = form.querySelector("[data-harmat-commission-rate]");
                var commissionInput = form.querySelector("[data-harmat-commission-amount]");
                var amountInput = form.querySelector("[data-harmat-deal-amount]");
                var rate = "";

                syncDealPriceBreakdown(form, eventTarget);

                if (brokerVisible && brokerSelect && brokerSelect.selectedIndex >= 0) {
                    rate = brokerSelect.options[brokerSelect.selectedIndex].getAttribute("data-commission-rate") || "";
                }
                if (rateInput) {
                    rateInput.value = brokerVisible ? rate : "";
                }
                if (commissionInput) {
                    var parsedRate = parseFloat(String(rate).replace(",", "."));
                    var dealAmount = toNumber(amountInput ? amountInput.value : "");
                    commissionInput.value = brokerVisible && parsedRate > 0 && dealAmount > 0 ? String(Math.round(dealAmount * parsedRate / 100)) : "";
                }

                var stageInput = form.querySelector("select[name='deal_stage']");
                var followupRequired = !stageInput || ["closed", "lost"].indexOf(stageInput.value) === -1;
                Array.prototype.forEach.call(form.querySelectorAll("[data-harmat-next-followup],[data-harmat-next-step]"), function(control) {
                    control.required = followupRequired;
                });

                syncPaymentPlan(form, eventTarget);
            }

            var paymentWatchSelector = "[data-harmat-deal-property],[data-harmat-deal-parking],[data-harmat-deal-storage],[data-harmat-deal-amount],[data-harmat-deal-deposit],[data-harmat-payment-received],[data-harmat-payment-due-date],[data-harmat-expected-close],[data-harmat-plan-percent],[data-harmat-plan-amount],[data-harmat-plan-paid],[data-harmat-plan-due]";

            function normalizePhone(value) {
                var digits = String(value || "").replace(/\D+/g, "");
                return digits.length >= 7 ? digits : "";
            }

            function duplicateContactsForForm(form) {
                try {
                    return JSON.parse(form.getAttribute("data-harmat-duplicate-contacts") || "[]") || [];
                } catch (error) {
                    return [];
                }
            }

            function duplicateMatchesForForm(form) {
                var emailInput = form.querySelector("input[name='deal_email']");
                var phoneInput = form.querySelector("input[name='deal_phone']");
                var leadInput = form.querySelector("input[name='deal_lead_id']");
                var inquiryInput = form.querySelector("[name='deal_inquiry_id']");
                var email = String(emailInput ? emailInput.value : "").trim().toLowerCase();
                var phone = normalizePhone(phoneInput ? phoneInput.value : "");
                var currentLeadId = String(leadInput ? leadInput.value : "0");
                var currentInquiryId = String(inquiryInput ? inquiryInput.value : "0");
                if (!email && !phone) {
                    return [];
                }
                return duplicateContactsForForm(form).filter(function(item) {
                    if (currentLeadId !== "0" && String(item.kind || "") === "lead" && String(item.id || "") === currentLeadId) {
                        return false;
                    }
                    if (currentInquiryId !== "0" && String(item.kind || "") === "inquiry" && String(item.id || "") === currentInquiryId) {
                        return false;
                    }
                    return (email && item.email && String(item.email).toLowerCase() === email) || (phone && item.phone_digits && String(item.phone_digits) === phone);
                });
            }

            function confirmDuplicateContact(form) {
                if (!form.hasAttribute("data-harmat-deal-editor-form")) {
                    return true;
                }
                if (form.dataset.harmatDuplicateConfirmed === "1") {
                    return true;
                }
                var matches = duplicateMatchesForForm(form).slice(0, 4);
                if (!matches.length) {
                    return true;
                }
                var message = salesCopy.duplicateIntro + "\n\n" + matches.map(function(item) {
                    var contact = item.email || item.phone || "";
                    return "- " + (item.client || salesCopy.noClient) + " / " + (item.source || "") + (contact ? " / " + contact : "");
                }).join("\n") + "\n\n" + salesCopy.duplicateTail;
                if (window.confirm(message)) {
                    form.dataset.harmatDuplicateConfirmed = "1";
                    return true;
                }
                return false;
            }

            function updateLiveDuplicateWarning(form) {
                if (!form.hasAttribute("data-harmat-deal-editor-form")) {
                    return;
                }
                var panel = form.querySelector("[data-harmat-live-duplicate]");
                var list = form.querySelector("[data-harmat-live-duplicate-list]");
                if (!panel || !list) {
                    return;
                }
                var matches = duplicateMatchesForForm(form).slice(0, 6);
                if (!matches.length) {
                    panel.hidden = true;
                    list.innerHTML = "";
                    return;
                }
                list.innerHTML = matches.map(function(item) {
                    var contact = item.email || item.phone || "-";
                    var href = item.url ? String(item.url).replace(/"/g, "&quot;") : "#";
                    return "<a href=\"" + href + "\">" + escapeHtml(item.client || salesCopy.noClient) + " / " + escapeHtml(item.source || "") + " / " + escapeHtml(contact) + "</a>";
                }).join("");
                panel.hidden = false;
            }

            function escapeHtml(value) {
                return String(value || "").replace(/[&<>"']/g, function(char) {
                    return {"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#039;"}[char] || char;
                });
            }

            function registeredPropertiesForSelect(select) {
                try {
                    return JSON.parse(select.getAttribute("data-harmat-property-warnings") || "[]") || [];
                } catch (error) {
                    return [];
                }
            }

            function confirmRegisteredProperty(select) {
                if (!select || !select.hasAttribute("data-harmat-property-warning")) {
                    return true;
                }
                var propertyId = String(select.value || "");
                if (!propertyId || propertyId === "0") {
                    select.dataset.harmatPreviousValue = propertyId;
                    return true;
                }
                var match = registeredPropertiesForSelect(select).filter(function(item) {
                    return String(item.property_id || "") === propertyId;
                })[0];
                if (!match) {
                    select.dataset.harmatPreviousValue = propertyId;
                    return true;
                }
                var detail = (match.items || []).map(function(item) {
                    var line = [item.source || "", item.client || "", item.state || ""].filter(Boolean).join(" / ");
                    return "- " + (line || salesCopy.registered);
                }).join("\n");
                var message = salesCopy.propertyLocked + "\n\n" + (match.property || "") + "\n" + detail + "\n\n" + salesCopy.propertyConfirm;
                if (window.confirm(message)) {
                    select.dataset.harmatPreviousValue = propertyId;
                    return true;
                }
                select.value = select.dataset.harmatPreviousValue || "0";
                return false;
            }

            function initMaterialFileInputs() {
                Array.prototype.forEach.call(document.querySelectorAll("[data-harmat-material-file-input]"), function(input) {
                    var field = input.closest(".harmat-sales-file-field");
                    var display = field ? field.querySelector("[data-harmat-material-file-name]") : null;
                    if (!display) {
                        return;
                    }
                    var emptyText = display.getAttribute("data-empty") || "";
                    var sync = function() {
                        var hasFile = !!(input.files && input.files.length);
                        display.textContent = hasFile ? input.files[0].name : emptyText;
                        display.classList.toggle("has-file", hasFile);
                    };
                    input.addEventListener("change", sync);
                    sync();
                });
            }

            Array.prototype.forEach.call(document.querySelectorAll(".harmat-sales-form"), function(form) {
                if (!form.querySelector("[data-harmat-deal-source]") && !form.querySelector("[data-harmat-payment-method]") && !form.querySelector("[data-harmat-property-warning]")) {
                    return;
                }
                Array.prototype.forEach.call(form.querySelectorAll("[data-harmat-property-warning]"), function(select) {
                    select.dataset.harmatPreviousValue = select.value || "0";
                });
                form.addEventListener("input", function(event) {
                    if (event.target.matches(paymentWatchSelector)) {
                        syncDealForm(form, event.target);
                    }
                    if (event.target.matches("input[name='deal_email'],input[name='deal_phone']")) {
                        updateLiveDuplicateWarning(form);
                    }
                });
                form.addEventListener("change", function(event) {
                    if (event.target.matches("[data-harmat-deal-source],select[name='deal_broker_id'],select[name='deal_stage'],[data-harmat-payment-method],[data-harmat-plan-status]," + paymentWatchSelector)) {
                        syncDealForm(form, event.target);
                    }
                    if (event.target.matches("[data-harmat-property-warning]")) {
                        if (!confirmRegisteredProperty(event.target)) {
                            syncDealForm(form, event.target);
                        }
                    }
                    if (event.target.matches("input[name='deal_email'],input[name='deal_phone']")) {
                        updateLiveDuplicateWarning(form);
                    }
                });
                form.addEventListener("submit", function(event) {
                    if (!confirmDuplicateContact(form)) {
                        event.preventDefault();
                    }
                });
                syncDealForm(form, null);
                updateLiveDuplicateWarning(form);
            });

            initMaterialFileInputs();

            Array.prototype.forEach.call(document.querySelectorAll(".harmat-sales-nav-more"), function(menu) {
                var closeTimer = null;
                menu.addEventListener("mouseleave", function() {
                    closeTimer = window.setTimeout(function() {
                        menu.removeAttribute("open");
                    }, 180);
                });
                menu.addEventListener("mouseenter", function() {
                    if (closeTimer) {
                        window.clearTimeout(closeTimer);
                        closeTimer = null;
                    }
                });
            });
            document.addEventListener("click", function(event) {
                Array.prototype.forEach.call(document.querySelectorAll(".harmat-sales-nav-more[open]"), function(menu) {
                    if (!menu.contains(event.target)) {
                        menu.removeAttribute("open");
                    }
                });
            });
        })();
JS;
    }

