        .harmat-sales-portal-body .harmat-sales-kpis article{border-color:#e7d1aa;box-shadow:0 10px 24px rgba(70,54,28,.045)}
        .harmat-sales-portal-body .harmat-sales-kpis small{letter-spacing:0!important;line-height:1.2!important}
        .harmat-sales-portal-body .harmat-sales-kpis strong{line-height:1.05!important}
        .harmat-sales-portal-body .harmat-sales-table th{letter-spacing:.02em!important}
        .harmat-sales-portal-body .harmat-sales-table td strong{letter-spacing:0}
        .harmat-sales-portal-body .harmat-sales-table tbody tr:hover td{background:#fffaf3}
        .harmat-sales-portal-body .harmat-sales-pill,
        .harmat-sales-portal-body .harmat-sales-assignment-state,
        .harmat-sales-portal-body .harmat-sales-protection{font-weight:900!important;box-shadow:inset 0 0 0 1px rgba(255,255,255,.45)}
        .harmat-sales-portal-body .harmat-sales-deal-focus-item{box-shadow:0 10px 26px rgba(70,54,28,.04)}
