        }
        ';
    }

    private function agent_portal_css() {
        return '
        *{box-sizing:border-box} body.harmat-agent-body{margin:0;background:#fbf4e7;color:#273238;font-family:Montserrat,Arial,"Microsoft YaHei",sans-serif}
